const LS_TEAM_CAMPAIGN = 'winchallenge_team_campaign_v1';
/* Die Kampagnen-Einstellungen des Hosts (welches Spiel, Modus, Runden-Scope, aktuelle Position …)
   lagen bisher nur im Arbeitsspeicher. Ein Reload zwischen zwei Matches/Runden hat sie dadurch
   verloren, wodurch "Nächstes Match" mit einem leeren Spiel abstürzte ("Bitte zuerst ein Spiel
   auswählen"). Werden jetzt zusätzlich lokal gespeichert und beim Wiedereinstieg restauriert. */
function saveTeamCampaignState(){
  if(!myTeam) return;
  try{
    localStorage.setItem(LS_TEAM_CAMPAIGN, JSON.stringify({
      teamId: myTeam.id, teamRoundScope, teamRoundGameChoice, teamRoundGameMode, teamRoundModeChoice,
      teamRoundSessionModeChoice, teamRoundDifficulty, teamRoundCount, teamRoundSelectedGames,
       teamRoundGameSequence, teamRoundGameModeChoices, teamRoundRandomOrder, teamRoundsPerGame, teamRoundFunChallenges, teamRoundCommunityChallenges,
      teamRoundPointGoalChoice, teamRoundCustomGoalValue, teamRoundClassicMode,
      teamCampaignIndex, teamCampaignHistory, teamRoundHeroAssignment, teamRoundHeroLockMode, teamRoundUseHeroFavorites, teamSkippedGames,
    }));
  }catch(e){}
}
function loadTeamCampaignState(teamId){
  try{
    const raw = localStorage.getItem(LS_TEAM_CAMPAIGN);
    if(!raw) return null;
    const data = JSON.parse(raw);
    if(data && data.teamId === teamId) return data;
  }catch(e){}
  return null;
}
function restoreTeamCampaignState(teamId){
  const saved = loadTeamCampaignState(teamId);
  if(!saved) return;
  teamRoundScope = saved.teamRoundScope || teamRoundScope;
  teamRoundGameChoice = saved.teamRoundGameChoice || teamRoundGameChoice;
  teamRoundGameMode = saved.teamRoundGameMode || teamRoundGameMode;
  teamRoundModeChoice = saved.teamRoundModeChoice || teamRoundModeChoice;
  teamRoundSessionModeChoice = saved.teamRoundSessionModeChoice || teamRoundSessionModeChoice;
  teamRoundDifficulty = saved.teamRoundDifficulty || teamRoundDifficulty;
  teamRoundCount = saved.teamRoundCount || teamRoundCount;
  teamRoundSelectedGames = saved.teamRoundSelectedGames || teamRoundSelectedGames;
  teamRoundGameSequence = saved.teamRoundGameSequence || teamRoundGameSequence;
  teamRoundGameModeChoices = saved.teamRoundGameModeChoices || teamRoundGameModeChoices;
  teamRoundRandomOrder = typeof saved.teamRoundRandomOrder === 'boolean' ? saved.teamRoundRandomOrder : teamRoundRandomOrder;
  teamRoundsPerGame = saved.teamRoundsPerGame || teamRoundsPerGame;
   teamRoundFunChallenges = typeof saved.teamRoundFunChallenges === 'boolean' ? saved.teamRoundFunChallenges : teamRoundFunChallenges;
   teamRoundCommunityChallenges = typeof saved.teamRoundCommunityChallenges === 'boolean' ? saved.teamRoundCommunityChallenges : teamRoundCommunityChallenges;
  teamRoundPointGoalChoice = saved.teamRoundPointGoalChoice || teamRoundPointGoalChoice;
  teamRoundCustomGoalValue = saved.teamRoundCustomGoalValue || teamRoundCustomGoalValue;
  teamRoundClassicMode = typeof saved.teamRoundClassicMode === 'boolean' ? saved.teamRoundClassicMode : teamRoundClassicMode;
  teamCampaignIndex = typeof saved.teamCampaignIndex === 'number' ? saved.teamCampaignIndex : teamCampaignIndex;
  teamCampaignHistory = saved.teamCampaignHistory || teamCampaignHistory;
  teamRoundHeroAssignment = saved.teamRoundHeroAssignment || null;
  teamRoundHeroLockMode = saved.teamRoundHeroLockMode || teamRoundHeroLockMode;
  teamRoundUseHeroFavorites = typeof saved.teamRoundUseHeroFavorites === 'boolean' ? saved.teamRoundUseHeroFavorites : teamRoundUseHeroFavorites;
  teamSkippedGames = saved.teamSkippedGames || teamSkippedGames;
}
