function loadSetupState(){ try{ const raw = localStorage.getItem(LS_SETUP); if(raw) return JSON.parse(raw); }catch(e){} return null; }
function clearSetupState(){ try{ localStorage.removeItem(LS_SETUP); }catch(e){} }
function savePlayers(){ try{ localStorage.setItem(LS_PLAYERS, JSON.stringify(globalPlayers)); }catch(e){} }
function loadPlayers(){ try{ const raw = localStorage.getItem(LS_PLAYERS); if(raw) return JSON.parse(raw); }catch(e){} return []; }
const LS_CUSTOM_CHALLENGES = 'winchallenge_custom_challenges_v1';
let customChallengesChannel = null;
function ensureCustomChallengesLive(){
  if(customChallengesChannel || !sb || !currentUser) return;
  customChallengesChannel=sb.channel('custom-challenges-all')
    .on('postgres_changes',{event:'*',schema:'public',table:'custom_games'},()=>loadCustomGamesFromCloud())
    .on('postgres_changes',{event:'*',schema:'public',table:'custom_challenges'},()=>loadCustomChallengesFromCloud())
    .subscribe();
}
function saveCustomChallenges(){ try{ localStorage.setItem(LS_CUSTOM_CHALLENGES, JSON.stringify(customChallenges)); }catch(e){} }
function loadCustomChallenges(){ try{ const raw = localStorage.getItem(LS_CUSTOM_CHALLENGES); if(raw) return JSON.parse(raw); }catch(e){} return {}; }
function addCustomChallenge(gameId, text, diff, scope){
  if(!text || !text.trim()) return;
  customChallenges[gameId] = customChallenges[gameId] || [];
  // Eigene Challenges von anderen Mitspielern landen erst im "wartet auf Freigabe"-Zustand und
  // zählen NICHT im aktiven Pool (siehe rulesPoolFor/personalPoolFor), bis ein Admin sie freigibt.
  // Der Admin selbst kann sich seine eigenen Einträge direkt freischalten.
  const approved = !!(currentUser && currentUser.is_admin);
  const item = { text: text.trim(), diff, scope, id: Date.now()+'-'+Math.random().toString(36).slice(2,7), approved, createdBy: currentUser?currentUser.id:null, createdByName: currentUser?currentUser.username:null };
  customChallenges[gameId].push(item);
  saveCustomChallenges();
  // Cloud-Sync: eigene Challenges gelten für die ganze Gruppe, nicht nur für dieses Gerät.
  if(sb) sb.from('custom_challenges').insert({ id: item.id, game_id: gameId, text: item.text, diff: item.diff, scope: item.scope, approved: item.approved, created_by: item.createdBy, created_by_name: item.createdByName }).then(async ({error})=>{
    if(error){ console.error('Custom-Challenge Cloud-Sync Fehler:', error); showAlert('Challenge konnte nicht zur Freigabe gesendet werden: '+error.message); return; }
    if(!item.approved) await notifyAdminsAboutCustomChallenge(item, gameId);
  });
}
async function notifyAdminsAboutCustomChallenge(item, gameId){
  if(!sb || !currentUser) return;
  try{
    const {data:admins,error}=await sb.from('profiles').select('id').eq('is_admin',true);
    if(error || !admins?.length) return;
    const game=GAME_NAME[gameId] || gameId;
    await sb.from('player_notifications').insert(admins.filter(a=>a.id!==currentUser.id).map(a=>({
      target_user_id:a.id, from_user_id:currentUser.id, icon:'✉',
      message:`Neue Challenge zur Freigabe: ${game} · ${item.diff} · ${item.createdByName||'Spieler'}\n[wc-request:challenge:${item.id}]`
    })));
  }catch(e){ console.warn('Admin-Hinweis für Challenge konnte nicht erstellt werden:',e); }
}
function removeCustomChallenge(gameId, id){
  if(!customChallenges[gameId]) return;
  customChallenges[gameId] = customChallenges[gameId].filter(c=>c.id!==id);
  saveCustomChallenges();
  renderCustomChallengesPage();
  if(sb) sb.from('custom_challenges').delete().eq('id', id).then(({error})=>{ if(error) console.error('Custom-Challenge Lösch-Sync Fehler:', error); });
}
// Lädt die geteilten eigenen Challenges aller Mitspieler aus der Cloud. Falls die Tabelle noch
// nicht existiert (SQL-Migration fehlt) oder kein Supabase verbunden ist, bleibt der bisherige
// rein-lokale Stand unangetastet (stiller Fallback). Beim allerersten erfolgreichen Sync nach dem
// Update: falls die Cloud noch leer ist, aber lokal schon eigene Challenges existieren, werden
// diese einmalig hochgeladen (Migration), statt verworfen zu werden.
async function loadCustomChallengesFromCloud(){
  if(!sb) return;
  try{
    const { data, error } = await sb.from('custom_challenges').select('id, game_id, text, diff, scope, approved, created_by, created_by_name');
    if(error){ console.error('Custom-Challenges Cloud-Load Fehler:', error.message); return; }
    if(data && data.length){
      const merged = {};
      data.forEach(r=>{ merged[r.game_id] = merged[r.game_id] || []; merged[r.game_id].push({ id:r.id, text:r.text, diff:r.diff, scope:r.scope, approved: r.approved !== false, createdBy: r.created_by, createdByName: r.created_by_name }); });
      customChallenges = merged;
      saveCustomChallenges();
    } else {
      const localEntries = Object.entries(customChallenges).flatMap(([gameId, list])=>list.map(c=>({ id:c.id, game_id:gameId, text:c.text, diff:c.diff, scope:c.scope, approved: c.approved!==false, created_by: c.createdBy||null, created_by_name: c.createdByName||null })));
      if(localEntries.length){ const { error: insErr } = await sb.from('custom_challenges').insert(localEntries); if(insErr) console.error('Custom-Challenges Migrations-Sync Fehler:', insErr.message); }
    }
    if(document.getElementById('cc-list') && document.getElementById('view-custom-challenges')?.classList.contains('active')) renderCustomChallengesPage();
  }catch(e){ console.error('Custom-Challenges Cloud-Load Fehler:', e); }
}
let ccSelectedGame = null, ccDiff = 'mittel', ccScope = 'shared';
function renderCustomChallengesPage(){
  if(!ccSelectedGame) ccSelectedGame = GAMES[0].id;
  const gameRow = document.getElementById('cc-game-picker');
  gameRow.innerHTML = '';
  GAMES.filter(g=>g.id!=='wwm').forEach(g=>{
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(g.id===ccSelectedGame?' active':'');
    btn.innerHTML = gameIconHTML(g.id,16)+' '+g.name;
    btn.addEventListener('click', ()=>{ ccSelectedGame = g.id; renderCustomChallengesPage(); });
    gameRow.appendChild(btn);
  });
  const diffRow = document.getElementById('cc-diff-picker');
  diffRow.innerHTML = '';
  [['leicht','LEICHT'],['mittel','MITTEL'],['schwer','SCHWER']].forEach(([k,label])=>{
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(k===ccDiff?' active':'');
    btn.textContent = label;
    btn.addEventListener('click', ()=>{ ccDiff = k; renderCustomChallengesPage(); });
    diffRow.appendChild(btn);
  });
  const scopeRow = document.getElementById('cc-scope-picker');
  scopeRow.innerHTML = '';
  [['shared','🤝 Team-Regel'],['personal','😎 Persönlich (namenbasiert)']].forEach(([k,label])=>{
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(k===ccScope?' active':'');
    btn.textContent = label;
    btn.addEventListener('click', ()=>{ ccScope = k; renderCustomChallengesPage(); });
    scopeRow.appendChild(btn);
  });
  const list = (customChallenges[ccSelectedGame] || []);
  const listEl = document.getElementById('cc-list');
  if(!list.length){
    listEl.innerHTML = '<div class="empty-hint" style="margin-top:16px;">Noch keine eigenen Challenges für dieses Spiel.</div>';
    return;
  }
  let html = `<div class="section-divider">📖 Eure eigenen Challenges für ${GAME_NAME[ccSelectedGame]}</div>`;
  list.forEach(c=>{
    const pendingBadge = c.approved===false ? ' <span style="color:var(--turquoise-bright);font-size:0.75rem;">· ⏳ wartet auf Freigabe</span>' : '';
    html += `<div class="sb-challenge-item">
      <div class="sb-diff-badge" style="background:${DIFF_COLOR[c.diff]}">${DIFF_LABEL[c.diff]}</div>
      <div class="sb-challenge-text">${c.text}${c.scope==='personal'?' <span style="color:var(--text-faint);font-size:0.75rem;">· persönlich</span>':''}${pendingBadge}</div>
      <button class="sb-btn danger" style="padding:6px 10px;" onclick="removeCustomChallenge('${ccSelectedGame}','${c.id}')">✕</button>
    </div>`;
  });
  listEl.innerHTML = html;
}
