let friendProfilesById = {};
let lastFriendsRenderSignature = null;
async function loadFriendLiveStats(friendIds){
  // Live-Werte aus der Overwolf-App (live_game_stats). Rein lesend — falls die Tabelle noch nicht
  // existiert oder leer ist, bleibt die Anzeige einfach normal (kein Fehler für den Nutzer sichtbar).
  const liveStats = {};
  if(!sb || !friendIds?.length) return liveStats;
  try{
    const cutoff = new Date(Date.now()-10*60*1000).toISOString(); // älter als 10 Min. gilt nicht mehr als "live"
    const { data, error } = await sb.from('live_game_stats').select('*').in('user_id', friendIds).eq('is_live', true).gte('updated_at', cutoff);
    if(error || !data) return liveStats;
    data.forEach(row=>{ liveStats[row.user_id] = row; });
  }catch(e){ /* Tabelle evtl. noch nicht angelegt — einfach ignorieren */ }
  return liveStats;
}
async function loadFriendActiveGames(friendIds){
  // Nur lesen: zeigt in der Freundesliste das laufende Spiel, falls die zugehörige
  // Lobby über die bestehenden Berechtigungen sichtbar ist. Fehlende Rechte lassen
  // die Anzeige einfach leer, statt die Freundesliste zu beeinträchtigen.
  const activeGames = {};
  if(!sb || !friendIds?.length) return activeGames;
  try{
    const { data: memberships, error: memberError } = await sb.from('team_members').select('team_id,user_id').in('user_id', friendIds);
    if(memberError || !memberships?.length) throw memberError || new Error('Keine Teammitgliedschaften sichtbar');
    const teamIds = [...new Set(memberships.map(m=>m.team_id))];
    const { data: rounds, error: roundError } = await sb.from('game_rounds').select('team_id,game_id,status,created_at,left_players').in('team_id', teamIds).in('status',['active','voting']).order('created_at',{ascending:false});
    if(roundError || !rounds?.length) return activeGames;
    const activeByTeam = new Map();
    rounds.forEach(round=>{ if(!activeByTeam.has(round.team_id)) activeByTeam.set(round.team_id,round); });
    memberships.forEach(member=>{
      const round = activeByTeam.get(member.team_id);
      if(round && !(round.left_players||[]).includes(member.user_id) && !activeGames[member.user_id]) activeGames[member.user_id] = round.game_id;
    });
  }catch(e){
    // Fallback für die aktuell geöffnete eigene Team-Lobby – die ist immer sichtbar.
  }
  if(myTeam && currentRound && ['active','voting'].includes(currentRound.status)){
    teamMembers.forEach(member=>{
      if(friendIds.includes(member.user_id) && !(currentRound.left_players||[]).includes(member.user_id)) activeGames[member.user_id] = currentRound.game_id;
    });
  }
  return activeGames;
}
async function renderFriendsPage(options={}){
  const quiet = !!options.quiet;
  if(!currentUser || !sb){
    document.getElementById('friend-my-code').textContent = '—';
    document.getElementById('friends-list').innerHTML = '<div class="empty-hint">Bitte zuerst einloggen.</div>';
    return;
  }
  if(!quiet) await reconcileFriendships();
  document.getElementById('friend-my-code').textContent = currentUser.friend_code || '…';
  document.getElementById('friend-invite-hint').style.display = myTeam ? 'block' : 'none';
  document.getElementById('friend-add-warning').textContent = '';
  const listEl = document.getElementById('friends-list');
  if(!quiet && !listEl.children.length) listEl.innerHTML = '<div class="empty-hint">Lädt…</div>';
  try{
    const { data, error } = await sb.from('friendships').select('friend_id, profiles!friendships_friend_id_fkey(id, username, avatar, last_active, bio, favorite_game, preferred_role, preferred_mode, skill_level, stats, equipped_badge, equipped_hat, equipped_banner, equipped_glow, equipped_frame)').eq('user_id', currentUser.id);
    if(error) throw error;
    myFriendIds = new Set((data||[]).map(f=>f.friend_id));
    if(!data || !data.length){
      listEl.innerHTML = '<div class="empty-hint">Noch keine Freunde – füge jemanden über den Freundescode hinzu.</div>';
    } else {
      const friendIds = data.map(f=>f.friend_id);
      const activeGames = await loadFriendActiveGames(friendIds);
      const liveOverwolfStats = await loadFriendLiveStats(friendIds);
      const renderSignature = JSON.stringify(data.map(f=>[
        f.friend_id, f.profiles?.username, f.profiles?.avatar, f.profiles?.last_active,
        f.profiles?.bio, f.profiles?.equipped_badge, f.profiles?.equipped_banner,
        f.profiles?.equipped_hat, f.profiles?.equipped_glow, f.profiles?.equipped_frame,
        activeGames[f.friend_id] || ''
      ]));
      if(quiet && renderSignature === lastFriendsRenderSignature) return;
      lastFriendsRenderSignature = renderSignature;
      const onlineCount = data.filter(f=>f.profiles && isOnline(f.profiles.last_active)).length;
      let html = `<div class="friends-list-head"><strong>Freunde <span class="friends-online-count">(${onlineCount} online)</span></strong><span class="score-sub">Online zuerst</span></div>`;
      const memberIds = myTeam ? new Set(teamMembers.map(m=>m.user_id)) : new Set();
      data.sort((a,b)=>Number(isOnline(b.profiles?.last_active))-Number(isOnline(a.profiles?.last_active))).forEach(f=>{
        const p = f.profiles;
        if(!p) return;
        friendProfilesById[p.id] = p;
        // Kosmetik (Banner/Abzeichen/…) in den geteilten Cache legen, damit cosmeticsFor()/
        // bannerStyleFor() auch für Freunde außerhalb der eigenen Gruppe funktionieren — vorher
        // blieb das Banner auf der Freunde-Seite leer, weil der Cache nur beim Laden von
        // Team-Mitgliedern befüllt wurde.
        remoteCosmeticsCache[p.username] = { badge: p.equipped_badge, hat: p.equipped_hat, banner: p.equipped_banner, glow: p.equipped_glow, frame: p.equipped_frame };
        const friendBanner = cosmeticsFor(p.username).banner;
        const friendBadge = cosmeticsFor(p.username).badge;
        // Freunde, die schon in der aktuellen Gruppe sind, lassen sich nicht nochmal einladen —
        // vorher wurde der Klick trotzdem an inviteFriendToTeam() weitergereicht und ist dort ins
        // Leere gelaufen ("geht nicht" bei Freunden aus derselben Gruppe).
        const alreadyIn = myTeam && memberIds.has(p.id);
        const canInvite = myTeam && !alreadyIn;
        const activeGameId = activeGames[p.id];
        const live = liveOverwolfStats[p.id];
        const activity = live
          ? `<span class="friend-activity is-playing">${gameIconHTML(live.game_id,14)} Spielt live ${GAME_NAME[live.game_id]||live.game_id} · ${live.kills||0}K/${live.deaths||0}D/${live.assists||0}A${live.hero?` · ${live.hero}`:''}</span>`
          : activeGameId
          ? `<span class="friend-activity is-playing">${gameIconHTML(activeGameId,14)} Spielt ${GAME_NAME[activeGameId]||activeGameId}</span>`
          : `<span class="friend-activity">${onlineDotHTML(p.last_active,true)}</span>`;
        html += `<div class="chip readonly member-clickable friend-chip${bannerClassFor(friendBanner)}" style="width:100%;box-sizing:border-box;justify-content:space-between;flex-wrap:wrap;margin-bottom:10px;${friendBanner?bannerStyleFor(friendBanner):''}" onclick="showFriendProfile('${p.id}')" title="Profil von ${p.username} ansehen">
          ${bannerImgTagHTML(friendBanner)}
          <span class="friend-primary" style="position:relative;z-index:2;">${renderAccountAvatarHTML(p.avatar,38)}<span class="friend-identity"><span class="friend-name-line">${badgeIconHTML(friendBadge)}${glowNameHTML(p.username,p.username)} ${onlineDotHTML(p.last_active,false)}</span>${activity}</span></span>
          <span class="friend-actions" style="position:relative;z-index:2;margin-left:auto;">
            ${canInvite?`<button class="sb-btn friend-invite-btn" onclick="event.stopPropagation(); inviteFriendToTeam('${p.id}','${p.username}')">Einladen</button>`:(alreadyIn?'<span style="color:var(--text-faint);font-size:.75rem;">in Lobby</span>':'')}
            <button class="friend-remove-btn" onclick="event.stopPropagation(); openDmFromFriends('${p.id}','${messageEscape(p.username)}')" title="Chat mit ${messageEscape(p.username)}">💬</button>
            <button class="friend-remove-btn" onclick="event.stopPropagation(); removeFriend('${p.id}','${p.username}')" title="Freund entfernen">✕</button>
          </span>
          ${p.bio ? `<span style="position:relative;z-index:2;width:100%;font-size:0.78rem;color:var(--text-muted);font-style:italic;">„${p.bio}"</span>` : ''}
        </div>`;
      });
      listEl.innerHTML = html;
    }
  }catch(e){ listEl.innerHTML = '<div class="empty-hint">Freundesliste konnte nicht geladen werden.</div>'; console.error(e); }
  if(!quiet){
    await materializeAcceptedOutgoingFriendRequests();
    await renderFriendRequests();
    await renderPendingInvites();
  }
}
function showFriendProfile(userId){
  const p = friendProfilesById[userId];
  const modal = document.getElementById('member-profile-modal');
  if(!p || !modal) return;
  const facts = [];
  if(p.favorite_game) facts.push(['🎮 Lieblingsspiel', `${gameIconHTML(p.favorite_game,16)} ${GAME_NAME[p.favorite_game]||p.favorite_game}`]);
  if(p.preferred_role) facts.push(['🎭 Bevorzugte Rolle', PROFILE_ROLE_LABEL[p.preferred_role]||p.preferred_role]);
  if(p.preferred_mode) facts.push(['🤝 Bevorzugter Modus', PROFILE_MODE_LABEL[p.preferred_mode]||p.preferred_mode]);
  if(p.skill_level) facts.push(['📊 Erfahrung', PROFILE_SKILL_LABEL[p.skill_level]||p.skill_level]);
  const factsHTML = facts.length
    ? facts.map(([label,val])=>`<div class="member-modal-fact"><span><span class="fact-label">${label}</span>${val}</span></div>`).join('')
    : `<div class="empty-hint" style="padding:14px;">${p.username} hat noch keine Profilangaben hinterlegt.</div>`;
  const banner = cosmeticsFor(p.username).banner;
  const badge = cosmeticsFor(p.username).badge;
  const isSelf = p.id === currentUser.id;
  modal.innerHTML = `<div class="member-modal-card${bannerClassFor(banner)}" style="${banner ? bannerStyleFor(banner) : ''}" onclick="event.stopPropagation();">
    ${bannerImgTagHTML(banner)}
    ${bannerBadgeStampHTML(banner, badge)}
    <button class="member-modal-close" onclick="event.preventDefault();event.stopPropagation();closeMemberProfileModal()" aria-label="Schließen">✕</button>
    ${profileQuickEditButton(isSelf)}
    <div class="member-modal-avatar">${withHatOverlay(p.username, renderAccountAvatarHTML(p.avatar,52), 52)}</div>
    <div class="member-modal-name">${badgeIconHTML(badge)}${glowNameHTML(p.username,p.username)}</div>
    ${p.bio ? `<div class="member-modal-bio">„${p.bio}“</div>` : ''}
    <div class="score-sub" style="margin-top:4px;">${onlineDotHTML(p.last_active, true)} Freundesprofil</div>
    <div class="member-modal-facts">${factsHTML}</div>
    ${renderMemberStatsSummaryHTML({username:p.username, stats:p.stats})}
    ${renderMemberHeroFavoritesHTML(p)}
    <div class="empty-hint" style="margin-top:14px;">💡 Tippe in der Freundesliste auf „Einladen“, um ${p.username} in deine aktuelle Team-Lobby zu holen.</div>
  </div>`;
  modal.classList.remove('hidden');
}
// ===== Freundschaftsanfragen (statt direktem Hinzufügen) =====
// Wichtig: Row-Level-Security lässt jeden Nutzer immer nur SEINE EIGENE Zeile in "friendships"
// anlegen (auth.uid() = user_id) — man kann also nicht beide Richtungen auf einmal in einem
// Rutsch eintragen. Genau daran scheiterte "Freund per Code hinzufügen" bisher lautlos: der
// zweite upsert für die Gegenseite wurde von der Datenbank stillschweigend verworfen, ohne dass
// das im UI auffiel. Jetzt läuft es über eine eigene Tabelle "friend_requests" (from_user,
// to_user, status) — Anfrage stellen, Gegenseite nimmt an oder lehnt ab, und beide Seiten legen
// danach JEWEILS NUR IHRE EIGENE friendships-Zeile an (siehe materializeAcceptedOutgoingFriendRequests).
// ERFORDERT Supabase-Tabelle+Policies, siehe SQL-Hinweis im Chat.
// Räumt einseitig "übrig gebliebene" Freundschaften auf: wurde ich entfernt, während ich offline
// war (App zu, kein Realtime-Event angekommen), bleibt meine eigene friendships-Zeile sonst für
// immer stehen, weil die Gegenseite meine Zeile aus RLS-Gründen nicht selbst löschen darf. Läuft
// bei jedem Öffnen der Freunde-Seite: für jede Freundschaft, die ICH eingetragen habe, wird
// geprüft, ob die Gegenseite ihre Zeile noch hat — falls nicht, war ich offline beim Entfernen und
// räume jetzt selbst auf.
async function reconcileFriendships(){
  if(!currentUser || !sb) return;
  try{
    const [{ data: mine, error: e1 }, { data: theirs, error: e2 }] = await Promise.all([
      sb.from('friendships').select('friend_id').eq('user_id', currentUser.id),
      sb.from('friendships').select('user_id').eq('friend_id', currentUser.id)
    ]);
    if(e1 || e2 || !mine || !mine.length) return;
    const reciprocated = new Set((theirs||[]).map(r=>r.user_id));
    const candidates = mine.map(r=>r.friend_id).filter(fid=>!reciprocated.has(fid));
    if(!candidates.length) return;
    // Nicht sofort löschen: eine einseitige Freundschaft ist nicht automatisch "entfernt" — direkt
    // nach dem Annehmen einer Anfrage legt erstmal nur die annehmende Seite ihre Zeile an, die
    // andere Seite holt das erst beim nächsten Öffnen der Freunde-Seite nach (siehe
    // materializeAcceptedOutgoingFriendRequests). Solange dafür noch eine friend_requests-Zeile
    // zwischen den beiden existiert (egal welcher Status), ist das nur dieser Übergangszustand und
    // keine echte Entfernung — sonst würde man dem anderen die frisch angenommene Freundschaft
    // gleich wieder wegräumen, bevor er selbst nachziehen konnte.
    const orExpr = candidates.map(fid=>`and(from_user.eq.${currentUser.id},to_user.eq.${fid}),and(from_user.eq.${fid},to_user.eq.${currentUser.id})`).join(',');
    const { data: inFlight } = await sb.from('friend_requests').select('from_user,to_user').or(orExpr);
    const inFlightIds = new Set();
    (inFlight||[]).forEach(r=>{ inFlightIds.add(r.from_user===currentUser.id ? r.to_user : r.from_user); });
    const stale = candidates.filter(fid=>!inFlightIds.has(fid));
    for(const fid of stale){
      await sb.from('friendships').delete().eq('user_id', currentUser.id).eq('friend_id', fid);
    }
  }catch(e){ console.error(e); }
}
async function removeFriend(friendId, friendUsername){
  if(!currentUser || !sb) return;
  if(!(await confirmAction(`${friendUsername} wirklich als Freund entfernen?`))) return;
  try{
    // Eigene Zeile geht sicher (RLS erlaubt das immer) — die Gegenrichtung entfernen wir im
    // gleichen Rutsch mit, falls die Policy das zulässt; falls nicht, verschwindet der Freund
    // trotzdem sofort aus der eigenen Liste.
    await sb.from('friendships').delete().eq('user_id', currentUser.id).eq('friend_id', friendId);
    await sb.from('friendships').delete().eq('user_id', friendId).eq('friend_id', currentUser.id);
  }catch(e){ console.error(e); }
  await renderFriendsPage();
}
async function sendFriendRequest(targetId, targetUsername){
  if(!currentUser || !sb) return { ok:false, msg:'Nicht eingeloggt.' };
  if(targetId === currentUser.id) return { ok:false, msg:'Das bist du selbst.' };
  try{
    const { data: already } = await sb.from('friendships').select('user_id').eq('user_id', currentUser.id).eq('friend_id', targetId).maybeSingle();
    if(already) return { ok:false, msg: `${targetUsername} ist schon dein Freund.` };
    const { data: existing } = await sb.from('friend_requests').select('id, from_user, to_user, status')
      .or(`and(from_user.eq.${currentUser.id},to_user.eq.${targetId}),and(from_user.eq.${targetId},to_user.eq.${currentUser.id})`).maybeSingle();
    if(existing && existing.status === 'pending'){
      if(existing.from_user === targetId){
        // Die andere Seite hat euch schon angefragt — direkt annehmen statt doppelt anzufragen.
        await acceptFriendRequest(existing.id, targetId, true);
        return { ok:true, msg: `${targetUsername} ist jetzt dein Freund (ihr hattet euch gegenseitig angefragt).` };
      }
      return { ok:false, msg: `Anfrage an ${targetUsername} läuft schon.` };
    }
    const { error } = await sb.from('friend_requests').insert({ from_user: currentUser.id, to_user: targetId, status:'pending' });
    if(error) throw error;
    return { ok:true, msg: `Freundschaftsanfrage an ${targetUsername} gesendet.` };
  }catch(e){ return { ok:false, msg: 'Fehler: ' + e.message }; }
}
async function addFriendByCode(){
  const input = document.getElementById('friend-code-input');
  const warn = document.getElementById('friend-add-warning');
  warn.style.color = 'var(--lose)'; warn.textContent = '';
  const code = input.value.trim().toUpperCase();
  if(!code){ warn.textContent = 'Bitte einen Freundescode eingeben.'; return; }
  if(!currentUser || !sb) return;
  try{
    const { data, error } = await sb.from('profiles').select('id, username').eq('friend_code', code).maybeSingle();
    if(error || !data){ warn.textContent = 'Kein Account mit diesem Code gefunden.'; return; }
    const result = await sendFriendRequest(data.id, data.username);
    if(!result.ok){ warn.textContent = result.msg; return; }
    input.value = '';
    warn.style.color = 'var(--win)'; warn.textContent = result.msg;
    await renderFriendRequests();
  }catch(e){ warn.textContent = 'Fehler: ' + e.message; }
}
async function searchFriendsByName(){
  const input = document.getElementById('friend-search-input');
  const warn = document.getElementById('friend-search-warning');
  const resultsEl = document.getElementById('friend-search-results');
  warn.textContent = ''; resultsEl.innerHTML = '';
  const q = input.value.trim();
  if(!q){ warn.textContent = 'Bitte einen Namen eingeben.'; return; }
  if(!currentUser || !sb) return;
  resultsEl.innerHTML = '<div class="empty-hint">Sucht…</div>';
  try{
    const { data, error } = await sb.from('profiles').select('id, username, avatar').ilike('username', `%${q}%`).neq('id', currentUser.id).limit(10);
    if(error) throw error;
    if(!data || !data.length){ resultsEl.innerHTML = '<div class="empty-hint">Niemand mit diesem Namen gefunden.</div>'; return; }
    resultsEl.innerHTML = data.map(p=>`<div class="chip readonly" style="width:100%;box-sizing:border-box;justify-content:space-between;">
      <span>${renderAccountAvatarHTML(p.avatar,20)} ${p.username}</span>
      <button class="header-menu-btn" style="width:auto;border-radius:14px;padding:0 10px;font-size:0.72rem;" onclick="sendFriendRequestFromSearch('${p.id}','${p.username}')">➕ Anfragen</button>
    </div>`).join('');
  }catch(e){ resultsEl.innerHTML = '<div class="empty-hint">Suche fehlgeschlagen.</div>'; console.error(e); }
}
async function sendFriendRequestFromSearch(targetId, targetUsername){
  const result = await sendFriendRequest(targetId, targetUsername);
  showAlert(result.msg, result.ok ? '🤝' : '⚠️');
  if(result.ok){
    document.getElementById('friend-search-results').innerHTML = '';
    document.getElementById('friend-search-input').value = '';
    await renderFriendRequests();
  }
}
async function inviteFriendToTeam(friendUserId, friendUsername){
  if(!myTeam || !currentUser || !sb) return;
  if(teamMembers.some(m=>m.user_id===friendUserId)){ showAlert(`${friendUsername} ist schon in eurer Gruppe.`, 'ℹ️'); return; }
  try{
    const { error } = await sb.from('team_invites').insert({ team_id: myTeam.id, from_user: currentUser.id, to_user: friendUserId, status: 'pending' });
    if(error) throw error;
    showAlert(`Einladung an ${friendUsername} verschickt.`, '📨');
  }catch(e){ showAlert('Einladung konnte nicht verschickt werden: ' + e.message, '⚠️'); }
}
// Eingehende UND ausgehende Freundschaftsanfragen — getrennt von Team-Einladungen weiter unten.
async function renderFriendRequests(){
  const divider = document.getElementById('friend-requests-divider');
  const inEl = document.getElementById('friend-requests-incoming');
  const outEl = document.getElementById('friend-requests-outgoing');
  if(!currentUser || !sb){ divider.style.display='none'; inEl.innerHTML=''; outEl.innerHTML=''; return; }
  try{
    const [{ data: incoming, error: e1 }, { data: outgoing, error: e2 }] = await Promise.all([
      sb.from('friend_requests').select('id, from_user, profiles!friend_requests_from_user_fkey(username, avatar)').eq('to_user', currentUser.id).eq('status','pending'),
      sb.from('friend_requests').select('id, to_user, profiles!friend_requests_to_user_fkey(username, avatar)').eq('from_user', currentUser.id).eq('status','pending'),
    ]);
    if(e1) throw e1; if(e2) throw e2;
    const hasAny = (incoming && incoming.length) || (outgoing && outgoing.length);
    divider.style.display = hasAny ? 'block' : 'none';
    inEl.innerHTML = (incoming||[]).map(r=>`<div class="settings-row-btn" style="margin-bottom:8px;">
      <span class="settings-row-icon">🤝</span>
      <span class="settings-row-text"><span class="settings-row-title">${r.profiles?r.profiles.username:'?'} möchte befreundet sein</span></span>
      <button class="sb-btn" style="padding:8px 12px;" onclick="acceptFriendRequest('${r.id}','${r.from_user}')">✅</button>
      <button class="sb-btn danger" style="padding:8px 12px;" onclick="declineFriendRequest('${r.id}')">❌</button>
    </div>`).join('');
    outEl.innerHTML = (outgoing||[]).map(r=>`<div class="settings-row-btn" style="margin-bottom:8px;opacity:0.75;">
      <span class="settings-row-icon">⏳</span>
      <span class="settings-row-text"><span class="settings-row-title">Anfrage an ${r.profiles?r.profiles.username:'?'}</span><span class="settings-row-sub">Wartet auf Bestätigung</span></span>
      <button class="sb-btn danger" style="padding:8px 12px;" onclick="declineFriendRequest('${r.id}')">Zurückziehen</button>
    </div>`).join('');
  }catch(e){ console.error(e); }
}
async function acceptFriendRequest(requestId, fromUserId, skipRerender){
  if(!currentUser || !sb) return;
  try{
    await sb.from('friend_requests').update({ status:'accepted' }).eq('id', requestId);
    // Nur die eigene Zeile anlegen — die Gegenseite legt ihre eigene beim nächsten Öffnen der
    // Freunde-Seite an (materializeAcceptedOutgoingFriendRequests), RLS verbietet Fremdzeilen.
    await sb.from('friendships').upsert({ user_id: currentUser.id, friend_id: fromUserId }, { onConflict:'user_id,friend_id' });
    myFriendIds.add(fromUserId);
  }catch(e){ console.error(e); }
  if(!skipRerender) await renderFriendsPage();
}
async function declineFriendRequest(requestId){
  if(!sb) return;
  try{ await sb.from('friend_requests').update({ status:'declined' }).eq('id', requestId); }catch(e){ console.error(e); }
  await renderFriendRequests();
}
// Wer eine Anfrage GESCHICKT hat, sieht hier (beim Öffnen der Freunde-Seite), ob sie inzwischen
// angenommen wurde, und legt dann selbst seine eigene friendships-Zeile an (siehe Kommentar oben).
async function materializeAcceptedOutgoingFriendRequests(){
  if(!currentUser || !sb) return;
  try{
    const { data, error } = await sb.from('friend_requests').select('id, to_user').eq('from_user', currentUser.id).eq('status','accepted');
    if(error || !data || !data.length) return;
    for(const r of data){
      await sb.from('friendships').upsert({ user_id: currentUser.id, friend_id: r.to_user }, { onConflict:'user_id,friend_id' });
      await sb.from('friend_requests').delete().eq('id', r.id);
    }
  }catch(e){ console.error(e); }
}
async function renderPendingInvites(){
  const divider = document.getElementById('friend-invites-divider');
  const listEl = document.getElementById('friend-invites-list');
  if(!currentUser || !sb){ divider.style.display='none'; listEl.innerHTML=''; return; }
  try{
    // Einladungen sind nur 24 Stunden gültig. Der Zeitfilter verhindert, dass alte
    // Einladungen noch sichtbar/annahmbar sind; die DELETE-Anfrage räumt sie bei
    // geöffneter App zusätzlich direkt aus der Tabelle.
    const expiresBefore = new Date(Date.now()-24*60*60*1000).toISOString();
    await sb.from('team_invites').delete().eq('to_user', currentUser.id).eq('status','pending').lt('created_at', expiresBefore);
    const { data, error } = await sb.from('team_invites').select('id, team_id, status, created_at, teams(name, code), profiles!team_invites_from_user_fkey(username)').eq('to_user', currentUser.id).eq('status','pending').gte('created_at', expiresBefore);
    if(error) throw error;
    if(!data || !data.length){ divider.style.display='none'; listEl.innerHTML=''; return; }
    divider.style.display = 'block';
    let html = '';
    data.forEach(inv=>{
      html += `<div class="settings-row-btn" style="margin-bottom:8px;">
        <span class="settings-row-icon">📨</span>
        <span class="settings-row-text"><span class="settings-row-title">${inv.profiles?inv.profiles.username:'?'} lädt dich ein</span><span class="settings-row-sub">${inv.teams?inv.teams.name||'Team':'Team'}</span></span>
        <button class="sb-btn" style="padding:8px 12px;" onclick="acceptTeamInvite('${inv.id}','${inv.teams?inv.teams.code:''}')">✅</button>
        <button class="sb-btn danger" style="padding:8px 12px;" onclick="declineTeamInvite('${inv.id}')">❌</button>
      </div>`;
    });
    listEl.innerHTML = html;
  }catch(e){ console.error(e); }
}
async function acceptTeamInvite(inviteId, teamCode){
  if(!teamCode){ showAlert('Dieses Team existiert nicht mehr.', '⚠️'); return; }
  await sb.from('team_invites').update({ status: 'accepted' }).eq('id', inviteId);
  await joinTeam(teamCode);
  showView('team');
}
async function declineTeamInvite(inviteId){
  if(!sb) return;
  try{ await sb.from('team_invites').update({ status: 'declined' }).eq('id', inviteId); }catch(e){ console.error(e); }
  await renderPendingInvites();
}
function togglePref(key){
  userPrefs[key] = !userPrefs[key];
  savePrefs();
  applyUserPrefs();
  if(key==='showOnlineStatus'){
    if(userPrefs.showOnlineStatus) startPresenceHeartbeat();
    else stopPresenceHeartbeat();
  }
  renderUserSettingsPage();
}
// Schalter in den Einstellungen sollen nicht mehr direkt beim Antippen umschalten, sondern
// erst ein kleines Menü mit An/Aus öffnen (gleiches Popup wie bei den Team-Auswahlen).
function openPrefToggleModal(key, rowEl){
  const icon = (rowEl && rowEl.querySelector('.settings-row-icon')) ? rowEl.querySelector('.settings-row-icon').textContent : '⚙️';
  const title = (rowEl && rowEl.querySelector('.settings-row-title')) ? rowEl.querySelector('.settings-row-title').textContent : 'Einstellung';
  openTeamPickerModal(icon, title, ()=>renderPrefToggleModalContent(key));
}
function renderPrefToggleModalContent(key){
  const val = !!userPrefs[key];
  return `<div class="filter-row">
    <button class="filter-pill${val?' active':''}" onclick="setPrefValue('${key}', true)">✅ An</button>
    <button class="filter-pill${!val?' active':''}" onclick="setPrefValue('${key}', false)">❌ Aus</button>
  </div>`;
}
function setPrefValue(key, value){
  value = !!value;
  if(!!userPrefs[key] === value){ closeTeamPickerModal(); return; }
  userPrefs[key] = value;
  savePrefs();
  applyUserPrefs();
  if(key==='showOnlineStatus'){
    if(userPrefs.showOnlineStatus) startPresenceHeartbeat();
    else stopPresenceHeartbeat();
  }
  renderUserSettingsPage();
  closeTeamPickerModal();
}
function cycleFontScale(){
  const values = ['normal','large','larger'];
  const current = values.indexOf(userPrefs.fontScale||'normal');
  userPrefs.fontScale = values[(current+1)%values.length];
  savePrefs();
  applyUserPrefs();
  renderUserSettingsPage();
}
function applyUserPrefs(){
  const root = document.documentElement;
  const scale = userPrefs.fontScale||'normal';
  root.style.fontSize = scale==='large' ? '17px' : scale==='larger' ? '18px' : '';
  document.body.classList.toggle('wc-reduced-motion', !!userPrefs.reducedMotion);
  document.body.classList.toggle('wc-high-contrast', !!userPrefs.highContrast);
}
function renderUserSettingsPage(){
  ['confirmDialogs','animations','soundVibration','chatNotifications','inviteNotifications','messageNotifications','showTierStatus','showUniqueQuote','showOnlineStatus','publicProfile','allowFriendRequests','reducedMotion','highContrast'].forEach(key=>{
    const el = document.getElementById('pref-toggle-'+key);
    if(el) el.textContent = userPrefs[key] ? '✅ An' : '❌ Aus';
  });
  const scaleLabel = document.getElementById('pref-fontScale-label');
  if(scaleLabel) scaleLabel.textContent = ({normal:'Standard',large:'Groß',larger:'Sehr groß'})[userPrefs.fontScale||'normal'];
  const row = document.getElementById('pref-defaulttab-picker');
  if(row){
    row.innerHTML = '';
    [['home','🚀 Startseite'],['start-choice','🎮 Direkt zu Spiel starten']].forEach(([k,label])=>{
      const btn = document.createElement('button');
      btn.className = 'filter-pill'+(userPrefs.defaultTab===k?' active':'');
      btn.textContent = label;
      btn.addEventListener('click', ()=>{ userPrefs.defaultTab = k; savePrefs(); renderUserSettingsPage(); });
      row.appendChild(btn);
    });
  }
}
function submitCustomChallenge(){
  const input = document.getElementById('cc-text-input');
  const text = input.value.trim();
  if(!text){ showAlert('Bitte einen Text für die Challenge eingeben.', '📝'); return; }
  addCustomChallenge(ccSelectedGame, text, ccDiff, ccScope);
  input.value = '';
  renderCustomChallengesPage();
}
const LS_PREFS = 'winchallenge_prefs_v1';
function savePrefs(){
  try{ localStorage.setItem(LS_PREFS, JSON.stringify(userPrefs)); }catch(e){}
  syncUserPrefsCloud();
}
async function syncUserPrefsCloud(){
  if(!sb || !currentUser?.id) return;
  try{
    await sb.from('user_preferences').upsert({user_id:currentUser.id,settings:userPrefs,updated_at:new Date().toISOString()},{onConflict:'user_id'});
  }catch(e){ console.warn('Einstellungen wurden lokal gespeichert; Cloud-Abgleich ist noch nicht eingerichtet.',e.message); }
}
async function loadUserPrefsCloud(){
  if(!sb || !currentUser?.id) return;
  try{
    const {data,error}=await sb.from('user_preferences').select('settings').eq('user_id',currentUser.id).maybeSingle();
    if(error || !data?.settings) return;
    userPrefs=Object.assign(loadPrefs(),data.settings);
    try{ localStorage.setItem(LS_PREFS,JSON.stringify(userPrefs)); }catch(e){}
    applyUserPrefs();
    renderUserSettingsPage();
  }catch(e){ console.warn('Cloud-Einstellungen konnten nicht geladen werden.',e.message); }
}
let userPrefsChannel = null;
function ensureUserPrefsLive(){
  if(userPrefsChannel || !sb || !currentUser?.id) return;
  userPrefsChannel=sb.channel('user-preferences-'+currentUser.id)
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'user_preferences',filter:'user_id=eq.'+currentUser.id},()=>loadUserPrefsCloud())
    .subscribe();
}
function loadPrefs(){
  const defaults = { confirmDialogs:true, animations:true, soundVibration:true, chatNotifications:true, inviteNotifications:true, messageNotifications:true, defaultTab:'home', showTierStatus:true, showUniqueQuote:true, showOnlineStatus:true, publicProfile:true, allowFriendRequests:true, reducedMotion:false, highContrast:false, fontScale:'normal' };
  try{ const raw = localStorage.getItem(LS_PREFS); if(raw) return Object.assign(defaults, JSON.parse(raw)); }catch(e){}
  return defaults;
}
function togglePasswordVisibility(inputId, btn){
  const input = document.getElementById(inputId);
  if(!input) return;
  const showing = input.type === 'text';
  input.type = showing ? 'password' : 'text';
  btn.textContent = showing ? '👁️' : '🙈';
  btn.setAttribute('aria-label', showing ? 'Passwort anzeigen' : 'Passwort verbergen');
}
function confirmAction(msg, icon){
  if(!userPrefs.confirmDialogs) return Promise.resolve(true);
  return new Promise(resolve=>{
    document.getElementById('custom-confirm-icon').textContent = icon || '❓';
    document.getElementById('custom-confirm-message').textContent = msg;
    const backdrop = document.getElementById('custom-confirm-backdrop');
    backdrop.classList.remove('hidden');
    const okBtn = document.getElementById('custom-confirm-ok');
    const cancelBtn = document.getElementById('custom-confirm-cancel');
    const cleanup = (result)=>{
      backdrop.classList.add('hidden');
      okBtn.removeEventListener('click', onOk);
      cancelBtn.removeEventListener('click', onCancel);
      resolve(result);
    };
    const onOk = ()=>cleanup(true);
    const onCancel = ()=>cleanup(false);
    okBtn.addEventListener('click', onOk);
    cancelBtn.addEventListener('click', onCancel);
  });
}
function playStartCue(){
  if(!userPrefs.soundVibration) return;
  try{ if(navigator.vibrate) navigator.vibrate([70,40,70]); }catch(e){}
  try{
    const ctx = new (window.AudioContext||window.webkitAudioContext)();
    const osc = ctx.createOscillator(); const gain = ctx.createGain();
    osc.type = 'sine'; osc.frequency.setValueAtTime(680, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(980, ctx.currentTime+0.16);
    gain.gain.setValueAtTime(0.16, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+0.32);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(); osc.stop(ctx.currentTime+0.34);
  }catch(e){}
}
