function avatarFor(name){
  // Für den eigenen eingeloggten Account ist currentUser.avatar die einzige verlässliche Quelle
  // (aus Supabase synchronisiert). avatarMap ist nur ein lokaler Cache — der nach dem automatischen
  // Vergeben des Blutmond-Emblems (100% Achievements) veraltet bleiben konnte und dadurch z.B. im
  // Shop weiterhin das Emblem zeigte, obwohl inzwischen ein anderer Avatar gewählt wurde.
  if(currentUser && name===currentUser.username){
    const cur = currentUser.avatar || '😎';
    if(avatarMap[name] !== cur){ avatarMap[name] = cur; saveAvatars(); }
    return cur;
  }
  if(!avatarMap[name]){
    const def = ICON_AVATARS[Math.abs(hashHue(name)) % ICON_AVATARS.length];
    avatarMap[name] = 'icon:'+def.id;
    saveAvatars();
  }
  return avatarMap[name];
}
function avatarHTML(name, size){
  size = size || 26;
  const val = avatarFor(name);
  if(typeof val === 'string' && (val.indexOf('data:image') === 0 || val.indexOf('asset:') === 0)){
    const src = val.indexOf('asset:') === 0 ? val.slice(6) : val;
    return `<img src="${src}" style="width:${size}px;height:${size}px;border-radius:8px;object-fit:cover;vertical-align:middle;">`;
  }
  if(typeof val === 'string' && val.indexOf('icon:') === 0){
    const def = ICON_AVATARS.find(i=>'icon:'+i.id===val) || ICON_AVATARS[0];
    const s = Math.round(size*0.62);
    return `<span style="display:inline-flex;align-items:center;justify-content:center;width:${size}px;height:${size}px;border-radius:8px;background:${def.color};vertical-align:middle;"><svg viewBox="0 0 24 24" width="${s}" height="${s}">${ICON_SVG[def.id]}</svg></span>`;
  }
  if(typeof val === 'string' && (val.indexOf('hero:') === 0 || val.indexOf('game:') === 0)){
    // Kommt von einem synchronisierten Online-Account-Avatar (Helden-Bild oder Spiel-Icon) —
    // dieselbe Auflösung wie renderAccountAvatarHTML nutzen, statt den rohen String zu zeigen.
    return renderAccountAvatarHTML(val, size);
  }
  return `<span style="font-size:${Math.round(size*0.75)}px;">${val}</span>`;
}
