function resizeImageToDataUrl(file, size, cb){
  const reader = new FileReader();
  reader.onload = ev=>{
    const img = new Image();
    img.onload = ()=>{
      const canvas = document.createElement('canvas'); canvas.width = size; canvas.height = size;
      const ctx = canvas.getContext('2d');
      const s = Math.min(img.width, img.height);
      ctx.drawImage(img, (img.width-s)/2, (img.height-s)/2, s, s, 0, 0, size, size);
      cb(canvas.toDataURL('image/jpeg', 0.85));
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}
document.getElementById('avatar-upload-input').addEventListener('change', e=>{
  const file = e.target.files[0]; if(!file || !editingAvatarPlayer) return;
  resizeImageToDataUrl(file, 128, dataUrl=>{
    avatarMap[editingAvatarPlayer] = dataUrl; saveAvatars();
    renderAvatarPickerGrid(); renderGlobalPlayerChips();
    e.target.value = '';
  });
});

