async function subscribeTeam(teamId){
  if(!sb) return;
  if(teamChannel) sb.removeChannel(teamChannel);
  teamChannel = sb.channel('team-'+teamId)
    .on('broadcast', { event:'card-effect' }, ({payload})=>{ if(payload) showTeamCardEffect(payload); })
    .on('broadcast', { event:'pikachu-sound' }, ({payload})=>{ playPikachuGroupSound(payload); })
    .on('broadcast', { event:'risk-card-invite' }, ({payload})=>{ if(payload && window.receiveRiskCardInvite) window.receiveRiskCardInvite(payload); })
    .on('broadcast', { event:'risk-card-vote' }, ({payload})=>{ if(payload && window.receiveRiskCardVote) window.receiveRiskCardVote(payload); })
    .on('broadcast', { event:'risk-card-rolling' }, ({payload})=>{ if(payload && window.receiveRiskCardRolling) window.receiveRiskCardRolling(payload); })
    .on('broadcast', { event:'risk-card-result' }, ({payload})=>{ if(payload && window.receiveRiskCardResult) window.receiveRiskCardResult(payload); })
    .on('broadcast', { event:'reaction-duel-invite' }, ({payload})=>{ if(payload && window.receiveReactionDuelInvite) window.receiveReactionDuelInvite(payload); })
    .on('broadcast', { event:'reaction-duel-ready' }, ({payload})=>{ if(payload && window.receiveReactionDuelReady) window.receiveReactionDuelReady(payload); })
    .on('broadcast', { event:'reaction-duel-start' }, ({payload})=>{ if(payload && window.receiveReactionDuelStart) window.receiveReactionDuelStart(payload); })
    .on('broadcast', { event:'reaction-duel-click' }, ({payload})=>{ if(payload && window.receiveReactionDuelClick) window.receiveReactionDuelClick(payload); })
    .on('broadcast', { event:'reaction-duel-result' }, ({payload})=>{ if(payload && window.receiveReactionDuelResult) window.receiveReactionDuelResult(payload); })
    .on('broadcast', { event:'number-guess-start' }, ({payload})=>{ if(payload && window.receiveNumberGuessStart) window.receiveNumberGuessStart(payload); })
    .on('broadcast', { event:'number-guess-choice' }, ({payload})=>{ if(payload && window.receiveNumberGuessChoice) window.receiveNumberGuessChoice(payload); })
    .on('broadcast', { event:'number-guess-result' }, ({payload})=>{ if(payload && window.receiveNumberGuessResult) window.receiveNumberGuessResult(payload); })
    .on('postgres_changes', { event:'*', schema:'public', table:'team_members', filter:`team_id=eq.${teamId}` }, ()=>{ refreshTeamMembers(); })
    .on('postgres_changes', { event:'*', schema:'public', table:'teams', filter:`id=eq.${teamId}` }, ()=>{ refreshTeamDraftSettings(); })
    .on('postgres_changes', { event:'*', schema:'public', table:'game_rounds', filter:`team_id=eq.${teamId}` }, ()=>{ checkActiveRound(); })
    .on('postgres_changes', { event:'*', schema:'public', table:'round_items' }, ()=>{ debouncedRoundItemsRefresh(); })
    .on('postgres_changes', { event:'*', schema:'public', table:'round_votes' }, ()=>{ debouncedRoundItemsRefresh(); })
    .subscribe((status)=>{
      if(status === 'CHANNEL_ERROR' || status === 'TIMED_OUT'){
        console.warn('Team-Realtime nicht verbunden (Status: '+status+'). Prüfe in Supabase unter Database → Replication. Live-Updates laufen währenddessen per Polling weiter.');
      }
    });
  // Warten, bis der erste Rundenstatus-Check durch ist, bevor Aufrufer (z. B. restoreMyTeam)
  // sich auf currentRound verlassen — sonst zeigt der "Zurück zum Spiel"-Button nach einem
  // Neuladen kurzzeitig fälschlich "keine aktive Session" an.
  await checkActiveRound();
  await refreshTeamDraftSettings();
  startTeamPolling();
}
function showTeamCardEffect(payload){
  const visuals={
    mirror:'🪞', team_shield:'🛡️', spy_glass:'🔍', hero_steal:'🔄', force_reroll:'🎲',
    lock_joker:'🚫', point_thief:'🦝', delete_challenge:'🗑️', team_spirit:'🤝', lucky:'🍀',
    extra_hard:'💀', hero_pick:'🎯', reaction_duel:'⚡', risk_card:'🎲', number_guess:'🔢'
  };
  const previous = document.querySelector('.team-card-effect');
  if(previous) previous.remove();
  const layer = document.createElement('div');
  layer.className = 'team-card-effect effect-'+String(payload.id||'generic').replace(/[^a-z0-9_-]/gi,'');
  layer.style.cssText='position:fixed!important;inset:0!important;z-index:2147483647!important;display:flex!important;align-items:center!important;justify-content:center!important;opacity:1!important;background:radial-gradient(circle,rgba(34,211,209,.14),rgba(4,5,12,.08) 52%,rgba(4,5,12,.18))!important;backdrop-filter:blur(1px)!important;pointer-events:none!important;';
  const card = document.createElement('div'); card.className='team-card-effect-card';
  card.style.cssText='width:min(540px,90vw)!important;padding:18px!important;background:transparent!important;border:0!important;box-shadow:none!important;text-shadow:0 3px 18px #000,0 0 26px rgba(34,211,209,.9)!important;';
  const iconAnimations={mirror:'mirror-icon-kf 1.6s ease-out',team_shield:'shield-icon-kf 1.3s cubic-bezier(.15,1.2,.35,1)',spy_glass:'spy-icon-kf 1.7s ease-out',hero_steal:'swap-icon-kf 1.3s ease-in-out',force_reroll:'dice-icon-kf 1.35s ease-in-out',risk_card:'dice-icon-kf 1.35s ease-in-out',lock_joker:'lock-icon-kf 1.2s ease-out',point_thief:'coin-icon-kf 1.25s ease-out',delete_challenge:'strike-icon-kf 1.1s ease-out',reaction_duel:'lightning-icon-kf .52s steps(2) 2',lucky:'luck-icon-kf 1.6s ease-in-out',team_spirit:'luck-icon-kf 1.6s ease-in-out'};
  const icon = document.createElement('div'); icon.className='team-card-effect-icon'; icon.style.cssText=`font-size:clamp(7rem,19vw,14rem)!important;filter:drop-shadow(0 0 26px rgba(34,211,209,.95))!important;animation:${iconAnimations[payload.id]||'team-card-pop .42s cubic-bezier(.2,1.2,.4,1) forwards'};`;
  if(payload.id==='pikachu') icon.innerHTML=`<img src="${payload.image||'assets/pikachu-50-avatar.gif'}" alt="Pikachu" style="display:block;width:clamp(9rem,24vw,16rem);height:clamp(9rem,24vw,16rem);object-fit:cover;border-radius:50%;border:3px solid #facc15;box-shadow:0 0 32px #facc15;">`;
  else icon.textContent=visuals[payload.id]||payload.icon||'🎯';
  const title = document.createElement('div'); title.className='team-card-effect-title'; title.style.cssText='font-size:clamp(1.35rem,4vw,2.4rem)!important;color:#fff!important;'; title.textContent=payload.title||'Karte eingesetzt';
  const sub = document.createElement('div'); sub.className='team-card-effect-sub'; sub.style.cssText='color:#d7fbff!important;font-size:clamp(.9rem,2.5vw,1.15rem)!important;'; sub.textContent=payload.sub||'';
  card.append(icon,title,sub); layer.appendChild(card); document.body.appendChild(layer);
  // Bei Sound-Effekten entfernt der Audio-Player die Animation erst eine Sekunde nach dem Ton.
  const durationMs = payload.durationMs === 0 ? 0 : (Number(payload.durationMs)||2450);
  if(durationMs) window.setTimeout(()=>layer.remove(),durationMs);
  return layer;
}
function cardEffectShortDescription(item){
  const text = String(item && item.desc || '').replace(/\s+/g,' ').trim();
  if(!text) return '';
  return text.split(/[.!]/)[0].slice(0,118).trim();
}
function broadcastTeamCardEffect(item, targetName){
  const actor=currentUser?.username||'Jemand';
  const action = targetName ? `${actor} greift ${targetName} an.` : `${actor} aktiviert diesen Vorteil.`;
  const explanation = cardEffectShortDescription(item);
  const payload={ id:item.id||'', icon:item.icon||'🎯', title:item.label||'Karte eingesetzt', sub:explanation ? `${action} ${explanation}.` : action };
  showTeamCardEffect(payload);
  if(teamChannel) teamChannel.send({type:'broadcast',event:'card-effect',payload}).catch(()=>{});
}
function hasPikachuSound(){
  const s=currentUser && statsStore[currentUser.username];
  return !!(s && ((s.pikachusFound||0)>=50 || (s.shopOwned&&s.shopOwned.banners||[]).includes('pikachu_expedition')));
}
const PIKACHU_SOUND_VARIANTS = [
  { id:'thunderbolt', src:'assets/pikachu-thunderbolt.mp3', title:'Pikachu setzt Donnerblitz ein!', image:'assets/pikachu-thunderbolt.gif' },
  { id:'pika', src:'assets/pikachu_scream.mp3', title:'Pika Pika!', image:'assets/pikachu-50-avatar.gif' },
  { id:'pika', src:'assets/pikachu_mw38Ry2.mp3', title:'Pika Pika!', image:'assets/pikachu-50-avatar.gif' }
];
const PIKACHU_SOUND_COOLDOWN_MS = 8000;
let lastPikachuSoundAt = 0;
function playPikachuGroupSound(payload){
  const now=Date.now();
  if(now-lastPikachuSoundAt < PIKACHU_SOUND_COOLDOWN_MS) return false;
  lastPikachuSoundAt=now;
  const variant=(payload&&payload.variant) || PIKACHU_SOUND_VARIANTS[Math.floor(Math.random()*PIKACHU_SOUND_VARIANTS.length)];
  const actor=(payload&&payload.name) || 'Jemand';
  const effect=showTeamCardEffect({id:'pikachu',icon:'⚡',title:variant.title, image:variant.image, durationMs:0, sub:variant.id==='thunderbolt' ? actor+' setzt Donnerblitz ein!' : actor+' ruft: Pika Pika!'});
  try{
    const audio=new Audio(variant.src);
    audio.volume=.64;
    // Genau eine Sekunde nach dem Ende des jeweiligen Sounds ausblenden.
    audio.addEventListener('ended',()=>window.setTimeout(()=>effect?.remove(),1000),{once:true});
    // Sicherheitsnetz, falls ein Browser kein ended-Event auslöst.
    window.setTimeout(()=>effect?.remove(),15000);
    audio.play().catch(()=>{});
  }catch(e){}
  try{ if(userPrefs.soundVibration) navigator.vibrate&&navigator.vibrate([45,30,70]); }catch(e){}
  return true;
}
function sendPikachuGroupSound(){
  if(!hasPikachuSound()){ showAlert('Finde erst alle 50 Pikachus, um den Pikachu-Sound freizuschalten.','⚡'); return; }
  const remaining=Math.ceil((PIKACHU_SOUND_COOLDOWN_MS-(Date.now()-lastPikachuSoundAt))/1000);
  if(remaining>0){ showToast('Pikachu braucht noch '+remaining+' Sek. Pause.','⚡'); return; }
  const payload={name:currentUser?.username||'Jemand',variant:PIKACHU_SOUND_VARIANTS[Math.floor(Math.random()*PIKACHU_SOUND_VARIANTS.length)]};
  if(playPikachuGroupSound(payload) && teamChannel) Promise.resolve(teamChannel.send({type:'broadcast',event:'pikachu-sound',payload})).catch(()=>{});
}
let draftSyncTimer = null;
function syncDraftSettings(){
  if(!myTeam || !currentUser || myTeam.host_id !== currentUser.id || !sb) return;
  clearTimeout(draftSyncTimer);
  draftSyncTimer = setTimeout(async ()=>{
    try{ await sb.from('teams').update({ draft_settings: {
      text: campaignSummaryText(), at: Date.now(), scope:teamRoundScope, gameId:teamRoundGameChoice,
      gameMode:teamRoundGameMode, mode:teamRoundModeChoice, sessionMode:teamRoundSessionModeChoice,
      difficulty:teamRoundDifficulty, count:teamRoundCount, selectedGames:teamRoundSelectedGames,
      gameSequence:teamRoundGameSequence, gameModeChoices:teamRoundGameModeChoices, randomOrder:teamRoundRandomOrder,
       roundsPerGame:teamRoundsPerGame, funChallenges:teamRoundFunChallenges, communityChallenges:teamRoundCommunityChallenges,
      pointGoalChoice:teamRoundPointGoalChoice, customGoalValue:teamRoundCustomGoalValue,
      heroLockMode:teamRoundHeroLockMode, useHeroFavorites:teamRoundUseHeroFavorites, confirmed:!teamSettingsOpen,
      sabotageLimit:teamRoundSabotageLimit, sabotageAllowed:teamRoundSabotageAllowed, blitzSeconds:teamRoundBlitzSeconds
    } }).eq('id', myTeam.id); }
    catch(e){ console.error(e); }
  }, 500);
}
async function syncCampaignSummary(){
  if(!myTeam || !currentUser || myTeam.host_id !== currentUser.id || !sb) return;
  try{
    await sb.from('teams').update({ campaign_summary: { history: teamCampaignHistory, roundId: currentRound ? currentRound.id : null, at: Date.now() } }).eq('id', myTeam.id);
  }catch(e){ console.error(e); }
}
async function refreshTeamDraftSettings(){
  if(!myTeam || !sb) return;
  try{
    const { data } = await sb.from('teams').select('draft_settings, campaign_summary').eq('id', myTeam.id).maybeSingle();
    if(data){
      myTeam.draft_settings = data.draft_settings;
      myTeam.campaign_summary = data.campaign_summary;
      // Eigene, fehlertolerante Abfrage: falls die pending_next_game-Spalte (neue SQL-Migration)
      // noch fehlt, soll das NICHT den obigen, längst funktionierenden draft_settings-Sync mitreißen.
      let pendingChanged = false;
      try{
        const { data: pn } = await sb.from('teams').select('pending_next_game').eq('id', myTeam.id).maybeSingle();
        if(pn){ pendingChanged = JSON.stringify(myTeam.pending_next_game) !== JSON.stringify(pn.pending_next_game); myTeam.pending_next_game = pn.pending_next_game; }
      }catch(e){ /* Spalte evtl. noch nicht migriert — still ignorieren */ }
      const d = data.draft_settings;
      if(d && myTeam.host_id!==currentUser.id && !currentRound){
        teamRoundScope=d.scope||teamRoundScope; teamRoundGameChoice=d.gameId||teamRoundGameChoice;
        teamRoundGameMode=d.gameMode||null; teamRoundModeChoice=d.mode||teamRoundModeChoice;
        teamRoundSessionModeChoice=d.sessionMode||teamRoundSessionModeChoice; teamRoundDifficulty=d.difficulty||teamRoundDifficulty;
        teamRoundCount=d.count||teamRoundCount; teamRoundSelectedGames=d.selectedGames||teamRoundSelectedGames;
        teamRoundGameSequence=d.gameSequence||teamRoundGameSequence; teamRoundGameModeChoices=d.gameModeChoices||teamRoundGameModeChoices;
        teamRoundRandomOrder = typeof d.randomOrder==='boolean' ? d.randomOrder : teamRoundRandomOrder;
        teamRoundsPerGame = d.roundsPerGame || teamRoundsPerGame;
        teamRoundFunChallenges = typeof d.funChallenges==='boolean' ? d.funChallenges : teamRoundFunChallenges;
        teamRoundCommunityChallenges = typeof d.communityChallenges==='boolean' ? d.communityChallenges : teamRoundCommunityChallenges;
        teamRoundSabotageLimit = d.sabotageLimit || teamRoundSabotageLimit;
        teamRoundSabotageAllowed = typeof d.sabotageAllowed==='boolean' ? d.sabotageAllowed : teamRoundSabotageAllowed;
        teamRoundBlitzSeconds = d.blitzSeconds || teamRoundBlitzSeconds;
        communityChallengesEnabled = !!teamRoundCommunityChallenges;
        teamRoundPointGoalChoice = d.pointGoalChoice || teamRoundPointGoalChoice;
        teamRoundCustomGoalValue = d.customGoalValue || teamRoundCustomGoalValue;
        teamRoundHeroLockMode=d.heroLockMode||teamRoundHeroLockMode;
        teamRoundUseHeroFavorites=typeof d.useHeroFavorites==='boolean' ? d.useHeroFavorites : teamRoundUseHeroFavorites;
      }
      if(!currentRound && !teamSettingsOpen) renderTeamPage();
      else if(!teamSettingsOpen && pendingChanged) renderTeamPage();
    }
  }catch(e){ console.error(e); }
}
const PROFILE_ROLE_LABEL = { attack:'⚔️ Angriff/Damage', tank:'🛡️ Tank/Frontline', support:'➕ Support/Heiler', flex:'🔀 Flexibel/Egal' };
const PROFILE_SKILL_LABEL = { beginner:'🌱 Anfänger', intermediate:'🎯 Fortgeschritten', pro:'🏆 Profi' };
