/* ---- Screen 3: Lobby / Einladen (Code + Mitglieder, kein aktiver Round) ---- */
let lobbySettingsExpanded = true;
function toggleLobbySettingsExpanded(){ lobbySettingsExpanded=!lobbySettingsExpanded; renderTeamPage(); }
function renderTeamLobbyScreen(isHost, mine){
  if(isHost && mine && !mine.ready){ mine.ready = true; sb.from('team_members').update({ ready: true }).eq('team_id', myTeam.id).eq('user_id', currentUser.id).then(()=>{}); }
  let html = `
    <div class="scoreboard-head">
      <div class="scoreboard-info" style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:nowrap;width:100%;">
      <div style="min-width:0;overflow:hidden;flex:1 1 auto;">`;
  if(isHost && teamRenameEditing){
    html += `<div class="player-input-row" style="max-width:280px;margin:0;">
      <input type="text" id="team-rename-input" placeholder="Team-Name" maxlength="24" value="${myTeam.name||''}">
      <button onclick="renameTeam()">✅</button>
    </div>`;
  } else {
    html += `<div class="scoreboard-title" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${myTeam.name || 'Team'}${isHost ? ' 👑' : ''}${isHost ? ` <button class="header-menu-btn" style="display:inline-flex;width:28px;height:28px;font-size:0.8rem;vertical-align:middle;" onclick="teamRenameEditing=true; renderTeamPage();" title="Team umbenennen">✏️</button>` : ''}</div>`;
  }
  html += `
      </div>
        <div class="team-code-row"><span class="team-code-badge">${myTeam.code}</span><button class="header-menu-btn" style="width:auto;border-radius:14px;padding:0 8px;font-size:0.65rem;" onclick="shareTeamInvite('${myTeam.code}')" title="Team teilen (Code kann von dort auch kopiert werden)">↗ Teilen</button><span class="team-visibility-badge">${myTeam.is_public?'🌐 Öffentlich':'🔒 Geschlossen'}</span></div>
      </div>
      <div class="team-lobby-head-actions">
      <button class="sb-btn" onclick="openFriendInviteModal()">🤝 Freund einladen</button>
      ${isHost && teamMembers.length>1 ? '<button class="sb-btn" onclick="openHostTransferPicker()">👑 Host übergeben</button>' : ''}
      ${renderTeamChatAction()}
      </div>
    </div>
    <div class="settings-card">
      <div class="setup-step-head"><span class="setup-step-icon">👥</span><div class="setup-step-title">Mitglieder</div></div>
      <div class="player-chips">`;
  teamMembers.forEach(m=>{
    const canKick = isHost && m.user_id !== currentUser.id;
    const roleBadge = (m.round_role && m.round_role!=='all' && ROLE_META[m.round_role]) ? `<span class="team-member-role" title="Gewählte Rolle: ${m.round_role}">${ROLE_META[m.round_role].icon} ${m.round_role}</span>` : '';
    // Chip-Wrapper hat selbst einen Rand — bei Bannern kam dadurch ein zweiter, unsauberer Ring
    // um den eigenen Banner-Rahmen zustande. Bei aktivem Banner blenden wir den Chip-Rand aus,
    // der Banner selbst übernimmt dann die einzige sichtbare Umrandung.
    const memberHasBanner = !!cosmeticsFor(m.username).banner;
    html += `<div class="chip readonly member-clickable"${memberHasBanner?' style="border-color:transparent;background:transparent;"':''} onclick="showMemberProfile('${m.user_id}')">${playerCosmeticCardHTML(m.username, withHatOverlay(m.username, renderAccountAvatarHTML(m.avatar,20), 20), (m.user_id===myTeam.host_id?' 👑':'')+' '+(m.ready?'✅':'⏳')+' '+onlineDotHTML(m.last_active)+roleBadge)}${canKick?`<button class="member-kick-btn" onclick="event.stopPropagation(); kickMember('${m.user_id}')" title="Aus der Gruppe entfernen" aria-label="${m.username} aus der Gruppe entfernen">✕</button>`:''}</div>`;
  });
  html += `</div>`;
  html += `</div>`;
  if(!isHost && myTeam.draft_settings && myTeam.draft_settings.text){
    const draft=myTeam.draft_settings;
    html += `<div class="settings-card" style="border-color:var(--turquoise);">
      <button class="settings-row-btn" style="padding:10px 12px;background:rgba(34,211,238,.06);" onclick="toggleLobbySettingsExpanded()">
        <span class="settings-row-text"><span class="settings-row-title">Lobby-Einstellungen</span><span class="settings-row-sub">${draft.confirmed?'Vom Host bestätigt – jederzeit einsehbar.':'Der Host richtet die nächste Runde gerade ein.'}</span></span>
        <span class="settings-row-chev">${lobbySettingsExpanded?'▴':'▾'}</span>
      </button>
      ${lobbySettingsExpanded ? `<div style="padding:12px 4px 0;"><p class="setup-info" style="margin:0;">${draft.text}</p><div class="filter-row" style="margin-top:10px;"><span class="filter-pill active">${draft.scope==='match'?'Ein Match':draft.scope==='games'?'Spiele-Abend':draft.scope==='points'?'Bis zum Punkteziel':'Runden spielen'}</span><span class="filter-pill">${draft.mode==='team'?'Team':'Jeder gegen Jeden'}</span><span class="filter-pill">${draft.sessionMode==='chaos'?'Chaos':'Challenge'}</span><span class="filter-pill">${draft.difficulty||'Mittel'}</span></div></div>` : ''}
    </div>`;
  }
  const confirmedGameId = myTeam.draft_settings && myTeam.draft_settings.confirmed ? myTeam.draft_settings.gameId : null;
  const lobbyRoleOptions = confirmedGameId ? rolesForGame(confirmedGameId) : null;
  if(lobbyRoleOptions){
    const currentRoleKey = (mine&&mine.round_role)||'all';
    const currentRoleLabel = currentRoleKey==='all' ? '🎲 Zufällig' : `${ROLE_META[currentRoleKey]?ROLE_META[currentRoleKey].icon:''} ${currentRoleKey}`;
    html += `<button class="settings-row-btn" onclick="openRolePickerModal()">
      <span class="settings-row-icon">🎭</span>
      <span class="settings-row-text">
        <span class="settings-row-title">Meine Rolle</span>
        <span class="settings-row-sub">${currentRoleLabel}</span>
      </span>
      <span class="settings-row-chev">›</span>
    </button>`;
  }
  html += renderLoadoutPicker();
  html += renderMemberLobbyExtras(isHost, mine);
  return html;
}
function renderMemberLobbyExtras(isHost, mine){
  let html = '';
  if(isHost){
    html += `<button class="settings-row-btn" style="margin-top:4px;" onclick="openTeamSettings()">
      <span class="settings-row-icon">⚙️</span>
      <span class="settings-row-text">
        <span class="settings-row-title">Runde einstellen</span>
        <span class="settings-row-sub">${teamRoundGameChoice ? campaignSummaryText() : 'Spiel, Modus und Ablauf festlegen'}</span>
      </span>
      <span class="settings-row-chev">›</span>
    </button>`;
    if(teamRoundGameChoice){
      const waiting = teamMembers.filter(m=>m.user_id!==myTeam.host_id && !m.ready);
      html += `<div class="panel-block" style="margin-top:12px;">
        ${waiting.length ? `<p class="setup-warning" style="margin-top:0;">⏳ ${waiting.length} nicht bereit – startet ohne sie; sie bleiben im Team.</p>` : ''}
        <div class="roll-zone" style="margin-bottom:0;"><button class="roll-btn" onclick="startTeamRound()">🚀 Runde mit Bereiten starten</button></div>
      </div>`;
    }
  } else {
    html += `<div class="empty-hint">📱 Wartet, bis der Team-Ersteller (👑) eine Runde startet…</div>`;
    html += `<div class="roll-zone" style="margin-top:12px;"><button class="roll-btn" onclick="toggleMyReady()">${mine && mine.ready ? '⏳ Nicht mehr bereit' : '✅ Bereit'}</button></div>`;
  }
  return html;
}
function setTeamPageChrome(icon, title, eyebrow, h2, p){
  document.getElementById('team-page-icon').textContent = icon;
  document.getElementById('team-page-title').textContent = title;
  const lead = document.getElementById('team-section-lead');
  if(eyebrow || h2 || p){
    lead.style.display = 'block';
    document.getElementById('team-section-eyebrow').textContent = eyebrow || '';
    document.getElementById('team-section-h2').textContent = h2 || '';
    document.getElementById('team-section-p').textContent = p || '';
  } else {
    lead.style.display = 'none';
  }
}
let teamChatExpanded = false;
let teamChatMessages = [];
let teamChatChannel = null;
let teamChatFor = null;
function teamChatReadKey(){ return currentUser&&myTeam ? `winchallenge_team_chat_read_${currentUser.id}_${myTeam.id}` : ''; }
function teamChatReadAt(){ try{return Number(localStorage.getItem(teamChatReadKey())||0);}catch(e){return 0;} }
function setTeamChatReadAt(value){ try{ const key=teamChatReadKey(); if(key) localStorage.setItem(key,String(value)); }catch(e){} }
function unreadTeamChatCount(){ const since=teamChatReadAt(); return teamChatMessages.filter(m=>m.author_id!==currentUser?.id && new Date(m.created_at).getTime()>since).length; }
function markTeamChatRead(){ setTeamChatReadAt(Date.now()); }
function updateTeamChatUnreadIndicator(){ const count=userPrefs?.chatNotifications ? unreadTeamChatCount() : 0; document.querySelectorAll('.team-chat-unread').forEach(badge=>{badge.textContent=count>99?'99+':count;badge.hidden=!count;}); }
function teamChatNameHTML(message){
  const username=message?.profiles?.username || 'Spieler';
  const stats=statsStore?.[username] || {};
  const banner=SHOP_BANNERS?.find(b=>b.id===stats.equippedBanner);
  const style=banner && !banner.basic ? bannerStyleFor(banner) : '';
  return `<strong class="team-chat-name"${style?` style="${style}"`:''}>${messageEscape(username)}</strong>`;
}
function shareTeamInvite(code){
  const text=`Komm in mein WIN CHALLENGE Team: ${code}`;
  if(navigator.share){ navigator.share({title:'WIN CHALLENGE Team',text}).catch(()=>{}); }
  else copyTeamCode(code);
}
function ensureTeamChatModal(){
  let modal=document.getElementById('team-chat-modal');
  if(!modal){
    modal=document.createElement('div'); modal.id='team-chat-modal'; modal.className='team-chat-modal-backdrop hidden';
    modal.onclick=(event)=>{ if(event.target===modal) closeTeamChatModal(); };
    document.body.appendChild(modal);
  }
  return modal;
}
function openTeamChatModal(){
  if(!myTeam) return;
  teamChatExpanded=true; markTeamChatRead(); renderTeamChatModal(); refreshTeamChat();
}
function closeTeamChatModal(){
  teamChatExpanded=false;
  const modal=document.getElementById('team-chat-modal'); if(modal) modal.classList.add('hidden');
  updateTeamChatUnreadIndicator();
}
function toggleTeamChat(){
  const modal=document.getElementById('team-chat-modal');
  if(teamChatExpanded && modal && !modal.classList.contains('hidden')) closeTeamChatModal();
  else openTeamChatModal();
}
function renderTeamChatAction(){
  return `<button class="sb-btn team-chat-action" onclick="openTeamChatModal()"><span>💬 Chat</span></button>`;
}
function renderTeamChatIconAction(){
  if(!myTeam) return '';
  const unread=unreadTeamChatCount();
  return `<button class="header-menu-btn team-chat-header-btn" onclick="openTeamChatModal()" aria-label="Team-Chat" title="Team-Chat">💬<span class="team-chat-unread" ${unread?'':'hidden'}>${unread||''}</span></button>`;
}
function renderTeamChatModal(){
  if(!myTeam) return;
  const modal=ensureTeamChatModal();
  const rows=teamChatMessages.map(m=>`<div class="team-chat-message">${renderAccountAvatarHTML(m.profiles?.avatar,22)}<div>${teamChatNameHTML(m)}<span>${messageEscape(m.body)}</span></div><time>${messageDate(m.created_at)}</time></div>`).join('');
  modal.innerHTML=`<section class="team-chat-modal-card" role="dialog" aria-modal="true" aria-label="Team-Chat" onclick="event.stopPropagation();"><div class="team-chat-modal-head"><span>💬 Team-Chat</span><button class="team-chat-modal-close" onclick="closeTeamChatModal()" aria-label="Chat schließen">✕</button></div><div class="team-chat-body"><div id="team-chat-feed" class="team-chat-feed">${rows||'<div class="empty-hint">Noch keine Nachrichten. Schreib den ersten Satz!</div>'}</div><form class="team-chat-form" onsubmit="event.preventDefault();sendTeamChat(this)"><input maxlength="500" required placeholder="Nachricht an dein Team …"><button class="roll-btn" type="submit">Senden</button></form></div></section>`;
  modal.classList.remove('hidden');
  const feed=modal.querySelector('#team-chat-feed'); if(feed) feed.scrollTop=feed.scrollHeight;
}
function renderTeamChatHTML(){
  if(!myTeam) return '';
  const rows=teamChatMessages.map(m=>`<div class="team-chat-message">${renderAccountAvatarHTML(m.profiles?.avatar,22)}<div>${teamChatNameHTML(m)}<span>${messageEscape(m.body)}</span></div><time>${messageDate(m.created_at)}</time></div>`).join('');
  const unread=unreadTeamChatCount();
  return `<section class="settings-card team-chat" style="margin-top:0;"><button class="team-chat-toggle" onclick="toggleTeamChat()"><span>Team-Chat <b class="team-chat-unread" ${unread?'':'hidden'}>${unread||''}</b></span><small>${teamChatExpanded?'Einklappen':'Öffnen'}</small></button>${teamChatExpanded?`<div class="team-chat-body"><div id="team-chat-feed" class="team-chat-feed">${rows||'<div class="empty-hint">Noch keine Nachrichten. Schreib den ersten Satz!</div>'}</div><form class="team-chat-form" onsubmit="event.preventDefault();sendTeamChat(this)"><input maxlength="500" required placeholder="Nachricht an dein Team …"><button class="roll-btn" type="submit">Senden</button></form></div>`:''}</section>`;
}
async function refreshTeamChat(){
  if(!myTeam||!sb) return;
  const {data,error}=await sb.from('team_messages').select('id,body,created_at,author_id,profiles(username,avatar)').eq('team_id',myTeam.id).order('created_at',{ascending:true}).limit(100);
  if(error){ console.warn('Team-Chat nicht verfügbar:',error.message); teamChatMessages=[]; }
  else teamChatMessages=data||[];
  // Vorhandene Chat-Historie ist keine neue Benachrichtigung. Beim ersten Betreten
  // einer Gruppe wird sie deshalb als gelesen markiert; danach zeigt der rote Punkt
  // ausschließlich Nachrichten an, die wirklich neu eintreffen.
  if(!teamChatReadAt() && teamChatMessages.length){
    const newest=Math.max(...teamChatMessages.map(m=>new Date(m.created_at).getTime()||0));
    if(newest) setTeamChatReadAt(newest);
  }
  if(teamChatExpanded) markTeamChatRead();
  updateTeamChatUnreadIndicator();
  refreshMessageBadges();
  const feed=document.getElementById('team-chat-feed'); if(feed){ feed.innerHTML=teamChatMessages.map(m=>`<div class="team-chat-message">${renderAccountAvatarHTML(m.profiles?.avatar,22)}<div>${teamChatNameHTML(m)}<span>${messageEscape(m.body)}</span></div><time>${messageDate(m.created_at)}</time></div>`).join('')||'<div class="empty-hint">Noch keine Nachrichten. Schreib den ersten Satz!</div>'; feed.scrollTop=feed.scrollHeight; }
}
async function sendTeamChat(form){
  if(!myTeam||!currentUser||!sb) return;
  const input=form.querySelector('input'); const body=input?.value.trim(); if(!body) return;
  const {error}=await sb.from('team_messages').insert({team_id:myTeam.id,author_id:currentUser.id,body});
  if(error){ showAlert('Nachricht konnte nicht gesendet werden: '+error.message); return; }
  input.value=''; await refreshTeamChat();
}
function ensureTeamChatLive(){
  if(!sb||!myTeam) return;
  if(teamChatChannel && teamChatFor !== myTeam.id){ sb.removeChannel?.(teamChatChannel); teamChatChannel=null; teamChatMessages=[]; }
  if(teamChatChannel) return;
  teamChatFor=myTeam.id;
  teamChatChannel=sb.channel('team-chat-'+myTeam.id).on('postgres_changes',{event:'*',schema:'public',table:'team_messages',filter:'team_id=eq.'+myTeam.id},()=>refreshTeamChat()).subscribe();
}
(function(){const css=document.createElement('style');css.textContent=`.team-chat{max-width:1100px;margin-left:auto!important;margin-right:auto!important}.team-chat-toggle{width:100%;display:flex;justify-content:space-between;align-items:center;background:none;border:0;color:var(--text);font:inherit;font-weight:900;font-size:1rem;cursor:pointer;padding:2px}.team-chat-toggle>span{display:inline-flex;align-items:center;gap:8px}.team-chat-toggle small{color:var(--turquoise);font-weight:800}.team-chat-unread{min-width:18px;height:18px;padding:0 5px;display:inline-flex;align-items:center;justify-content:center;border-radius:999px;background:#f25f72;color:#fff;font-size:.67rem;box-shadow:0 0 12px rgba(242,95,114,.55)}.team-chat-unread[hidden]{display:none!important}.team-chat-body{margin-top:14px;border-top:1px solid var(--border-soft);padding-top:12px}.team-chat-feed{display:grid;gap:8px;max-height:260px;overflow:auto;padding-right:4px}.team-chat-message{display:grid;grid-template-columns:24px 1fr auto;gap:8px;align-items:start;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.035);font-size:.87rem}.team-chat-name{display:block;width:max-content;max-width:100%;padding:2px 7px;border-radius:7px;color:var(--turquoise);font-size:.78rem;background:rgba(17,20,34,.75);background-size:cover;background-position:center;text-shadow:0 1px 3px #000;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.team-chat-message span{display:block;white-space:pre-wrap}.team-chat-message time{font-size:.68rem;color:var(--text-faint)}.team-chat-form{display:flex;gap:9px;margin-top:12px}.team-chat-form input{flex:1;background:var(--bg-elevated);border:1px solid var(--border);border-radius:10px;color:var(--text);padding:11px}@media(max-width:560px){.team-chat-form{flex-direction:column}.team-chat-form .roll-btn{width:100%}.team-chat-message{grid-template-columns:24px 1fr}.team-chat-message time{grid-column:2}}`;document.head.appendChild(css);})();
function renderTeamPage(){
  window.refreshPregameHeader?.();
  window.refreshAppBottomNav?.();
  if(teamRoundRenderLocked) return; // Roulette dreht gerade auf diesem Gerät — Re-Renders durch Polling/Realtime währenddessen unterdrücken
  const el = document.getElementById('team-content');
  const leaveBtn = document.getElementById('team-leave-btn');
  if(!currentUser){
    setTeamPageChrome('👥','Team','','','');
    if(leaveBtn) leaveBtn.style.display = 'none';
    el.innerHTML = `<div class="empty-hint">Bitte zuerst einloggen.<button class="empty-hint-link" onclick="showView('auth')">👤 Einloggen</button></div>`;
    return;
  }
  if(!myTeam){
    if(myTeams.length){ openTeamFromList(myTeams[myTeams.length-1].id); return; }
    showView('teams-list', true);
    return;
  }

  const isHost = myTeam.host_id === currentUser.id;
  const mine = teamMembers.find(m=>m.user_id===currentUser.id);

  // Für Mitspieler (Nicht-Host) gibt es keine eigene lokale teamPendingGameIntro-Variable — die wird
  // nur beim Host gesetzt (s. nextCampaignRound()). Stattdessen über das synchronisierte
  // myTeam.pending_next_game erkennen, ob GENAU JETZT (also nach der zuletzt bekannten Runde) eine
  // neue Spiel-Ankündigung ansteht — afterRoundId muss zur aktuell bekannten Runde passen, sonst ist
  // der Eintrag entweder noch nicht relevant oder schon überholt (neue Runde längst gestartet).
  const memberPendingIntro = !isHost && myTeam.pending_next_game && myTeam.pending_next_game.afterRoundId === (currentRound ? currentRound.id : null);
  const showGameIntro = teamPendingGameIntro || memberPendingIntro;

  if(showGameIntro){
    setTeamPageChrome('🎮','Nächstes Spiel','','','');
    if(leaveBtn) leaveBtn.style.display = 'none';
    const introGameId = isHost ? teamRoundGameChoice : myTeam.pending_next_game.gameId;
    const g = GAMES.find(x=>x.id===introGameId);
    const cover = gameCoverCache[introGameId];
    const cardStyle = cover ? `background-image:url('${cover.replace(/'/g,"%27")}');` : `background:${g?g.grad:'var(--bg-card)'};`;
    const actionHTML = isHost
      ? `<button class="round-prompt-btn primary" onclick="confirmTeamGameIntro()">▶️ Los geht's</button>`
      : '';
    const belowCardHTML = isHost ? '' : `<p class="empty-hint" style="margin:14px 0 0;">⏳ Wartet auf den Team-Ersteller (👑)…</p>`;
    el.innerHTML = `<div class="game-intro-card${cover?' has-cover':''}" style="${cardStyle}">
      <div class="game-intro-eyebrow">Nächstes Spiel</div>
      ${cover?'':`<div class="game-intro-icon">${g?g.icon:'🎮'}</div>`}
      <div class="game-intro-name">${GAME_NAME[introGameId]||''}</div>
      <div class="game-intro-tag">${g?g.tag:''}</div>
      ${actionHTML}
    </div>
    ${belowCardHTML}
    <div style="margin-top:16px;">${renderLoadoutPicker()}</div>`;
    return;
  }

  if(teamRoundTransitioning){
    setTeamPageChrome('⏳','Nächste Runde','','','');
    if(leaveBtn) leaveBtn.style.display = 'none';
    el.innerHTML = `<div class="empty-hint" style="padding:60px 20px;">⏳ Nächste Runde wird vorbereitet…</div>`;
    return;
  }

  // Screen-Router: läuft gerade eine Runde? -> Live-Rundenansicht (unabhängig von Settings/Lobby)
  if(currentRound){
    setTeamPageChrome('🎮','Runde läuft','','','');
    if(leaveBtn) leaveBtn.style.display = 'none';
    el.innerHTML = renderTeamRoundSection();
    ensureTeamChatLive(); if(teamChatExpanded) refreshTeamChat();
    startBlitzRotationIfNeeded();
    return;
  }
  stopBlitzRotation();
  if(leaveBtn) leaveBtn.style.display = 'flex';
  // Kein aktiver Round: Host konfiguriert gerade? -> eigene Einstellungs-Seite
  if(isHost && teamSettingsOpen){
    setTeamPageChrome('','','','','');
    el.innerHTML = renderTeamSettingsScreen();
    renderTeamRoundPicker();
    return;
  }
  // Sonst: Lobby / Einladen — kein zusätzlicher Eyebrow-Text nötig, der Name steht schon oben in der Kopfzeile.
  setTeamPageChrome('👥', myTeam.name || 'Team', '', '', '');
  el.innerHTML = renderTeamLobbyScreen(isHost, mine);
  ensureTeamChatLive(); if(teamChatExpanded) refreshTeamChat();
}

