async function loadHeroImages(){
  if(!sb) return;
  try{
    const { data, error } = await sb.from('hero_images').select('hero_name, image_data');
    if(!error && data) data.forEach(r=>{ heroImageCache[r.hero_name] = r.image_data; });
  }catch(e){ /* table may not exist yet until SQL migration is run */ }
}
function heroAvatarInner(heroName, gameId){
  const img = heroImageFor(gameId, heroName);
  return img ? `<img src="${img}" style="width:100%;height:100%;object-fit:cover;">` : initials(heroName);
}
let adminGameChallengeSelected=null, adminGameChallengeDiff='mittel', adminGameChallengeScope='shared';
function renderAdminGamesTab(){
  if(!adminGameChallengeSelected) adminGameChallengeSelected=GAMES[0]?.id||null;
  const picker=document.getElementById('admin-game-challenge-picker');
  if(picker){
    picker.innerHTML='';
    GAMES.forEach(g=>{
      const btn=document.createElement('button');
      btn.className='filter-pill'+(g.id===adminGameChallengeSelected?' active':'');
      btn.innerHTML=`${g.icon} ${g.name}`;
      btn.onclick=()=>{ adminGameChallengeSelected=g.id; renderAdminGamesTab(); };
      picker.appendChild(btn);
    });
  }
  const diffRow=document.getElementById('admin-game-challenge-diff');
  if(diffRow){
    diffRow.innerHTML='';
    Object.entries(DIFF_LABEL).forEach(([k,label])=>{
      const btn=document.createElement('button');
      btn.className='filter-pill'+(k===adminGameChallengeDiff?' active':'');
      btn.textContent=label;
      btn.onclick=()=>{ adminGameChallengeDiff=k; renderAdminGamesTab(); };
      diffRow.appendChild(btn);
    });
  }
  const scopeRow=document.getElementById('admin-game-challenge-scope');
  if(scopeRow){
    scopeRow.innerHTML='';
    [['shared','🤝 Team-Challenge'],['personal','👤 Persönliche Challenge']].forEach(([k,label])=>{
      const btn=document.createElement('button');
      btn.className='filter-pill'+(k===adminGameChallengeScope?' active':'');
      btn.textContent=label;
      btn.onclick=()=>{ adminGameChallengeScope=k; renderAdminGamesTab(); };
      scopeRow.appendChild(btn);
    });
  }
  const list=document.getElementById('admin-games-list');
  if(list){
    list.innerHTML=GAMES.map(g=>{
      const count=(CHALLENGE_SOURCES[g.id]||[]).length + (customChallenges[g.id]||[]).filter(c=>c.approved!==false).length;
      return `<div class="settings-row-btn" style="cursor:default;"><span class="settings-row-icon" style="background:none;padding:0;">${g.icon}</span><span class="settings-row-text"><span class="settings-row-title">${g.name}</span><span class="settings-row-sub">${g.tag||''} · ${count} Challenges</span></span></div>`;
    }).join('');
  }
}
async function adminAddGame(){
  if(!currentUser?.is_admin || !sb) return;
  const name=document.getElementById('admin-game-name').value.trim();
  const icon=document.getElementById('admin-game-icon').value.trim()||'🎮';
  const tag=document.getElementById('admin-game-tag').value.trim();
  const maxPlayers=Number.parseInt(document.getElementById('admin-game-maxplayers').value,10)||10;
  const status=document.getElementById('admin-game-add-status');
  if(!name){ if(status){status.textContent='Bitte einen Namen eingeben.';status.style.color='#f87171';} return; }
  const id=name.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,30) || ('game_'+Date.now());
  if(GAME_NAME[id]){ if(status){status.textContent='Es gibt schon ein Spiel mit einer sehr ähnlichen ID — bitte anderen Namen wählen.';status.style.color='#f87171';} return; }
  const {error}=await sb.from('custom_games').insert({ id, name, icon, tag, max_players:maxPlayers, created_by:currentUser.id });
  if(error){ if(status){status.textContent='Fehlgeschlagen: '+error.message;status.style.color='#f87171';} return; }
  const gameObj={ id, icon, watermark:icon, name, tag, grad:'linear-gradient(135deg,#241a3a,#0d3b3a)', maxPlayers };
  GAMES.push(gameObj); SESSION_GAMES.push(id);
  GAME_NAME[id]=name; GAME_ICON[id]=icon;
  CHALLENGE_SOURCES[id]=[]; PERSONAL_SOURCES[id]=[];
  document.getElementById('admin-game-name').value='';
  document.getElementById('admin-game-icon').value='';
  document.getElementById('admin-game-tag').value='';
  document.getElementById('admin-game-maxplayers').value='';
  if(status){ status.textContent=`"${name}" wurde hinzugefügt und ist jetzt überall wählbar.`; status.style.color='var(--turquoise)'; }
  adminGameChallengeSelected=id;
  renderAdminGamesTab();
}
function adminAddGameChallenge(){
  if(!currentUser?.is_admin) return;
  const status=document.getElementById('admin-game-challenge-status');
  const textEl=document.getElementById('admin-game-challenge-text');
  const text=textEl.value.trim();
  if(!adminGameChallengeSelected){ if(status){status.textContent='Bitte zuerst ein Spiel auswählen.';status.style.color='#f87171';} return; }
  if(!text){ if(status){status.textContent='Bitte einen Challenge-Text eingeben.';status.style.color='#f87171';} return; }
  addCustomChallenge(adminGameChallengeSelected, text, adminGameChallengeDiff, adminGameChallengeScope);
  textEl.value='';
  if(status){ status.textContent=`Challenge für ${GAME_NAME[adminGameChallengeSelected]} hinzugefügt und sofort aktiv.`; status.style.color='var(--turquoise)'; }
  renderAdminGamesTab();
}
function renderAdminNotificationsTab(){
  const status=document.getElementById('admin-notification-test-status');
  if(status) status.textContent='';
}
async function adminSendTestNotification(){
  if(!currentUser?.is_admin||!sb) return;
  const status=document.getElementById('admin-notification-test-status');
  const {error}=await sb.from('player_notifications').insert({target_user_id:currentUser.id,from_user_id:currentUser.id,icon:'🔔',message:'Das ist eine Test-Benachrichtigung — wenn du sie als Toast siehst und sie im Mitteilungszentrum auftaucht, funktioniert alles.'});
  if(error){ if(status){ status.textContent='Fehlgeschlagen: '+error.message; status.style.color='#f87171'; } return; }
  if(status){ status.textContent='Gesendet — schau auf den Toast oben und ins Mitteilungszentrum.'; status.style.color='var(--turquoise)'; }
  refreshMessageBadges();
}
