const ADMIN_TABS = [
  { key:'overview', icon:'🛠️', label:'Übersicht' },
  { key:'users', icon:'👥', label:'Benutzer' },
  { key:'heroes', icon:'🖼️', label:'Helden-Bilder' },
  { key:'covers', icon:'🎮', label:'Cover-Bilder' },
  { key:'points', icon:'🪙', label:'Punkte (Test)' },
  { key:'pending_challenges', icon:'⏳', label:'Challenges freigeben' },
  { key:'game_suggestions', icon:'💡', label:'Spiele-Vorschläge' },
  { key:'bug_reports', icon:'🐞', label:'Bug-Reports' },
  { key:'games', icon:'🕹️', label:'Spiele verwalten' },
  { key:'notifications', icon:'🔔', label:'Benachrichtigungen (Test)' },
];
let adminActiveTab = 'overview';
function renderAdminTabs(){
  const row = document.getElementById('admin-tabs'); if(!row) return;
  row.innerHTML = '';
  ADMIN_TABS.forEach(t=>{
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(t.key===adminActiveTab?' active':'');
    btn.textContent = `${t.icon} ${t.label}`;
    btn.addEventListener('click', ()=>{ adminActiveTab = t.key; showAdminTab(t.key); });
    row.appendChild(btn);
  });
}
function showAdminTab(key){
  adminActiveTab = key;
  ADMIN_TABS.forEach(t=>{
    const panel = document.getElementById('admin-tab-'+t.key);
    if(panel) panel.style.display = (t.key===key) ? 'block' : 'none';
  });
  renderAdminTabs();
  if(key==='points') renderAdminPointsTab();
  if(key==='pending_challenges') renderAdminPendingChallengesTab();
  if(key==='game_suggestions') renderAdminGameSuggestionsTab();
  if(key==='bug_reports') renderAdminBugReportsTab();
  if(key==='games') renderAdminGamesTab();
  if(key==='notifications') renderAdminNotificationsTab();
}
let adminPointsSelectedPlayer = null;
function renderAdminPointsTab(){
  const names = Object.keys(statsStore);
  const row = document.getElementById('admin-points-player-picker');
  if(!row) return;
  if(!names.length){ row.innerHTML = '<div class="empty-hint">Noch keine lokalen Spieler-Statistiken vorhanden.</div>'; return; }
  if(!adminPointsSelectedPlayer || !names.includes(adminPointsSelectedPlayer)) adminPointsSelectedPlayer = (currentUser && names.includes(currentUser.username)) ? currentUser.username : names[0];
  row.innerHTML = '';
  names.forEach(n=>{
    const isMe = currentUser && n===currentUser.username;
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(n===adminPointsSelectedPlayer?' active':'');
    btn.innerHTML = avatarHTML(n,16)+' '+n+(isMe?' (Du)':'');
    btn.addEventListener('click', ()=>{ adminPointsSelectedPlayer = n; renderAdminPointsTab(); });
    row.appendChild(btn);
  });
  const s = statsStore[adminPointsSelectedPlayer];
  const claimedCount = s ? (s.achievementsClaimed||[]).length : 0;
  const statusEl = document.getElementById('admin-achievement-status');
  if(statusEl) statusEl.textContent = `${claimedCount} / ${ACHIEVEMENTS_DEF.length} freigeschaltet (${adminPointsSelectedPlayer||'—'})`;
  const balanceEl = document.getElementById('admin-points-balance-preview');
  if(balanceEl && s){
    const notMe = currentUser && adminPointsSelectedPlayer!==currentUser.username;
    balanceEl.innerHTML = `Aktuell für <strong>${adminPointsSelectedPlayer}</strong>: totalPoints ${s.totalPoints||0} · spent ${s.spent||0} · Bonus ${s.shopBonus||0} → <strong>Guthaben ${shopBalance(adminPointsSelectedPlayer)}</strong>${notMe?' <span style="color:#f87171;">(nicht dein eigener Account — im Shop siehst du das hier nicht!)</span>':''}`;
  }
}
// Lädt alle noch nicht freigegebenen eigenen Challenges (spielübergreifend) direkt aus Supabase —
// unabhängig vom lokalen customChallenges-Cache, damit auch Einträge von anderen Geräten auftauchen.
async function renderAdminPendingChallengesTab(){
  const listEl = document.getElementById('admin-pending-challenges-list');
  if(!listEl) return;
  if(!sb){ listEl.innerHTML = '<div class="empty-hint">Keine Verbindung zur Cloud.</div>'; return; }
  listEl.innerHTML = '<div class="empty-hint">Lädt…</div>';
  const { data, error } = await sb.from('custom_challenges').select('id, game_id, text, diff, scope, created_by_name').eq('approved', false);
  if(error){ listEl.innerHTML = `<div class="empty-hint">Fehler beim Laden (evtl. fehlt noch die Spalte "approved" in custom_challenges): ${error.message}</div>`; return; }
  if(!data || !data.length){ listEl.innerHTML = '<div class="empty-hint">Aktuell nichts zur Freigabe offen. 🎉</div>'; return; }
  let html = '';
  data.forEach(c=>{
    html += `<div class="sb-challenge-item">
      <div class="sb-diff-badge" style="background:${DIFF_COLOR[c.diff]}">${DIFF_LABEL[c.diff]}</div>
      <div class="sb-challenge-text">${gameIconHTML(c.game_id,16)} ${GAME_NAME[c.game_id]||c.game_id} · ${c.text}${c.scope==='personal'?' <span style="color:var(--text-faint);font-size:0.75rem;">· persönlich</span>':''}${c.created_by_name?` <span style="color:var(--text-faint);font-size:0.75rem;">· von ${c.created_by_name}</span>`:''}</div>
      <button class="sb-btn" style="padding:6px 10px;" onclick="approveCustomChallenge('${c.id}')">✅</button>
      <button class="sb-btn danger" style="padding:6px 10px;" onclick="rejectCustomChallenge('${c.id}')">✕</button>
    </div>`;
  });
  listEl.innerHTML = html;
}
async function approveCustomChallenge(id){
  if(!sb) return;
  const { data, error } = await sb.from('custom_challenges').update({ approved: true }).eq('id', id).select('id, game_id, text, created_by, created_by_name').maybeSingle();
  if(error){ showAlert('Fehler: ' + error.message); return; }
  Object.values(customChallenges).forEach(list=>{ const item = list.find(c=>c.id===id); if(item) item.approved = true; });
  saveCustomChallenges();
  if(data?.created_by && currentUser){
    await sb.from('player_notifications').insert({target_user_id:data.created_by,from_user_id:currentUser.id,icon:'✅',message:`Deine Challenge für ${GAME_NAME[data.game_id]||data.game_id} wurde freigegeben und ist jetzt auswählbar.`});
  }
  await loadCustomChallengesFromCloud();
  renderAdminPendingChallengesTab();
}
async function rejectCustomChallenge(id){
  if(!sb) return;
  const {data:item}=await sb.from('custom_challenges').select('game_id,created_by').eq('id',id).maybeSingle();
  const { error } = await sb.from('custom_challenges').delete().eq('id', id);
  if(error){ showAlert('Fehler: ' + error.message); return; }
  Object.keys(customChallenges).forEach(gameId=>{ customChallenges[gameId] = customChallenges[gameId].filter(c=>c.id!==id); });
  saveCustomChallenges();
  if(item?.created_by && currentUser) await sb.from('player_notifications').insert({target_user_id:item.created_by,from_user_id:currentUser.id,icon:'✉',message:`Deine Challenge für ${GAME_NAME[item.game_id]||item.game_id} wurde leider nicht freigegeben.`});
  renderAdminPendingChallengesTab();
}
// ===== Bug-Reports =====
function bugStatusLabel(status){ return ({open:'Offen',reviewed:'In Prüfung',fixed:'Behoben',closed:'Geschlossen'})[status] || 'Offen'; }
async function submitBugReport(){
  if(!currentUser || !sb){ showAlert('Bitte zuerst einloggen, um einen Bug zu melden.'); return; }
  const title=document.getElementById('bug-report-title')?.value.trim();
  const body=document.getElementById('bug-report-body')?.value.trim();
  if(!title || !body){ showAlert('Bitte Titel und Beschreibung ausfüllen.'); return; }
  const {data:createdReport,error}=await sb.from('bug_reports').insert({reporter_id:currentUser.id,reporter_name:currentUser.username,title,body,status:'open'}).select('id').maybeSingle();
  if(error){ showAlert('Bug-Report konnte nicht gesendet werden: '+error.message); return; }
  document.getElementById('bug-report-title').value=''; document.getElementById('bug-report-body').value='';
  try{
    const {data:admins}=await sb.from('profiles').select('id').eq('is_admin',true);
    const rows=(admins||[]).filter(a=>a.id!==currentUser.id).map(a=>({target_user_id:a.id,from_user_id:currentUser.id,icon:'🐞',message:`Neuer Bug-Report von ${currentUser.username}: ${title}\n[wc-request:bug:${createdReport?.id||''}]`}));
    if(rows.length) await sb.from('player_notifications').insert(rows);
  }catch(e){ console.warn('Admin-Bug-Hinweis konnte nicht gesendet werden:',e); }
  showToast('Danke! Dein Bug-Report wurde an das Admin-Team gesendet.','🐞',3600);
  renderBugReportsPage();
}
async function renderBugReportsPage(){
  const out=document.getElementById('my-bug-reports'); if(!out) return;
  if(!currentUser||!sb){out.innerHTML='';return;}
  const {data,error}=await sb.from('bug_reports').select('id,title,body,status,admin_feedback,reward_coins,created_at,updated_at').eq('reporter_id',currentUser.id).order('created_at',{ascending:false}).limit(50);
  if(error){out.innerHTML=`<div class="empty-hint">Bug-Reports sind noch nicht eingerichtet. Bitte führe die SQL-Datei aus.</div>`;return;}
  out.innerHTML=`<div class="section-divider" style="margin-top:22px;">Meine Meldungen</div>`+(data||[]).map(r=>`<article class="settings-card" style="margin-top:10px;"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;"><strong>${messageEscape(r.title)}</strong><span class="message-kind">${bugStatusLabel(r.status)}</span></div><p class="setup-info" style="white-space:pre-wrap;margin:8px 0 0;">${messageEscape(r.body)}</p>${r.admin_feedback?`<div class="rules-note" style="margin-top:12px;"><strong>Antwort vom Admin:</strong> ${messageEscape(r.admin_feedback)}</div>`:''}${r.reward_coins?`<div style="color:var(--turquoise);font-weight:900;margin-top:10px;">Danke: +${r.reward_coins} Shop-Coins</div>`:''}</article>`).join('')||'<div class="empty-hint">Noch keine Bug-Reports gesendet.</div>';
}
async function renderAdminBugReportsTab(){
  const out=document.getElementById('admin-bug-reports-list'); if(!out) return;
  if(!sb){out.innerHTML='<div class="empty-hint">Keine Verbindung zur Cloud.</div>';return;}
  out.innerHTML='<div class="empty-hint">Lädt…</div>';
  const {data,error}=await sb.from('bug_reports').select('id,reporter_id,reporter_name,title,body,status,admin_feedback,reward_coins,rewarded,created_at').order('created_at',{ascending:false}).limit(100);
  if(error){out.innerHTML=`<div class="empty-hint">Bug-Reports sind noch nicht eingerichtet: ${messageEscape(error.message)}</div>`;return;}
  out.innerHTML=(data||[]).map(r=>`<article class="settings-card" style="margin-top:10px;"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;"><strong>${messageEscape(r.title)}</strong><span class="message-kind">${bugStatusLabel(r.status)}</span></div><div class="setup-info" style="margin:4px 0 9px;">von ${messageEscape(r.reporter_name||'Spieler')} · ${messageDate(r.created_at)}</div><p style="white-space:pre-wrap;margin:0;">${messageEscape(r.body)}</p><textarea id="bug-feedback-${r.id}" rows="2" placeholder="Antwort an ${messageEscape(r.reporter_name||'Spieler')}" style="width:100%;box-sizing:border-box;margin-top:12px;resize:vertical;">${messageEscape(r.admin_feedback||'')}</textarea><div class="filter-row" style="margin-top:9px;align-items:center;"><select id="bug-status-${r.id}"><option value="open" ${r.status==='open'?'selected':''}>Offen</option><option value="reviewed" ${r.status==='reviewed'?'selected':''}>In Prüfung</option><option value="fixed" ${r.status==='fixed'?'selected':''}>Behoben</option><option value="closed" ${r.status==='closed'?'selected':''}>Geschlossen</option></select><input id="bug-reward-${r.id}" type="number" min="0" max="500" value="${r.rewarded?0:''}" placeholder="Danke-Coins" style="max-width:130px;"><button class="roll-btn" onclick="resolveBugReport('${r.id}')">Antwort speichern</button></div>${r.rewarded?`<div class="setup-info" style="margin:8px 0 0;">Belohnung bereits vergeben: ${r.reward_coins||0} Coins</div>`:''}</article>`).join('')||'<div class="empty-hint">Keine Bug-Reports offen.</div>';
}
async function resolveBugReport(id){
  if(!currentUser?.is_admin||!sb) return;
  const {data:report,error:loadError}=await sb.from('bug_reports').select('id,reporter_id,reporter_name,rewarded').eq('id',id).maybeSingle();
  if(loadError||!report){showAlert('Bug-Report konnte nicht geladen werden.');return;}
  const feedback=document.getElementById('bug-feedback-'+id)?.value.trim()||'';
  const status=document.getElementById('bug-status-'+id)?.value||'reviewed';
  const requested=Math.max(0,Math.min(500,parseInt(document.getElementById('bug-reward-'+id)?.value,10)||0));
  const reward=report.rewarded?0:requested;
  if(reward){
    const {data:profile,error:profileError}=await sb.from('profiles').select('admin_bonus_points').eq('id',report.reporter_id).maybeSingle();
    if(profileError){showAlert('Coins konnten nicht vorbereitet werden: '+profileError.message);return;}
    const {error:bonusError}=await sb.from('profiles').update({admin_bonus_points:(profile?.admin_bonus_points||0)+reward}).eq('id',report.reporter_id);
    if(bonusError){showAlert('Coins konnten nicht vergeben werden: '+bonusError.message);return;}
  }
  const {error}=await sb.from('bug_reports').update({status,admin_feedback:feedback,reward_coins:reward||undefined,rewarded:report.rewarded||reward>0}).eq('id',id);
  if(error){showAlert('Antwort konnte nicht gespeichert werden: '+error.message);return;}
  await sb.from('player_notifications').insert({target_user_id:report.reporter_id,from_user_id:currentUser.id,icon:status==='fixed'?'✅':'🐞',message:`Antwort zu deinem Bug-Report: ${feedback||bugStatusLabel(status)}${reward?` · +${reward} Shop-Coins`:''}`});
  showToast('Antwort gespeichert und live versendet.','✅'); renderAdminBugReportsTab();
}
// ===== Spiele vorschlagen =====
// ERFORDERT Supabase-Tabelle "game_suggestions", siehe SQL-Hinweis im Chat.
async function submitGameSuggestion(){
  if(!currentUser || !sb){ showAlert('Für Spielvorschläge wird ein Account benötigt.', '👤'); return; }
  const nameEl = document.getElementById('suggest-game-name');
  const descEl = document.getElementById('suggest-game-desc');
  const steamEl = document.getElementById('suggest-game-steam');
  const name = nameEl.value.trim();
  const steamUrl = steamEl.value.trim();
  const desc = [descEl.value.trim(), steamUrl ? `Steam-Seite: ${steamUrl}` : ''].filter(Boolean).join('\n');
  if(!name){ showAlert('Bitte einen Spielnamen eingeben.'); return; }
  const { data:createdSuggestion, error } = await sb.from('game_suggestions').insert({
    suggested_by: currentUser.id, suggested_by_name: currentUser.username, game_name: name, description: desc, status: 'pending',
  });
  if(error){ showAlert('Vorschlag konnte nicht gespeichert werden: '+error.message+' — evtl. fehlt die Tabelle game_suggestions in Supabase.'); return; }
  nameEl.value = ''; descEl.value = ''; steamEl.value = '';
  try{
    const {data:admins}=await sb.from('profiles').select('id').eq('is_admin',true);
    const rows=(admins||[]).filter(a=>a.id!==currentUser.id).map(a=>({target_user_id:a.id,from_user_id:currentUser.id,icon:'💡',message:`Neuer Spielvorschlag von ${currentUser.username}: ${name}\n[wc-request:game:${createdSuggestion?.id||''}]`}));
    if(rows.length) await sb.from('player_notifications').insert(rows);
  }catch(e){ console.warn('Admin-Hinweis für Spielvorschlag konnte nicht erstellt werden:',e); }
  showToast('Vorschlag gesendet — der Admin meldet sich zurück.', '📨', 3200);
  loadMyGameSuggestions();
}
async function loadMyGameSuggestions(){
  const el = document.getElementById('my-game-suggestions');
  if(!el) return;
  if(!currentUser || !sb){ el.innerHTML = ''; return; }
  const { data, error } = await sb.from('game_suggestions').select('id, game_name, description, status, admin_feedback').eq('suggested_by', currentUser.id).order('created_at', {ascending:false});
  if(error || !data || !data.length){ el.innerHTML = ''; return; }
  const statusLabel = { pending:'⏳ Wartet auf Rückmeldung', approved:'✅ Wird hinzugefügt', rejected:'❌ Nicht diesmal' };
  el.innerHTML = `<div class="setup-info" style="margin-bottom:4px;"><strong>Eure Vorschläge:</strong></div>` + data.map(s=>
    `<div class="settings-row-sub" style="margin-top:4px;">${s.game_name} — ${statusLabel[s.status]||s.status}${s.admin_feedback?` · „${s.admin_feedback}“`:''}</div>`
  ).join('');
}
async function renderAdminGameSuggestionsTab(){
  const listEl = document.getElementById('admin-game-suggestions-list');
  if(!listEl) return;
  if(!sb){ listEl.innerHTML = '<div class="empty-hint">Keine Verbindung zur Cloud.</div>'; return; }
  listEl.innerHTML = '<div class="empty-hint">Lädt…</div>';
  const { data, error } = await sb.from('game_suggestions').select('id, game_name, description, status, suggested_by_name').eq('status','pending').order('created_at', {ascending:false});
  if(error){ listEl.innerHTML = `<div class="empty-hint">Fehler beim Laden (evtl. fehlt die Tabelle game_suggestions): ${error.message}</div>`; return; }
  if(!data || !data.length){ listEl.innerHTML = '<div class="empty-hint">Aktuell keine offenen Spielvorschläge. 🎉</div>'; return; }
  let html = '';
  data.forEach(s=>{
    html += `<div class="settings-card" style="margin-bottom:10px;">
      <div class="setup-step-title" style="font-size:1rem;">${s.game_name} <span style="color:var(--text-faint);font-size:0.78rem;font-weight:500;">· von ${s.suggested_by_name||'?'}</span></div>
      ${s.description ? `<p class="setup-info" style="margin:4px 0 8px;">${s.description}</p>` : ''}
      <input type="text" id="admin-suggest-feedback-${s.id}" placeholder="Kurze Rückmeldung (optional)" style="width:100%;box-sizing:border-box;margin-bottom:8px;">
      <div class="roll-zone" style="gap:8px;margin-bottom:0;">
        <button class="sb-btn" onclick="resolveGameSuggestion('${s.id}','approved')">✅ Wird hinzugefügt</button>
        <button class="sb-btn danger" onclick="resolveGameSuggestion('${s.id}','rejected')">❌ Nicht diesmal</button>
      </div>
    </div>`;
  });
  listEl.innerHTML = html;
}
async function resolveGameSuggestion(id, status){
  if(!sb) return;
  const feedbackEl = document.getElementById('admin-suggest-feedback-'+id);
  const admin_feedback = feedbackEl ? feedbackEl.value.trim() : '';
  const { data, error } = await sb.from('game_suggestions').update({ status, admin_feedback }).eq('id', id).select('suggested_by, game_name').maybeSingle();
  if(error){ showAlert('Fehler: '+error.message); return; }
  // Vorschlagende Person direkt benachrichtigen, statt dass sie es nur zufällig beim nächsten
  // Besuch der Spiele-Seite sieht.
  if(data && data.suggested_by){
    try{
      await sb.from('player_notifications').insert({
        target_user_id: data.suggested_by, from_user_id: currentUser.id, icon: status==='approved'?'✅':'❌',
        message: status==='approved' ? `Euer Spielvorschlag „${data.game_name}“ wird hinzugefügt!` : `Euer Spielvorschlag „${data.game_name}“ wird (vorerst) nicht umgesetzt.${admin_feedback?' — '+admin_feedback:''}`,
      });
    }catch(e){ console.error(e); }
  }
  renderAdminGameSuggestionsTab();
}
function adminRaiseAchievementLevel(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const s = statsStore[name];
  s.achievementsClaimed = s.achievementsClaimed || [];
  const next = ACHIEVEMENTS_DEF.find(a=>!s.achievementsClaimed.includes(a.id));
  if(!next){ showAlert('Schon alle Achievements freigeschaltet.', '🏆'); return; }
  s.achievementsClaimed.push(next.id);
  s.totalPoints = (s.totalPoints||0) + next.reward;
  addCoins(name, next.reward);
  grantAllAchievementsRewardIfNeeded(name, s);
  saveStats();
  syncCosmeticsForNameToProfile(name);
  renderAdminPointsTab();
}
function adminLowerAchievementLevel(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const s = statsStore[name];
  s.achievementsClaimed = s.achievementsClaimed || [];
  const lastId = s.achievementsClaimed.pop();
  if(!lastId) return;
  const a = ACHIEVEMENTS_DEF.find(x=>x.id===lastId);
  if(a){ s.totalPoints = Math.max(0, (s.totalPoints||0) - a.reward); addCoins(name, -a.reward); }
  enforceAchievementLocksAfterChange(name, s);
  saveStats();
  syncCosmeticsForNameToProfile(name);
  renderAdminPointsTab();
}
function adminUnlockAllAchievements(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const s = statsStore[name];
  s.achievementsClaimed = s.achievementsClaimed || [];
  ACHIEVEMENTS_DEF.forEach(a=>{
    if(!s.achievementsClaimed.includes(a.id)){ s.achievementsClaimed.push(a.id); s.totalPoints = (s.totalPoints||0) + a.reward; addCoins(name, a.reward); }
  });
  grantAllAchievementsRewardIfNeeded(name, s);
  saveStats();
  syncCosmeticsForNameToProfile(name);
  renderAdminPointsTab();
}
async function adminResetAchievements(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]) return;
  if(!(await confirmAction('Achievements für '+name+' wirklich zurücksetzen? Die dafür erhaltenen Punkte werden wieder abgezogen.'))) return;
  const s = statsStore[name];
  const claimed = s.achievementsClaimed || [];
  const totalReward = claimed.reduce((sum,id)=>{ const a = ACHIEVEMENTS_DEF.find(x=>x.id===id); return sum + (a?a.reward:0); }, 0);
  s.totalPoints = Math.max(0, (s.totalPoints||0) - totalReward);
  addCoins(name, -totalReward);
  s.achievementsClaimed = [];
  enforceAchievementLocksAfterChange(name, s);
  saveStats();
  syncCosmeticsForNameToProfile(name);
  renderAdminPointsTab();
  showAlert('Achievements für '+name+' wurden zurückgesetzt.', '🔄');
}
function adminResetSpent(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]){ showAlert('Kein lokaler Spieler ausgewählt.'); return; }
  const s = statsStore[name];
  const oldCoins = ensureCoins(s);
  s.coins = 0; s.spent = 0; s.shopBonus = 0;
  saveStats();
  if(currentUser && name===currentUser.username) syncFullStatsToCloud(name);
  if(document.getElementById('view-shop').classList.contains('active')) renderShopPage();
  const status=document.getElementById('admin-spent-status');
  if(status) status.textContent = `Guthaben für ${name} auf 0 gesetzt (war: ${oldCoins}).`;
  showToast(`Guthaben für ${name} auf 0 gesetzt (war: ${oldCoins}).`, '🧹', 3500);
  renderAdminPointsTab();
}
function adminAddPoints(){
  const name = adminPointsSelectedPlayer;
  if(!name || !statsStore[name]){ showAlert('Kein lokaler Spieler ausgewählt.'); return; }
  const amount = parseInt(document.getElementById('admin-points-amount').value, 10);
  if(!amount || amount === 0){ showAlert('Bitte eine Zahl ungleich 0 eingeben.'); return; }
  const s = statsStore[name];
  s.totalPoints = (s.totalPoints||0) + amount; // bleibt als Lebenszeit-Statistik erhalten
  const newBalance = addCoins(name, amount);
  saveStats();
  if(currentUser && name===currentUser.username) syncFullStatsToCloud(name);
  if(document.getElementById('view-shop').classList.contains('active')) renderShopPage();
  if(document.getElementById('view-stats').classList.contains('active')) renderStatsPage();
  showToast(`${amount>0?'+':''}${amount} Punkte für ${name} — neues Guthaben: ${newBalance}`, '🪙', 3500);
  renderAdminPointsTab();
}
async function renderAdminUsers(){
  const el = document.getElementById('admin-users-list');
  if(!sb) return;
  el.innerHTML = '<div class="empty-hint" style="padding:10px;">Lade…</div>';
  const { data, error } = await sb.from('profiles').select('*').order('created_at');
  if(error || !data){ el.innerHTML = '<div class="empty-hint">Fehler beim Laden.</div>'; return; }
  el.innerHTML = '';
  data.forEach(u=>{
    const row = document.createElement('div');
    row.className = 'chip readonly';
    row.style.width = '100%'; row.style.justifyContent = 'space-between'; row.style.marginBottom = '8px'; row.style.flexWrap = 'wrap'; row.style.rowGap = '8px';
    row.innerHTML = `<span>${renderAccountAvatarHTML(u.avatar,20)} ${u.username}${u.is_admin?' 🛡️':''}${u.is_banned?' 🚫':''}<br><span style="color:var(--text-muted); font-size:0.78rem;">${u.email||'—'}</span></span>`;
    const actions = document.createElement('span'); actions.style.display = 'flex'; actions.style.gap = '6px'; actions.style.flexWrap = 'wrap'; actions.style.justifyContent = 'flex-end';
    const adminBtn = document.createElement('button'); adminBtn.className = 'sb-btn'; adminBtn.textContent = u.is_admin ? 'Admin entfernen' : 'Zu Admin machen';
    adminBtn.addEventListener('click', ()=>toggleAdminFlag(u.id, !u.is_admin));
    const banBtn = document.createElement('button'); banBtn.className = 'sb-btn danger'; banBtn.textContent = u.is_banned ? 'Entsperren' : 'Sperren';
    banBtn.addEventListener('click', ()=>toggleBanFlag(u.id, !u.is_banned));
    // Coins geben: da die Punkte/Guthaben-Stände lokal auf dem jeweiligen Gerät des Nutzers liegen
    // (nicht serverseitig), landet der Betrag als "admin_bonus_points" im Profil und wird beim
    // nächsten Öffnen der App auf DESSEN Gerät automatisch gutgeschrieben (siehe applyAdminAdjustments).
    const coinsInput = document.createElement('input');
    coinsInput.type = 'number'; coinsInput.placeholder = 'Coins'; coinsInput.min = '1';
    coinsInput.style.cssText = 'width:80px;padding:8px 10px;border-radius:10px;border:1px solid var(--border);background:var(--bg-elevated);color:var(--text);';
    const giveBtn = document.createElement('button'); giveBtn.className = 'sb-btn'; giveBtn.textContent = '💰 Geben';
    giveBtn.addEventListener('click', ()=>{
      const amt = parseInt(coinsInput.value, 10);
      if(!amt || amt <= 0){ showAlert('Bitte eine gültige Coin-Zahl eingeben.'); return; }
      adminGiveCoins(u.id, u.username, amt);
      coinsInput.value = '';
    });
    const resetBtn = document.createElement('button'); resetBtn.className = 'sb-btn danger'; resetBtn.textContent = '♻️ Komplett zurücksetzen';
    resetBtn.addEventListener('click', ()=>adminResetUser(u.id, u.username));
    actions.appendChild(adminBtn); actions.appendChild(banBtn); actions.appendChild(coinsInput); actions.appendChild(giveBtn); actions.appendChild(resetBtn);
    row.appendChild(actions);
    el.appendChild(row);
  });
  if(!data.length) el.innerHTML = '<div class="empty-hint">Keine Nutzer gefunden.</div>';
}
async function toggleAdminFlag(userId, val){ if(!sb) return; await sb.from('profiles').update({ is_admin: val }).eq('id', userId); renderAdminUsers(); }
async function toggleBanFlag(userId, val){ if(!sb) return; await sb.from('profiles').update({ is_banned: val }).eq('id', userId); renderAdminUsers(); }
async function adminGiveCoins(userId, username, amount){
  if(!sb) return;
  try{
    const { data } = await sb.from('profiles').select('admin_bonus_points').eq('id', userId).maybeSingle();
    const current = (data && data.admin_bonus_points) || 0;
    const { error } = await sb.from('profiles').update({ admin_bonus_points: current + amount }).eq('id', userId);
    if(error) throw error;
    if(currentUser && userId===currentUser.id){
      // Sich selbst Coins geben soll sofort wirken, nicht erst beim nächsten App-Start.
      await applyAdminAdjustments();
      if(document.getElementById('view-shop')?.classList.contains('active')) renderShopPage();
      showAlert(`${amount} Coins gutgeschrieben — direkt wirksam.`, '💰');
    } else {
      showAlert(`${amount} Coins an ${username} vergeben — werden gutgeschrieben, sobald ${username} die App das nächste Mal öffnet.`, '💰');
    }
  }catch(e){ showAlert('Fehler beim Vergeben: ' + e.message); }
}
async function adminResetUser(userId, username){
  if(!sb) return;
  if(!(await confirmAction(`${username} WIRKLICH komplett zurücksetzen? Statistiken, Coins, Käufe und ausgerüstete Kosmetik werden gelöscht, sobald ${username} die App das nächste Mal öffnet. Das kann nicht rückgängig gemacht werden.`))) return;
  try{
    const { error } = await sb.from('profiles').update({
      admin_bonus_points: 0, admin_reset_pending: true,
      equipped_badge: null, equipped_hat: null, equipped_banner: null, equipped_glow: null, equipped_frame: null,
    }).eq('id', userId);
    if(error) throw error;
    showAlert(`${username} wird beim nächsten Öffnen der App komplett zurückgesetzt.`, '♻️');
    renderAdminUsers();
  }catch(e){ showAlert('Fehler beim Zurücksetzen: ' + e.message); }
}
// Wird beim Login/Session-Wiederherstellen für den EIGENEN Account geprüft — Admin-Vergaben und
// -Resets landen serverseitig im Profil und werden hier auf das lokale Gerät angewendet, weil
// Punkte/Statistiken/Käufe (statsStore) rein lokal pro Gerät gespeichert sind, nicht zentral.
async function applyAdminAdjustments(){
  if(!currentUser || !sb) return;
  try{
    const { data } = await sb.from('profiles').select('admin_bonus_points, admin_reset_pending').eq('id', currentUser.id).maybeSingle();
    if(!data) return;
    const clear = {};
    if(data.admin_reset_pending){
      delete statsStore[currentUser.username];
      saveStats();
      clear.admin_reset_pending = false;
      clear.admin_bonus_points = 0;
      clear.full_stats = null;
      showAlert('Ein Admin hat deinen Account komplett zurückgesetzt.', '♻️');
    } else if(data.admin_bonus_points && data.admin_bonus_points > 0){
      const s = statsStore[currentUser.username] = statsStore[currentUser.username] || { totalPoints:0, roundsPlayed:0, roundWins:0, challengesWon:0, challengesLost:0, bestRoundScore:-Infinity, currentRoundStreak:0, bestRoundStreak:0, gamesPlayed:{} };
      s.totalPoints = (s.totalPoints||0) + data.admin_bonus_points;
      addCoins(currentUser.username, data.admin_bonus_points);
      saveStats();
      showAlert(`Ein Admin hat dir ${data.admin_bonus_points} Coins geschenkt!`, '💰');
      clear.admin_bonus_points = 0;
    }
    if(Object.keys(clear).length) await sb.from('profiles').update(clear).eq('id', currentUser.id);
  }catch(e){ console.error(e); }
}

let adminSelectedHeroGame = 'ow2';
function renderAdminHeroGamePicker(){
  const row = document.getElementById('admin-hero-game-select'); row.innerHTML = '';
  Object.keys(HERO_GAMES).forEach(id=>{
    const btn = document.createElement('button');
    btn.className = 'filter-pill'+(id===adminSelectedHeroGame?' active':'');
    btn.innerHTML = gameIconHTML(id,18)+' '+GAME_NAME[id];
    btn.addEventListener('click', ()=>{ adminSelectedHeroGame = id; renderAdminHeroGamePicker(); });
    row.appendChild(btn);
  });
  renderAdminHeroList();
}
function renderAdminHeroList(){
  const el = document.getElementById('admin-hero-list'); el.innerHTML = '';
  const heroes = HERO_GAMES[adminSelectedHeroGame];
  const list = document.createElement('div'); list.className = 'solo-hero-list';
  heroes.forEach(([name, role])=>{
    const meta = ROLE_META[role]; const img = heroImageFor(adminSelectedHeroGame, name);
    const item = document.createElement('div'); item.className = 'solo-hero-item'; item.style.opacity = 1; item.style.transform = 'none';
    item.innerHTML = `<div class="solo-avatar" style="background:${img?'#000':heroColor(name)}; overflow:hidden;">${heroAvatarInner(name,adminSelectedHeroGame)}<span class="avatar-badge" style="background:${meta.color}">${meta.icon}</span></div>
      <div class="solo-info"><div class="solo-player">${role}</div><div class="solo-hero">${name}</div></div>`;
    const label = document.createElement('label'); label.className = 'sb-btn'; label.style.cursor = 'pointer'; label.textContent = img ? '📷 Ersetzen' : '📷 Hochladen';
    const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*'; input.style.display = 'none';
    input.addEventListener('change', ()=>{ if(input.files[0]) uploadHeroImage(adminSelectedHeroGame, name, input.files[0]); });
    label.appendChild(input);
    item.appendChild(label);
    list.appendChild(item);
  });
  el.appendChild(list);
}
// Bilder werden jetzt unter "gameId:Heldenname" gespeichert (nicht mehr nur "Heldenname") — sonst
// hätten sich gleichnamige Helden aus verschiedenen Spielen gegenseitig überschrieben (z. B. Echo
// bei Overwatch vs. Echo bei Rainbow Six Siege). Bereits vorhandene alte Bilder unter dem bloßen
// Namen bleiben als Fallback weiter gültig (siehe heroImageFor).
function uploadHeroImage(gameId, heroName, file){
  resizeImageToDataUrl(file, 160, async dataUrl=>{
    heroImageCache[gameId+':'+heroName] = dataUrl;
    renderAdminHeroList();
    if(sb){ await sb.from('hero_images').upsert({ hero_name: gameId+':'+heroName, image_data: dataUrl }); }
  });
}
function renderAdminGameCoverList(){
  const el = document.getElementById('admin-cover-list'); if(!el) return;
  el.innerHTML = '';
  GAMES.forEach(g=>{
    const cover = gameCoverCache[g.id];
    const row = document.createElement('div'); row.className = 'solo-hero-item'; row.style.opacity = 1; row.style.transform = 'none'; row.style.flexWrap = 'wrap';
    row.innerHTML = `<div class="solo-avatar" style="background:${cover?'#000':'var(--bg-elevated)'}; overflow:hidden; font-size:1.4rem;">${cover?`<img src="${cover}" style="width:100%;height:100%;object-fit:cover;">`:g.icon}</div>
      <div class="solo-info"><div class="solo-player">${g.tag}</div><div class="solo-hero">${g.name}</div></div>`;
    const urlInput = document.createElement('input'); urlInput.type = 'text'; urlInput.placeholder = 'Bild-URL (https://…)'; urlInput.value = (cover && cover.indexOf('http')===0) ? cover : '';
    urlInput.style.cssText = 'flex:1; min-width:160px; background:var(--bg-elevated); border:1px solid var(--border); border-radius:10px; padding:8px 10px; color:var(--text); font-size:0.82rem;';
    const urlBtn = document.createElement('button'); urlBtn.className = 'sb-btn'; urlBtn.textContent = '🌐 Übernehmen';
    urlBtn.addEventListener('click', ()=>{ if(urlInput.value.trim()) setGameCoverUrl(g.id, urlInput.value.trim()); });
    const uploadLabel = document.createElement('label'); uploadLabel.className = 'sb-btn'; uploadLabel.style.cursor = 'pointer'; uploadLabel.textContent = cover ? '📷 Ersetzen' : '📷 Hochladen';
    const fileInput = document.createElement('input'); fileInput.type = 'file'; fileInput.accept = 'image/*'; fileInput.style.display = 'none';
    fileInput.addEventListener('change', ()=>{ if(fileInput.files[0]) uploadGameCoverImage(g.id, fileInput.files[0]); });
    uploadLabel.appendChild(fileInput);
    row.appendChild(urlInput); row.appendChild(urlBtn); row.appendChild(uploadLabel);
    if(cover){ const rmBtn = document.createElement('button'); rmBtn.className = 'sb-btn danger'; rmBtn.textContent = '✕'; rmBtn.addEventListener('click', ()=>removeGameCover(g.id)); row.appendChild(rmBtn); }
    el.appendChild(row);
  });
}
async function uploadGameCoverImage(gameId, file){
  const dataUrl = await resizeBlobToDataUrl(file, 500);
  gameCoverCache[gameId] = dataUrl;
  renderTileGrid(); renderAdminGameCoverList(); refreshGamePageIcons();
  if(sb) await sb.from('game_covers').upsert({ game_id: gameId, image_data: dataUrl });
}
async function setGameCoverUrl(gameId, url){
  gameCoverCache[gameId] = url;
  renderTileGrid(); renderAdminGameCoverList(); refreshGamePageIcons();
  if(sb) await sb.from('game_covers').upsert({ game_id: gameId, image_data: url });
}
async function removeGameCover(gameId){
  delete gameCoverCache[gameId];
  renderTileGrid(); renderAdminGameCoverList(); refreshGamePageIcons();
  if(sb) await sb.from('game_covers').delete().eq('game_id', gameId);
}
function resizeBlobToDataUrl(blob, size){
  return new Promise(resolve=>{ resizeImageToDataUrl(blob, size, resolve); });
}
function normalizeHeroKey(s){ return s.toLowerCase().replace(/[^a-z0-9]/g,''); }
document.getElementById('admin-hero-zip-input').addEventListener('change', async e=>{
  const file = e.target.files[0]; if(!file) return;
  const statusEl = document.getElementById('admin-zip-status');
  statusEl.style.color = 'var(--turquoise-bright)';
  statusEl.textContent = 'Verarbeite ZIP…';
  try{
    // Vorher fest auf OW2/MR/FP begrenzt (VAL/FINALS/R6 gingen leer aus) und Keys nur nach bloßem
    // Namen — jetzt auf das im Admin-Bereich ausgewählte Spiel skaliert (analog zum Einzel-Upload)
    // und mit spielspezifischem Key, damit sich gleichnamige Helden nicht mehr überschreiben.
    const allHeroNames = [...new Set((HERO_GAMES[adminSelectedHeroGame]||[]).map(h=>h[0]))];
    const lookup = {};
    allHeroNames.forEach(name=>{ lookup[normalizeHeroKey(name)] = name; });

    const zip = await JSZip.loadAsync(file);
    const entries = Object.values(zip.files).filter(f=>!f.dir && /\.(png|jpe?g|webp)$/i.test(f.name));
    let matched = 0; const unmatched = [];
    for(const entry of entries){
      const baseName = entry.name.split('/').pop().replace(/\.(png|jpe?g|webp)$/i, '');
      const heroName = lookup[normalizeHeroKey(baseName)];
      if(!heroName){ unmatched.push(entry.name); continue; }
      const blob = await entry.async('blob');
      const dataUrl = await resizeBlobToDataUrl(blob, 160);
      heroImageCache[adminSelectedHeroGame+':'+heroName] = dataUrl;
      if(sb) await sb.from('hero_images').upsert({ hero_name: adminSelectedHeroGame+':'+heroName, image_data: dataUrl });
      matched++;
    }
    statusEl.textContent = `${matched} Bild(er) für ${GAME_NAME[adminSelectedHeroGame]} zugeordnet und hochgeladen.` + (unmatched.length ? ` Nicht erkannt: ${unmatched.join(', ')}` : '');
    renderAdminHeroList();
  }catch(err){
    statusEl.style.color = 'var(--lose)';
    statusEl.textContent = 'Fehler beim Verarbeiten der ZIP-Datei: ' + err.message;
  }
  e.target.value = '';
});

