const ROLE_WEIGHTS = { ow2:{Tank:1,Damage:2,Support:2}, mr:{Tank:1,Damage:2,Support:2}, fp:{Attack:3,Support:2}, val:{Duelist:1,Initiator:1,Controller:1,Sentinel:1}, finals:{Light:1,Medium:1,Heavy:2}, r6:{Angriff:1,Verteidigung:1} };
function rolesForGame(gameId){ const w = ROLE_WEIGHTS[gameId]; return w ? Object.keys(w) : null; }
/* Held-Pool ggf. auf eine einzelne Rolle einschränken (für den Rollen-Filter oder für einen
   Joker-Reroll, der konsistent innerhalb derselben Rolle bleiben soll). */
function heroPoolForRole(gameId, role){
  const base = HERO_GAMES[gameId];
  if(!base || !role || role==='all') return base;
  const filtered = base.filter(h=>h[1]===role);
  return filtered.length ? filtered : base;
}
function hasAnyRoleChoice(roleMap){ return !!roleMap && Object.values(roleMap).some(r=>r && r!=='all'); }
/* Jede/r Spieler:in kann ihre/seine eigene Wunschrolle wählen (statt dass das ganze Team dieselbe
   Rolle bekommt). roleMap ordnet jedem Spieler-Key (user_id im Team-Modus, Spielername lokal)
   optional eine Rolle zu; wer nichts gewählt hat, bekommt zufällig eine der verbleibenden Helden. */
function assignHeroesByPlayerRoles(gameId, playerKeys, roleMap){
  const pool = HERO_GAMES[gameId];
  if(!pool) return null;
  const used = new Set();
  const result = {};
  const withRole = playerKeys.filter(k => roleMap && roleMap[k] && roleMap[k] !== 'all');
  const withoutRole = playerKeys.filter(k => withRole.indexOf(k) === -1);
  withRole.forEach(k=>{
    const role = roleMap[k];
    let choices = pool.filter(h=> h[1]===role && !used.has(h[0]));
    if(!choices.length) choices = pool.filter(h=>h[1]===role); // Pool zu klein: Wiederholung erlauben
    if(!choices.length) choices = pool; // Rolle existiert in diesem Spiel nicht -> Fallback
    const member = teamMembers.find(m=>m.user_id===k);
    const favorites = (member && member.hero_favorites && member.hero_favorites[gameId+':'+role]) ||
      ((currentUser && (k===currentUser.id || k===currentUser.username) && currentUser.hero_favorites && currentUser.hero_favorites[gameId+':'+role]) || []);
    const preferredChoices = teamRoundUseHeroFavorites ? choices.filter(h=>favorites.includes(h[0])) : [];
    if(preferredChoices.length) choices = preferredChoices;
    const hero = pickHeroAvoidingRecent(choices, k, gameId);
    result[k] = hero; used.add(hero[0]);
  });
  withoutRole.forEach(k=>{
    let choices = pool.filter(h=>!used.has(h[0]));
    if(!choices.length) choices = pool;
    const hero = pickHeroAvoidingRecent(choices, k, gameId);
    result[k] = hero; used.add(hero[0]);
  });
  return result;
}
const GAME_MODE_RESTRICTIONS = { fg:['versus'], ph:['team'], repo:['team'], lethal:['team'], cw:['team'], wwm:['team'], hff:['team'], crab:['versus'], pico:['team'] };
