function matchStyleFor(gameId, gameMode){
  const info = GAME_MODES[gameId] && GAME_MODES[gameId].find(m=>m.key===gameMode);
  return info ? info.style : null;
}
function isNoRoundsMode(gameId, gameMode){
  const info = GAME_MODES[gameId] && GAME_MODES[gameId].find(m=>m.key===gameMode);
  return !!(info && info.noRounds);
}
function roundOptionsFor(gameId, gameMode, forceMatch){
  const info = GAME_MODES[gameId] && GAME_MODES[gameId].find(m=>m.key===gameMode);
  if(info && info.fixedRounds) return [info.fixedRounds];
  if(info && info.noRounds) return [1];
  return (forceMatch || matchStyleFor(gameId, gameMode)==='match') ? [1,2,3,5] : (GAME_ROUND_PRESETS[gameId] || [1,3,5,7,9,11]);
}
/* Baut die tatsächliche Spielreihenfolge für scope 'games' ("Nach Spielen") aus der Spiele-Auswahl:
   roundsPerGame ist entweder eine feste Zahl (jedes Spiel kommt so oft dran) oder 'random' (1-3x
   zufällig pro Spiel). randomOrder=false behält die Auswahl-Reihenfolge bei, sonst wird gemischt. */
function buildGameSequence(games, roundsPerGame, randomOrder){
  // WICHTIG: es wird die Reihenfolge der SPIELE gemischt, nicht jede einzelne Runde für sich —
  // sonst würden bei "Runden pro Spiel" > 1 die Runden verschiedener Spiele durcheinandergewürfelt
  // (z. B. Overwatch/Fortnite/Overwatch) statt block-weise hintereinander zu bleiben.
  let blocks = (games||[]).map(id=>{
    const n = roundsPerGame==='random' ? randInt(1,3) : (roundsPerGame||1);
    return Array(n).fill(id);
  });
  if(randomOrder!==false) blocks = shuffle(blocks);
  return [].concat(...blocks);
}
function allowedModesFor(gameId){ return GAME_MODE_RESTRICTIONS[gameId] || ['team','versus']; }
function allowedModesForSelection(){
  if(setupState.scope === 'rounds' || setupState.scope === 'match'){
    return setupState.gameId ? allowedModesFor(setupState.gameId) : ['team','versus'];
  }
  if(!setupState.selectedGames.length) return ['team','versus'];
  let allowed = ['team','versus'];
  setupState.selectedGames.forEach(id=>{ allowed = allowed.filter(m=>allowedModesFor(id).includes(m)); });
  return allowed.length ? allowed : ['team','versus'];
}
const ROLE_META = {
  Tank:{icon:'🛡️', color:'var(--tank)'}, Damage:{icon:'⚔️', color:'var(--damage)'},
  Support:{icon:'➕', color:'var(--support)'}, Attack:{icon:'⚔️', color:'var(--damage)'},
  Duelist:{icon:'⚔️', color:'#f87171'}, Initiator:{icon:'🎯', color:'var(--turquoise)'},
  Controller:{icon:'🌀', color:'var(--purple)'}, Sentinel:{icon:'🛡️', color:'#34d399'},
  Light:{icon:'🏃', color:'var(--turquoise)'}, Medium:{icon:'💊', color:'var(--gold)'}, Heavy:{icon:'🛡️', color:'var(--purple)'},
  Angriff:{icon:'💥', color:'var(--damage)'}, Verteidigung:{icon:'🧱', color:'var(--tank)'},
};

/* ============================================================ RULES POOLS (shared, team-wide) ============================================================ */
function C(text, diff, theme, roles){ return {text, diff, theme, roles}; }
/* Ersetzt {player} in einem Challenge-Text durch einen zufälligen echten Spielernamen (den die
   Spieler sich selbst gegeben haben — globalPlayers/teamMembers), z. B. "Nur {player} darf in
   der ersten Halbzeit die Ult nutzen." -> "Nur Marlon darf...". Ohne Spielerliste bleibt der
   Platzhalter als generischer Fallback stehen. */
function substitutePlayerName(text, players){
  if(!text || text.indexOf('{player}') === -1) return text;
  const name = (players && players.length) ? players[randInt(0, players.length-1)] : 'jemand aus eurer Runde';
  return text.split('{player}').join(name);
}
function substitutePlayerNames(items, players){ return items.map(c=> c.text.indexOf('{player}')!==-1 ? Object.assign({}, c, { text: substitutePlayerName(c.text, players) }) : c); }

