let personalityChallengesEnabled = true; // Host-Einstellung: PERSONALITY_CHALLENGES zumischen ja/nein (siehe setupState.funChallenges / teamRoundFunChallenges), Standard An wie bisher
let communityChallengesEnabled = true; // Host-Einstellung: freigegebene Community-Challenges zumischen ja/nein
function libraryDisabledKey(){ return currentUser ? `winchallenge_library_disabled_${currentUser.id}` : 'winchallenge_library_disabled_guest'; }
function loadLibraryDisabled(){ try{ return new Set(JSON.parse(localStorage.getItem(libraryDisabledKey())||'[]')); }catch(e){ return new Set(); } }
function saveLibraryDisabled(set){ try{ localStorage.setItem(libraryDisabledKey(), JSON.stringify([...set])); }catch(e){} }
function challengeKey(gameId, text){ return gameId+'::'+text; }
function isChallengeDisabled(gameId, text){ return loadLibraryDisabled().has(challengeKey(gameId, text)); }
function toggleChallengeDisabled(gameId, text){
  const set=loadLibraryDisabled(); const key=challengeKey(gameId, text);
  if(set.has(key)) set.delete(key); else set.add(key);
  saveLibraryDisabled(set);
  renderChallengeLibrary();
}
function filterDisabledChallenges(gameId, arr){ const disabled=loadLibraryDisabled(); return (arr||[]).filter(c=>!disabled.has(challengeKey(gameId, c.text))); }
function rulesPoolFor(gameId, gameMode){
  const override = MODE_CHALLENGE_OVERRIDES[gameId+'_'+gameMode];
  const base = override ? override.rules : CHALLENGE_SOURCES[gameId];
  const custom = communityChallengesEnabled ? (customChallenges[gameId] || []).filter(c=>c.scope==='shared' && c.approved!==false).map(c=>C(c.text, c.diff, 'custom')) : [];
  const personality = personalityChallengesEnabled ? PERSONALITY_CHALLENGES : [];
  return filterDisabledChallenges(gameId, base).concat(personality).concat(filterDisabledChallenges(gameId, custom));
}
function personalPoolFor(gameId, gameMode){
  const override = MODE_CHALLENGE_OVERRIDES[gameId+'_'+gameMode];
  const base = filterDisabledChallenges(gameId, override ? override.personal : PERSONAL_SOURCES[gameId]);
  const custom = communityChallengesEnabled ? filterDisabledChallenges(gameId, (customChallenges[gameId] || []).filter(c=>c.scope==='personal' && c.approved!==false).map(c=>C(c.text, c.diff, 'custom'))) : [];
  return custom.length ? base.concat(custom) : base;
}
