// Sportliche Aufgaben dürfen nur Verhalten verlangen, das die Gruppe selbst steuern kann.
// Zufällige Match-Ergebnisse, Gegner-Leistungen, Ranglisten und "als Erste/r"-Rennen werden
// deshalb weder im Team- noch im Jeder-gegen-jeden-Pool für Sportspiele zugemischt.
function removeUncontrollableSportChallenges(pool){
  const blocked=/(gewinnt|erste[rs]? tor|meiste tore|meiste vorlagen|meiste rettungen|hattrick|rückstand|gegentor|shutout|verlängerung|beste gesamt|bestes einzelloch|wenigste schläg|drei löcher|höchste ballbeteiligung|als erste\(r\)|erste[rn]? erfolgreiche)/i;
  for(let i=pool.length-1;i>=0;i--) if(blocked.test(pool[i].text)) pool.splice(i,1);
}
[GOLF_CHALLENGES,GOLF_PERSONAL,RL_CHALLENGES,RL_PERSONAL,GB_CHALLENGES,GB_PERSONAL].forEach(removeUncontrollableSportChallenges);

