/* Bibliothek: Die vorhandenen Pools bleiben die einzige Quelle der Wahrheit. Die Kategorien
   werden absichtlich aus den Themen abgeleitet, damit auch neue bzw. eigene Challenges ohne
   zweite, fehleranfällige Datenpflege auffindbar sind. */
let libraryGameFilter = 'all', libraryCategoryFilter = 'all';
const LIBRARY_CATEGORIES = ['Allgemein','Helden','Spielmodus','Teamplay','Kills','Fähigkeiten','Schwierigkeit'];
function libraryCategory(c){
  const t = String(c.theme||'').toLowerCase(), x = String(c.text||'').toLowerCase();
  if(/hero|operator|agent|rolle|ult|fähigkeit|gadget/.test(t+' '+x)) return /ult|fähigkeit|gadget/.test(t+' '+x) ? 'Fähigkeiten' : 'Helden';
  if(/kill|elimination|headshot|ace|deaths|tode/.test(t+' '+x)) return 'Kills';
  if(/team|gemeinsam|alle |miteinander|support/.test(t+' '+x)) return 'Teamplay';
  if(/mode|side|angreifer|verteidiger|bomb|escort|kontroll|push|flashpoint/.test(t+' '+x)) return 'Spielmodus';
  if(c.diff==='schwer') return 'Schwierigkeit';
  return 'Allgemein';
}
function renderChallengeLibrary(){
  const gamesRow=document.getElementById('library-game-filter'), catRow=document.getElementById('library-category-filter'), out=document.getElementById('library-results');
  if(!gamesRow||!catRow||!out) return;
  const make=(row, items, active, set)=>{ row.innerHTML=''; items.forEach(([key,label])=>{ const b=document.createElement('button'); b.className='filter-pill'+(key===active?' active':''); b.textContent=label; b.onclick=()=>{set(key); renderChallengeLibrary();}; row.appendChild(b); }); };
  make(gamesRow, [['all','Alle Spiele'], ['community','⭐ Community'], ...Object.keys(CHALLENGE_SOURCES).map(id=>[id,GAME_NAME[id]||id])], libraryGameFilter, k=>libraryGameFilter=k);
  make(catRow, [['all','Alle Kategorien'], ...LIBRARY_CATEGORIES.map(c=>[c,c])], libraryCategoryFilter, k=>libraryCategoryFilter=k);
  const q=(document.getElementById('library-search').value||'').trim().toLowerCase(); let html='', count=0;
  const disabled=loadLibraryDisabled();
  const renderItem=(gid,c)=>{
    const cat=libraryCategory(c); const key=challengeKey(gid,c.text); const isOff=disabled.has(key);
    return `<div class="sb-challenge-item" style="${isOff?'opacity:0.45;':''}display:flex;align-items:center;gap:10px;">
      <div class="sb-diff-badge" style="background:${DIFF_COLOR[c.diff]}">${DIFF_LABEL[c.diff]}</div>
      <div class="sb-challenge-text" style="flex:1;">${messageEscape(c.text)}${c.createdByName?`<div style="font-size:.72rem;color:var(--turquoise);margin-top:2px;">von ${messageEscape(c.createdByName)}</div>`:''}<div style="font-size:.72rem;color:var(--text-faint);margin-top:4px;">${cat}${cat==='Spielmodus'?' · modusgebunden':''}</div></div>
      <button class="sb-btn${isOff?'':' danger'}" style="flex:none;" onclick="toggleChallengeDisabled('${gid}','${c.text.replace(/'/g,"\\'")}')">${isOff?'Aktivieren':'Abwählen'}</button>
    </div>`;
  };
  if(libraryGameFilter==='community'){
    Object.entries(customChallenges).forEach(([gid,pool])=>{
      const items=(pool||[]).filter(c=>c.approved!==false).filter(c=>(libraryCategoryFilter==='all'||libraryCategory(c)===libraryCategoryFilter)&&(!q||c.text.toLowerCase().includes(q)||libraryCategory(c).toLowerCase().includes(q)));
      if(!items.length) return; count+=items.length;
      html+=`<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">${gameIconHTML(gid,20)}</span><div class="setup-step-title">${GAME_NAME[gid]||gid}</div></div>`;
      items.forEach(c=>{ html+=renderItem(gid,c); }); html+='</div>';
    });
    out.innerHTML=html||'<div class="empty-hint">Noch keine freigegebenen Community-Challenges.</div>';
    return;
  }
  Object.entries(CHALLENGE_SOURCES).forEach(([gid,pool])=>{
    if(libraryGameFilter!=='all' && libraryGameFilter!==gid) return;
    const items=(pool||[]).filter(c=>(libraryCategoryFilter==='all'||libraryCategory(c)===libraryCategoryFilter)&&(!q||c.text.toLowerCase().includes(q)||libraryCategory(c).toLowerCase().includes(q)));
    if(!items.length) return; count+=items.length;
    html+=`<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">${gameIconHTML(gid,20)}</span><div class="setup-step-title">${GAME_NAME[gid]||gid}</div></div>`;
    items.forEach(c=>{ html+=renderItem(gid,c); }); html+='</div>';
  });
  out.innerHTML=html||'<div class="empty-hint">Keine passenden Challenges gefunden.</div>';
}

