let achievementsSelectedPlayer = null;
function renderAchievementsPage(){
  const names = Object.keys(statsStore);
  const contentEl = document.getElementById('achievements-content');
  if(!names.length){
    contentEl.innerHTML = '<div class="empty-hint">Noch keine Statistiken — spielt erst eine Runde.</div>';
    return;
  }
  if(currentUser) achievementsSelectedPlayer = currentUser.username;
  if(!achievementsSelectedPlayer || !names.includes(achievementsSelectedPlayer)) achievementsSelectedPlayer = names[0];
  const s = statsStore[achievementsSelectedPlayer];
  const claimed = new Set((s && s.achievementsClaimed) || []);
  const earnedCount = ACHIEVEMENTS_DEF.filter(a=>claimed.has(a.id)).length;
  let html = `<p class="setup-info" style="margin-top:0;">${earnedCount} / ${ACHIEVEMENTS_DEF.length} freigeschaltet</p>`;
  ACHIEVEMENTS_DEF.forEach(a=>{
    const done = claimed.has(a.id);
    html += `<div class="settings-row-btn" style="margin-top:8px;${done?'':'opacity:0.5;'}">
      <span class="settings-row-icon">${done?a.icon:'🔒'}</span>
      <span class="settings-row-text"><span class="settings-row-title">${a.label}</span><span class="settings-row-sub">${done?'Freigeschaltet':'Noch nicht erreicht'}</span></span>
      <span class="settings-row-chev">+${a.reward} Pkt</span>
    </div>`;
  });
  // Geheime Zusatz-Belohnung für 100% Achievements — kein eigenes ACHIEVEMENTS_DEF-Achievement
  // (sonst würde es sich selbst mitzählen), sondern ein separater Bonus-Eintrag am Ende der Liste,
  // damit er als Ziel sichtbar ist, ohne den Fortschrittsbalken/die Gesamtzahl zu verfälschen.
  const allDone = hasAllAchievements(s);
  html += `<div class="settings-row-btn" style="margin-top:8px;border:1px dashed var(--border-soft);${allDone?'':'opacity:0.5;'}">
    <span class="settings-row-icon">${allDone?'🩸':'🔒'}</span>
    <span class="settings-row-text"><span class="settings-row-title">${allDone?'Geheime Belohnung freigeschaltet':'??? Geheime Belohnung'}</span><span class="settings-row-sub">${allDone?'Blutmond-Emblem, Beobachter-Banner & eigener Spruch':'Alle '+ACHIEVEMENTS_DEF.length+' Achievements nötig'}</span></span>
  </div>`;
  contentEl.innerHTML = html;
}
const RANK_TIERS = [
  {min:20, label:'Ultimativer Winner', icon:'🌠'},
  {min:19, label:'Profi', icon:'🎖️'},
  {min:15, label:'Erfahrener', icon:'⭐'},
  {min:10, label:'Anfänger', icon:'🔰'},
  {min:5, label:'Neuling', icon:'🌱'},
];
function tierStatusFor(name){
  if(!userPrefs.showTierStatus) return null;
  const s = statsStore[name];
  if(!s) return null;
  const count = (s.achievementsClaimed||[]).length;
  return RANK_TIERS.find(t=>count>=t.min) || null;
}
function tierStatusLineHTML(name){
  const t = tierStatusFor(name);
  if(!t) return '';
  return `<div class="tier-status-line">${t.label}</div>`;
}
function checkAchievements(name){
  const s = statsStore[name];
  if(!s) return [];
  s.achievementsClaimed = s.achievementsClaimed || [];
  const newlyEarned = [];
  ACHIEVEMENTS_DEF.forEach(a=>{
    if(!s.achievementsClaimed.includes(a.id) && a.test(s)){
      s.achievementsClaimed.push(a.id);
      s.totalPoints = (s.totalPoints||0) + a.reward;
      addCoins(name, a.reward);
      newlyEarned.push(a);
    }
  });
  if(newlyEarned.length){
    grantAllAchievementsRewardIfNeeded(name, s);
    saveStats();
  }
  return newlyEarned;
}
// ===== Belohnung für 100% Achievements: Horror-Elite-Set =====
// Ersetzt das frühere käufliche "Kosmos-Paket": Beobachter-Banner, das rote Emblem (statt
// Spieler-/Helden-Bild) und der Spruch auf der Namenskarte werden automatisch vergeben UND
// ausgerüstet, sobald WIRKLICH ALLE Achievements freigeschaltet sind. Nicht käuflich.
function hasAllAchievements(s){
  return !!(s && (s.achievementsClaimed||[]).length >= ACHIEVEMENTS_DEF.length);
}
function grantAllAchievementsRewardIfNeeded(name, s){
  if(!hasAllAchievements(s) || s.allAchievementsRewardGranted) return;
  s.allAchievementsRewardGranted = true;
  s.shopOwned = s.shopOwned || {badges:[], banners:[], hats:[], glows:[], frames:[], sabotage:{}};
  if(!s.shopOwned.banners) s.shopOwned.banners = [];
  if(!s.shopOwned.banners.includes('watcher_eyes')) s.shopOwned.banners.push('watcher_eyes');
  s.equippedBanner = 'watcher_eyes';
  avatarMap[name] = EMBLEM_RED_GIF; saveAvatars();
  if(currentUser && currentUser.username===name){
    currentUser.avatar = EMBLEM_RED_GIF; profileAvatarChoice = EMBLEM_RED_GIF;
    if(sb) sb.from('profiles').update({avatar:EMBLEM_RED_GIF, equipped_banner:'watcher_eyes'}).eq('id', currentUser.id).catch(e=>console.error('Emblem-Sync Fehler:', e));
  }
  showAllAchievementsRewardModal();
}
// Eigenes Popup (statt simplem Alert-Text) für die 100%-Achievements-Belohnung: zeigt den
// freigeschalteten Banner als echte Hintergrund-Karte plus einen kurzen Hinweistext, dass das
// Set selten und NICHT käuflich ist.
function showAllAchievementsRewardModal(){
  const modal = document.getElementById('all-achievements-modal');
  if(!modal) return;
  const banner = SHOP_BANNERS.find(b=>b.id==='watcher_eyes');
  modal.innerHTML = `<div class="member-modal-card${bannerClassFor(banner)}" style="${banner ? bannerStyleFor(banner) : ''}" onclick="event.stopPropagation();">
    ${bannerImgTagHTML(banner)}
    <button class="member-modal-close" onclick="closeAllAchievementsRewardModal()" aria-label="Schließen">✕</button>
    <div class="member-modal-avatar" style="font-size:1rem;">🏆</div>
    <div class="member-modal-name">🩸 Horror-Elite-Set freigeschaltet</div>
    <p class="member-modal-bio" style="font-style:normal;margin-top:10px;line-height:1.4;">Alle Achievements geschafft — dafür gibt's das einzigartige Blutmond-Emblem, den Beobachter-Banner und einen eigenen Spruch auf deiner Namenskarte. Automatisch ausgerüstet.</p>
    <p style="margin-top:12px;font-size:0.76rem;font-weight:700;letter-spacing:0.03em;color:#ffd76a;">✨ Extrem selten · nicht käuflich · nur durch 100% Achievements</p>
  </div>`;
  modal.classList.remove('hidden');
}
function closeAllAchievementsRewardModal(){
  const modal = document.getElementById('all-achievements-modal');
  if(modal){ modal.classList.add('hidden'); modal.innerHTML = ''; }
}
function revokeAllAchievementsRewardIfNeeded(name, s){
  if(hasAllAchievements(s) || !s.allAchievementsRewardGranted) return;
  s.allAchievementsRewardGranted = false;
  if(s.equippedBanner==='watcher_eyes') s.equippedBanner = null;
  if(avatarMap[name]===EMBLEM_RED_GIF){ delete avatarMap[name]; saveAvatars(); }
  if(currentUser && currentUser.username===name && currentUser.avatar===EMBLEM_RED_GIF){
    currentUser.avatar = null; profileAvatarChoice = '😎';
    if(sb) sb.from('profiles').update({avatar:null, equipped_banner:null}).eq('id', currentUser.id).catch(e=>console.error('Emblem-Sync Fehler:', e));
  }
}
// Nach jeder Änderung der Achievement-Anzahl (v.a. beim Zurücksetzen) prüfen, ob noch ausgerüstete
// Belohnungen (Prestige-Abzeichen, Horror-Elite-Set) überhaupt noch freigeschaltet sein dürfen —
// sonst bleiben sie fälschlich sichtbar, obwohl "zurückgesetzt" wurde.
function enforceAchievementLocksAfterChange(name, s){
  if(!s) return;
  const count = (s.achievementsClaimed||[]).length;
  if(s.equippedBadge){
    const b = SHOP_BADGES.find(x=>x.id===s.equippedBadge);
    if(b && b.requiresAchievementCount && count < b.requiresAchievementCount) s.equippedBadge = null;
  }
  revokeAllAchievementsRewardIfNeeded(name, s);
}
function favoriteGame(s){
  let best=null, bestCount=0;
  Object.entries(s.gamesPlayed||{}).forEach(([g,c])=>{ if(c>bestCount){ best=g; bestCount=c; } });
  return best;
}
function successRate(s){
  const total = s.challengesWon + s.challengesLost;
  return total ? Math.round((s.challengesWon/total)*100) : 0;
}
// Baut die kompakte "Kurzversion" der Statistik (fürs Mitglieder-Profil, das jeder bei jedem sehen
// kann) — bewusst klein gehalten (nur Top-3-Listen statt der vollen challengeStats-Map), damit die
// profiles.stats-Spalte nicht unnötig groß wird.
function buildStatsSummary(s){
  const entries = Object.entries(s.challengeStats||{}).map(([text,c])=>({text, won:c.won||0, lost:c.lost||0, total:(c.won||0)+(c.lost||0)})).filter(e=>e.total>=2);
  const topDone = entries.filter(e=>e.won>0).sort((a,b)=> (b.won/b.total)-(a.won/a.total) || b.total-a.total).slice(0,3).map(e=>({text:e.text, won:e.won, total:e.total}));
  const topMissed = entries.filter(e=>e.lost>0).sort((a,b)=> (b.lost/b.total)-(a.lost/a.total) || b.total-a.total).slice(0,3).map(e=>({text:e.text, lost:e.lost, total:e.total}));
  return {
    totalPoints: s.totalPoints, roundsPlayed: s.roundsPlayed, roundWins: s.roundWins,
    challengesWon: s.challengesWon, challengesLost: s.challengesLost,
    bestRoundScore: s.bestRoundScore===-Infinity?0:s.bestRoundScore,
    bestRoundStreak: s.bestRoundStreak===-Infinity?0:(s.bestRoundStreak||0),
    favoriteGame: favoriteGame(s), topDone, topMissed, gamesPlayed: s.gamesPlayed || {},
  };
}
async function syncStatsToCloud(name){
  if(!currentUser || !sb || name !== currentUser.username) return;
  try{ await sb.from('profiles').update({ stats: buildStatsSummary(statsStore[name]) }).eq('id', currentUser.id); }
  catch(e){ console.error('Stats-Sync fehlgeschlagen:', e); }
}
/* ============================================================ VOLLSTÄNDIGER CLOUD-STATS-SYNC ============================================================
   Coins, Käufe (shopOwned), Erfolge etc. lagen bisher NUR im localStorage des jeweiligen Geräts
   (statsStore) — bei geräteübergreifender Nutzung (anderes Handy/Browser) waren Coins & Käufe
   dadurch scheinbar "weg". Jetzt wird der komplette statsStore-Eintrag des eigenen Accounts
   zusätzlich in der Cloud gespiegelt (profiles.full_stats, jsonb) und beim Login/Session-Start
   zurückgeholt + mit dem lokalen Stand zusammengeführt (jeweils der höhere/vollständigere Wert
   gewinnt, damit auf keinem Gerät versehentlich Fortschritt verloren geht).
   ERFORDERT Supabase-Spalte: alter table profiles add column if not exists full_stats jsonb; */
let fullStatsSyncTimer = null;
function scheduleFullStatsCloudSync(){
  if(!currentUser || !sb) return;
  clearTimeout(fullStatsSyncTimer);
  fullStatsSyncTimer = setTimeout(()=>{ syncFullStatsToCloud(currentUser.username); }, 900);
}
async function syncFullStatsToCloud(name){
  if(!currentUser || !sb || name !== currentUser.username) return;
  const s = statsStore[name];
  if(!s) return;
  try{
    const safe = JSON.parse(JSON.stringify(s, (k,v)=> v===-Infinity ? null : v));
    await sb.from('profiles').update({ full_stats: safe }).eq('id', currentUser.id);
  }catch(e){ console.error('Vollständiger Stats-Sync fehlgeschlagen (evtl. fehlt Spalte full_stats):', e); }
}
function mergeStatsForRestore(local, cloud){
  if(!cloud) return local || null;
  if(!local) return cloud;
  const merged = JSON.parse(JSON.stringify(local));
  ['totalPoints','spent','roundsPlayed','roundWins','challengesWon','challengesLost','currentRoundStreak','bestRoundStreak','shopBonus','pikachusFound','jackpotWins','minigamesWon'].forEach(k=>{
    merged[k] = Math.max(local[k]||0, cloud[k]||0);
  });
  // coins ist NICHT monoton (Ausgeben senkt es absichtlich) — Math.max wäre hier falsch, weil ein
  // Kauf auf diesem Gerät dann von einem älteren, höheren Cloud-Stand überschrieben würde. Der
  // lokale Stand gewinnt daher immer; die Cloud dient nur als Ausgangswert für ein neues Gerät,
  // das noch gar keinen eigenen lokalen coins-Wert hat.
  merged.coins = local.coins!=null ? local.coins : (cloud.coins!=null ? cloud.coins : undefined);
  const localBest = (typeof local.bestRoundScore==='number' && isFinite(local.bestRoundScore)) ? local.bestRoundScore : -Infinity;
  const cloudBest = (typeof cloud.bestRoundScore==='number' && isFinite(cloud.bestRoundScore)) ? cloud.bestRoundScore : -Infinity;
  merged.bestRoundScore = Math.max(localBest, cloudBest);
  merged.gamesPlayed = Object.assign({}, local.gamesPlayed||{});
  Object.entries(cloud.gamesPlayed||{}).forEach(([g,c])=>{ merged.gamesPlayed[g] = Math.max(merged.gamesPlayed[g]||0, c||0); });
  const lo = local.shopOwned || {badges:[],banners:[],hats:[],glows:[],frames:[],sabotage:{}};
  const co = cloud.shopOwned || {badges:[],banners:[],hats:[],glows:[],frames:[],sabotage:{}};
  const unionArr = (a,b)=> Array.from(new Set([...(a||[]), ...(b||[])]));
  merged.shopOwned = {
    badges: unionArr(lo.badges, co.badges), banners: unionArr(lo.banners, co.banners),
    hats: unionArr(lo.hats, co.hats), glows: unionArr(lo.glows, co.glows), frames: unionArr(lo.frames, co.frames),
    sabotage: Object.assign({}, lo.sabotage),
  };
  Object.entries(co.sabotage||{}).forEach(([id,c])=>{ merged.shopOwned.sabotage[id] = Math.max(merged.shopOwned.sabotage[id]||0, c||0); });
  merged.achievementsClaimed = Array.from(new Set([...(local.achievementsClaimed||[]), ...(cloud.achievementsClaimed||[])]));
  merged.challengeStats = Object.assign({}, local.challengeStats||{});
  Object.entries(cloud.challengeStats||{}).forEach(([text,c])=>{
    const ex = merged.challengeStats[text] || {won:0,lost:0};
    merged.challengeStats[text] = { won: Math.max(ex.won||0, c.won||0), lost: Math.max(ex.lost||0, c.lost||0) };
  });
  ['equippedBadge','equippedHat','equippedBanner','equippedGlow','equippedFrame'].forEach(k=>{
    if(merged[k]==null && cloud[k]!=null) merged[k] = cloud[k];
  });
  return merged;
}
async function restoreFullStatsFromCloud(){
    if (typeof statsStore === 'undefined') return;
  if(!currentUser || !sb) return;
  try{
    const { data } = await sb.from('profiles').select('full_stats').eq('id', currentUser.id).maybeSingle();
    const cloud = data && data.full_stats;
    const local = statsStore[currentUser.username] || null;
    const merged = mergeStatsForRestore(local, cloud);
    if(merged){
      const existing = statsStore[currentUser.username];
      if(existing){
        // Wichtig: in-place mutieren, NICHT das Objekt ersetzen. Sonst kann ein zeitgleich
        // laufender Kauf (der sich "s = statsStore[name]" schon vorher gemerkt hat) auf ein
        // inzwischen ausgetauschtes, totes Objekt schreiben — die Änderung ginge dann lautlos
        // verloren, obwohl lokal alles richtig aussah. Genau das führte zu "Guthaben wird beim
        // Kauf nicht abgezogen", weil dieser Abgleich seit Kurzem auch beim Öffnen des Shops läuft.
        Object.keys(existing).forEach(k=>{ if(!(k in merged)) delete existing[k]; });
        Object.assign(existing, merged);
      } else {
        statsStore[currentUser.username] = merged;
      }
      try{ localStorage.setItem(LS_STATS, JSON.stringify(statsStore)); }catch(e){}
      scheduleFullStatsCloudSync(); // gleicht bei Bedarf beide Seiten wieder an (z.B. nach einem Merge)
    }
  }catch(e){ console.error('Stats-Wiederherstellung aus der Cloud fehlgeschlagen (evtl. fehlt Spalte full_stats):', e); }
}
// Merkt sich pro Challenge-Text, wie oft sie geschafft bzw. nicht geschafft wurde — Basis für die
// "welche Challenges schafft man eher/seltener"-Übersicht auf der Statistik-Seite.
function recordChallengeOutcome(s, text, won){
  if(!text) return;
  s.challengeStats = s.challengeStats || {};
  const entry = s.challengeStats[text] || { won:0, lost:0 };
  if(won) entry.won++; else entry.lost++;
  s.challengeStats[text] = entry;
}
function recordRoundStats(){
  if(session.mode==='team'){
    const roundScore = scoreOf(session.sharedRules);
    const wins = session.sharedRules.filter(c=>c.state==='win').length;
    const losses = session.sharedRules.filter(c=>c.state==='lose').length;
    const won = roundScore > 0;
    session.players.forEach(p=>{
      const s = getPlayerStats(p);
      s.totalPoints += roundScore; s.challengesWon += wins; s.challengesLost += losses; s.roundsPlayed += 1;
      addCoins(p, roundScore);
      session.sharedRules.forEach(c=>{ if(c.state==='win'||c.state==='lose') recordChallengeOutcome(s, c.text, c.state==='win'); });
      s.gamesPlayed[session.gameId] = (s.gamesPlayed[session.gameId]||0)+1;
      const heroT = session.heroAssignment ? session.heroAssignment[p] : null;
      if(heroT){ s.heroesPlayed = s.heroesPlayed || {}; s.heroesPlayed[session.gameId+':'+heroT[0]] = true; }
      if(roundScore > s.bestRoundScore) s.bestRoundScore = roundScore;
      if(won){ s.roundWins += 1; s.currentRoundStreak += 1; if(s.currentRoundStreak > s.bestRoundStreak) s.bestRoundStreak = s.currentRoundStreak; }
      else { s.currentRoundStreak = 0; }
    });
  } else {
    const sharedScore = scoreOf(session.sharedRules);
    const ranked = session.players.map(p=>({ p, score: scoreOf(session.personalChallenges[p]) + sharedScore })).sort((a,b)=>b.score-a.score);
    const topScore = ranked.length ? ranked[0].score : null;
    session.players.forEach(p=>{
      const personal = session.personalChallenges[p];
      const roundScore = scoreOf(personal) + sharedScore;
      const wins = personal.filter(c=>c.state==='win').length;
      const losses = personal.filter(c=>c.state==='lose').length;
      const s = getPlayerStats(p);
      s.totalPoints += roundScore; s.challengesWon += wins; s.challengesLost += losses; s.roundsPlayed += 1;
      addCoins(p, roundScore);
      personal.forEach(c=>{ if(c.state==='win'||c.state==='lose') recordChallengeOutcome(s, c.text, c.state==='win'); });
      session.sharedRules.forEach(c=>{ if(c.state==='win'||c.state==='lose') recordChallengeOutcome(s, c.text, c.state==='win'); });
      s.gamesPlayed[session.gameId] = (s.gamesPlayed[session.gameId]||0)+1;
      const heroV = session.heroAssignment ? session.heroAssignment[p] : null;
      if(heroV){ s.heroesPlayed = s.heroesPlayed || {}; s.heroesPlayed[session.gameId+':'+heroV[0]] = true; }
      if(roundScore > s.bestRoundScore) s.bestRoundScore = roundScore;
      const won = roundScore === topScore;
      if(won){ s.roundWins += 1; s.currentRoundStreak += 1; if(s.currentRoundStreak > s.bestRoundStreak) s.bestRoundStreak = s.currentRoundStreak; }
      else { s.currentRoundStreak = 0; }
    });
  }
  recordGameHistoryEntry({
    date: new Date().toISOString(),
    gameId: session.gameId,
    mode: session.mode,
    difficulty: session.difficultyKey || null,
    players: session.players.slice(),
    challenges: [
      ...session.sharedRules.map(c=>({ text:c.text, diff:c.diff, scope:'shared', player:null, result: c.state==='win'?'win':c.state==='lose'?'lose':null })),
      ...(session.mode==='team' ? [] : session.players.flatMap(p=>(session.personalChallenges[p]||[]).map(c=>({ text:c.text, diff:c.diff, scope:'personal', player:p, result: c.state==='win'?'win':c.state==='lose'?'lose':null })))),
    ],
  });
  saveStats();
  session.players.forEach(p=>notifyNewAchievements(checkAchievements(p)));
  session.players.forEach(p=>syncStatsToCloud(p));
}
function notifyNewAchievements(newlyEarned){
  if(!newlyEarned || !newlyEarned.length) return;
  const totalReward = newlyEarned.reduce((s,a)=>s+a.reward,0);
  const lines = newlyEarned.map(a=>`${a.icon} ${a.label} (+${a.reward} Pkt)`).join('\n');
  showAlert(`🏅 Neues Achievement freigeschaltet!\n${lines}`, '🏅');
}
function showStatsPage(){ showView('stats'); renderStatsPage(); }
async function clearMyCloudCosmetics(){
  // Der Reset hat bisher nur den lokalen statsStore geleert. Das Aussehen (Banner, Abzeichen,
  // Mütze, Leuchtname) wird aber zusätzlich im Supabase-Profil gespiegelt (equipped_*), damit
  // andere Team-Mitglieder es sehen können — und wurde dort NICHT mit zurückgesetzt. cosmeticsFor()
  // bevorzugt diesen Cloud-Wert (remoteCosmeticsCache), weshalb Banner & Co. trotz "Reset" noch
  // angezeigt wurden. Deshalb hier zusätzlich die Cloud-Seite leeren.
  if(!currentUser) return;
  delete remoteCosmeticsCache[currentUser.username];
  if(!sb) return;
  try{
    await sb.from('profiles').update({ equipped_badge:null, equipped_hat:null, equipped_banner:null, equipped_glow:null, equipped_frame:null }).eq('id', currentUser.id);
    Object.assign(currentUser, { equipped_badge:null, equipped_hat:null, equipped_banner:null, equipped_glow:null, equipped_frame:null });
  }catch(e){ console.error('Cloud-Kosmetik konnte nicht zurückgesetzt werden:', e); }
}
async function resetStatsOnly(){
  if(!(await confirmAction('Statistiken (Punkte, Siege, Erfolge) wirklich zurücksetzen? Das kann nicht rückgängig gemacht werden.'))) return;
  // Horror-Elite-Set (rotes Emblem) hängt an Achievements — beim kompletten Stats-Wipe muss ein
  // lokal gesetztes Emblem-Avatar mit verschwinden, sonst bleibt das Bild trotz Reset stehen.
  Object.keys(statsStore).forEach(n=>{ if(avatarMap[n]===EMBLEM_RED_GIF) delete avatarMap[n]; });
  saveAvatars();
  statsStore = {}; saveStats(); gameHistory = []; saveGameHistory(); renderStatsPage();
  await clearMyCloudCosmetics();
  if(currentUser && sb){ try{ await sb.from('profiles').update({ full_stats: null }).eq('id', currentUser.id); }catch(e){ console.error('Cloud-Stats-Reset fehlgeschlagen:', e); } }
  if(currentUser && sb && currentUser.avatar===EMBLEM_RED_GIF){
    try{
      await sb.from('profiles').update({ avatar:null }).eq('id', currentUser.id);
      currentUser.avatar = null; profileAvatarChoice = '😎';
    }catch(e){ console.error('Avatar-Reset Fehler:', e); }
  }
}
async function resetAllLocalData(){
  if(!(await confirmAction('WIRKLICH ALLES zurücksetzen? Statistiken, lokale Mitspieler und Avatare auf diesem Gerät gehen verloren. Euer Online-Account/Team bleibt bestehen.'))) return;
  statsStore = {}; saveStats();
  gameHistory = []; saveGameHistory();
  globalPlayers = []; savePlayers();
  avatarMap = {}; saveAvatars();
  session = null; saveSession();
  await clearMyCloudCosmetics();
  if(currentUser && sb){ try{ await sb.from('profiles').update({ full_stats: null }).eq('id', currentUser.id); }catch(e){ console.error('Cloud-Stats-Reset fehlgeschlagen:', e); } }
  renderGlobalPlayerChips(); renderStatsPage(); updateContinueButton();
  showAlert('Erledigt — lokale Daten wurden zurückgesetzt.');
}
// Kurzer Überblick über die letzten gespielten Runden: welches Spiel, welcher Modus, wer hat
// mitgespielt und welche Challenges kamen mit welchem Ergebnis dran.
function renderGameHistoryHTML(){
  if(!gameHistory || !gameHistory.length) return '';
  const recent = gameHistory.slice(0, 12);
  const entryHTML = h=>{
    const dateStr = new Date(h.date).toLocaleString('de-DE', {day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit'});
    const modeLabel = h.mode==='team' ? '🤝 Team' : '⚔️ Jeder gegen Jeden';
    const challengeRows = (h.challenges||[]).map(c=>{
      const icon = c.result==='win' ? '✅' : c.result==='lose' ? '❌' : '➖';
      const who = c.player ? ` (${c.player})` : '';
      return `<div class="settings-row-sub" style="margin-top:2px;">${icon} ${c.text.slice(0,50)}${c.text.length>50?'…':''}${who}</div>`;
    }).join('');
    return `<details class="hero-avatar-group" style="margin-top:8px;">
      <summary style="font-size:0.85rem;padding:8px 12px;">${gameIconHTML(h.gameId,16)} ${GAME_NAME[h.gameId]||h.gameId} · ${modeLabel} · ${dateStr}</summary>
      <div style="padding:2px 12px 10px;">
        <div class="setup-info" style="margin:4px 0;">Spieler: ${(h.players||[]).join(', ')}${h.difficulty?` · Schwierigkeit: ${h.difficulty}`:''}</div>
        ${challengeRows}
      </div>
    </details>`;
  };
  return `<div class="settings-card" style="margin-bottom:16px;">
    <div class="setup-step-head"><span class="setup-step-icon">📜</span><div class="setup-step-title">Spielverlauf</div></div>
    <p class="setup-info" style="margin-top:0;">Die letzten Runden — Spiel, Modus, Mitspieler und wie die Challenges ausgegangen sind.</p>
    ${recent.map(entryHTML).join('')}
  </div>`;
}
function renderStatsPage(){
  const el = document.getElementById('stats-content');
  const names = Object.keys(statsStore);
  if(!names.length){ el.innerHTML = '<div class="empty-hint">Noch keine gespielten Runden. Startet eine Session, um Statistiken zu sammeln.</div>'; return; }
  const ranked = names.map(n=>({name:n, s:statsStore[n]})).sort((a,b)=>b.s.totalPoints-a.s.totalPoints);
  let html = renderGameHistoryHTML();
  ranked.forEach(({name, s}, i)=>{
    const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1)+'.';
    const fav = favoriteGame(s);
    const badges = ACHIEVEMENTS_DEF.filter(a=>a.test(s));
    const banner = SHOP_BANNERS.find(b=>b.id===s.equippedBanner) || SHOP_BANNERS.find(b=>b.id==='basic_slate');
    const shopBadge = SHOP_BADGES.find(b=>b.id===s.equippedBadge);
    const statFrame = SHOP_FRAMES.find(f=>f.id===s.equippedFrame);
    html += `<div class="stat-card${bannerClassFor(banner)}" style="${banner ? bannerStyleFor(banner) : ''}${(banner && !banner.basic) ? '' : frameStyleFor(statFrame)}">
      ${bannerImgTagHTML(banner)}
      ${bannerBadgeStampHTML(banner, shopBadge)}
      <div class="stat-card-head"><span class="lb-rank">${medal}</span><span class="stat-avatar">${withHatOverlay(name, avatarHTML(name,26), 26)}</span><div class="stat-name">${badgeIconHTML(shopBadge)}${glowNameHTML(name,name)}${shopBadge ? '' : tierStatusLineHTML(name)}</div><div class="stat-points">${s.totalPoints} Pkt</div></div>
      ${uniqueQuoteHTML(s)}
      <div class="stat-grid">
        <div class="stat-mini"><div class="stat-mini-val">${s.roundsPlayed}</div><div class="stat-mini-label">Runden</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${s.roundWins}</div><div class="stat-mini-label">Siege</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${s.challengesWon}</div><div class="stat-mini-label">Challenges ✅</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${successRate(s)}%</div><div class="stat-mini-label">Erfolgsquote</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${s.bestRoundScore===-Infinity?0:s.bestRoundScore}</div><div class="stat-mini-label">Rekord/Runde</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${fav?gameIconHTML(fav,20):'—'}</div><div class="stat-mini-label">Lieblingsspiel</div></div>
        <div class="stat-mini"><div class="stat-mini-val">${s.totalPoints}</div><div class="stat-mini-label">Coins insgesamt</div></div>
      </div>
      ${badges.length ? `<div class="stat-badges">${badges.map(b=>`<span class="stat-badge">${b.icon} ${b.label}</span>`).join('')}</div>` : ''}
      ${renderChallengeStatsHTML(s)}
    </div>`;
  });
  el.innerHTML = html;
}
// Zeigt pro Spieler(-in), welche konkreten Challenges am häufigsten geschafft bzw. am häufigsten
// nicht geschafft werden — nur Einträge mit mindestens 2 Versuchen, damit ein einzelner Ausreißer
// nicht gleich als Muster erscheint.
function renderChallengeStatsHTML(s){
  const entries = Object.entries(s.challengeStats||{}).map(([text,c])=>({text, won:c.won||0, lost:c.lost||0, total:(c.won||0)+(c.lost||0)})).filter(e=>e.total>=2);
  if(!entries.length) return '';
  const bestDone = entries.filter(e=>e.won>0).sort((a,b)=> (b.won/b.total)-(a.won/a.total) || b.total-a.total).slice(0,3);
  const oftenMissed = entries.filter(e=>e.lost>0).sort((a,b)=> (b.lost/b.total)-(a.lost/a.total) || b.total-a.total).slice(0,3);
  if(!bestDone.length && !oftenMissed.length) return '';
  const rowHTML = e => `<div class="settings-row-sub" style="margin-top:2px;">${e.text.slice(0,60)}${e.text.length>60?'…':''} — ${e.won}/${e.total}x geschafft</div>`;
  return `<details class="hero-avatar-group" style="margin-top:10px;">
    <summary style="font-size:0.85rem;padding:8px 12px;">📊 Welche Challenges klappen eher/seltener?</summary>
    <div style="padding:2px 12px 10px;">
      ${bestDone.length ? `<div class="setup-info" style="margin:6px 0 2px;"><strong>✅ Klappen meistens:</strong></div>${bestDone.map(rowHTML).join('')}` : ''}
      ${oftenMissed.length ? `<div class="setup-info" style="margin:8px 0 2px;"><strong>❌ Scheitern oft:</strong></div>${oftenMissed.map(rowHTML).join('')}` : ''}
    </div>
  </details>`;
}

