function frameStyleFor(frame){
  if(!frame) return '';
  // Bewusst dezent wie ein dünner LED-Streifen: 1px Ring, bei Verläufen nur ein hauchzarter
  // zweiter Farbschimmer außen — kein dicker Leucht-Doppelring.
  if(frame.grad) return `box-shadow:0 0 0 1px ${frame.c1}, 0 0 4px 0.5px ${frame.c2};`;
  return `box-shadow:0 0 0 1px ${frame.c1};`;
}
