shopSelectedPlayer = null;
// Einheitliches Shop-Guthaben: EIN Feld (s.coins), das direkt bei jeder Aktion addiert/subtrahiert
// wird — kein Herleiten mehr aus mehreren Feldern (totalPoints/spent/shopBonus), das war zu
// fehleranfällig. ensureCoins() migriert einmalig den alten Stand in "coins", danach ist coins
// die einzige Quelle der Wahrheit für den Shop.
function ensureCoins(s){
  if(!s) return 0;
  if(s.coins==null){
    s.coins = Math.max(0, (s.totalPoints||0) + (s.shopBonus||0) - (s.spent||0));
  }
  return s.coins;
}
function addCoins(name, amount){
  const s = statsStore[name];
  if(!s) return 0;
  ensureCoins(s);
  s.coins = Math.max(0, (s.coins||0) + amount);
  return s.coins;
}
function shopBalance(name){
  const s = statsStore[name];
  if(!s) return 0;
  return ensureCoins(s);
}
