function renderShopPage(){
  const pickerRow = document.getElementById('shop-player-picker');
  if(currentUser){
    // Eingeloggt: der Shop gehört immer dem eigenen Account — kein Umschalten auf andere Spieler.
    shopSelectedPlayer = currentUser.username;
    if(!statsStore[shopSelectedPlayer]){
      statsStore[shopSelectedPlayer] = { totalPoints:0, roundsPlayed:0, roundWins:0, challengesWon:0, challengesLost:0, bestRoundScore:-Infinity, currentRoundStreak:0, bestRoundStreak:0, gamesPlayed:{} };
      saveStats();
    }
    pickerRow.innerHTML = '';
  } else {
    const names = Object.keys(statsStore);
    if(!names.length){
      pickerRow.innerHTML = '';
      document.getElementById('shop-balance').textContent = '';
      document.getElementById('shop-content').innerHTML = '<div class="empty-hint">Noch keine Statistiken — spielt erst eine Runde, um Punkte zu sammeln.</div>';
      return;
    }
    if(!shopSelectedPlayer || !names.includes(shopSelectedPlayer)) shopSelectedPlayer = names[0];
    pickerRow.innerHTML = '';
    names.forEach(n=>{
      const btn = document.createElement('button');
      btn.className = 'filter-pill'+(n===shopSelectedPlayer?' active':'');
      btn.innerHTML = avatarHTML(n,16)+' '+n;
      btn.addEventListener('click', ()=>{ shopSelectedPlayer = n; renderShopPage(); });
      pickerRow.appendChild(btn);
    });
  }
  document.getElementById('shop-balance').innerHTML = `Guthaben: ${shopBalance(shopSelectedPlayer)} ${currencyMarkHTML()}`;
  const s = statsStore[shopSelectedPlayer];
  const owned = (s && s.shopOwned) || {badges:[], banners:[], hats:[], sabotage:{}};
  const previewBadge = SHOP_BADGES.find(b=>b.id===s.equippedBadge);
  const previewBanner = SHOP_BANNERS.find(b=>b.id===s.equippedBanner) || SHOP_BANNERS.find(b=>b.id==='basic_slate');
  const previewFrame = SHOP_FRAMES.find(f=>f.id===s.equippedFrame);
  let html = `<div class="stat-card shop-profile-preview${bannerClassFor(previewBanner)}" role="button" tabindex="0" title="Große Profilkarte öffnen" onclick="showMemberProfile(currentUser.id)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();showMemberProfile(currentUser.id);}" style="${previewBanner ? bannerStyleFor(previewBanner) : ''}${(previewBanner && !previewBanner.basic) ? '' : frameStyleFor(previewFrame)}">
    ${bannerImgTagHTML(previewBanner)}
    ${(currentUser && shopSelectedPlayer===currentUser.username) ? adminBadgeOverlayHTML() : ''}
    ${bannerBadgeStampHTML(previewBanner, previewBadge)}
    <div class="stat-card-head"><span class="stat-avatar">${withHatOverlay(shopSelectedPlayer, avatarHTML(shopSelectedPlayer,26), 26)}</span><div class="stat-name">${badgeIconHTML(previewBadge)}${glowNameHTML(shopSelectedPlayer,shopSelectedPlayer)}</div></div>
    ${uniqueQuoteHTML(s)}
  </div>`;
  html += '<div class="shop-catalog"><div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">🎖️</span><div class="setup-step-title">Abzeichen (neben dem Namen)</div></div><div class="avatar-grid" style="grid-template-columns:repeat(3,1fr);">';
  SHOP_BADGES.slice().sort((a,b)=>a.cost-b.cost).forEach(b=>{
    const isOwned = owned.badges.includes(b.id);
    if(b.cosmicExclusive && !isOwned) return; // nur übers Kosmos-Paket — vorher unsichtbar
    const isEquipped = s && s.equippedBadge===b.id;
    const myAchievementCount = s ? (s.achievementsClaimed||[]).length : 0;
    const locked = b.requiresAchievementCount && myAchievementCount < b.requiresAchievementCount;
    html += `<div class="avatar-grid-item${isEquipped?' selected':''}${isOwned?' owned':''}" style="font-size:1.4rem;flex-direction:column;gap:2px;${locked?'opacity:0.4;':''}" ${locked?'':`onclick="${isOwned?`equipShopItem('badge','${b.id}')`:`buyShopItem('badge','${b.id}')`}"`}>
      <span>${locked?'🔒':b.animated?`<span class="badge-lightning-flash">${b.icon}</span>`:b.icon}</span><span style="font-size:0.5rem;color:var(--text-muted);">${locked?`${b.requiresAchievementCount} Achievements nötig`:isOwned?(isEquipped?'aktiv':'ausrüsten'):(b.cost>0?`${b.cost} ${currencyMarkHTML()}`:'freischalten')}</span>
    </div>`;
  });
  html += '</div></div>';
  html += '<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">🧢</span><div class="setup-step-title">Mützen (Avatar-Aufsatz)</div></div><div class="avatar-grid" style="grid-template-columns:repeat(3,1fr);">';
  SHOP_HATS.slice().sort((a,b)=>a.cost-b.cost).forEach(b=>{
    const isOwned = owned.hats && owned.hats.includes(b.id);
    if(b.cosmicExclusive && !isOwned) return;
    const isEquipped = s && s.equippedHat===b.id;
    html += `<div class="avatar-grid-item${isEquipped?' selected':''}${isOwned?' owned':''}" style="font-size:1.4rem;flex-direction:column;gap:2px;" onclick="${isOwned?`equipShopItem('hat','${b.id}')`:`buyShopItem('hat','${b.id}')`}">
      <span>${b.icon}</span><span style="font-size:0.55rem;color:var(--text-muted);">${isOwned?(isEquipped?'aktiv':'ausrüsten'):`${b.cost} ${currencyMarkHTML()}`}</span>
    </div>`;
  });
  html += '</div></div>';
  html += '<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">🎨</span><div class="setup-step-title">Banner</div></div><p class="setup-info" style="margin-top:0;">Breite Hintergründe für deine Profil- und Namenskarte.</p><div class="filter-row">';
  SHOP_BANNERS.slice().sort((a,b)=>a.cost-b.cost).forEach(b=>{
    const pikaComplete = !!b.requiresPikachu && (s.pikachusFound||0) >= 50;
    const isOwned = owned.banners.includes(b.id) || pikaComplete;
    const isEquipped = s && s.equippedBanner===b.id;
    const locked = (b.requiresAllAchievements && !hasAllAchievements(s)) || (b.requiresPikachu && !pikaComplete);
    if(locked){
      const requirement = b.requiresPikachu ? '50 Pikachus finden' : `alle ${ACHIEVEMENTS_DEF.length} Achievements nötig`;
      html += `<button class="filter-pill" style="background:radial-gradient(circle at 30% 30%, #2a2a38, #0d0d14);border:2px dashed var(--border-soft);color:var(--text-muted);opacity:0.6;" disabled><span style="position:relative;z-index:2;">🔒 ${b.label} · ${requirement}</span></button>`;
      return;
    }
    const btnStyle = `${bannerStyleFor(b)}border:none;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,0.5);`;
    html += `<button class="filter-pill${isEquipped?' active':''}${isOwned?' owned':''}${bannerClassFor(b)}" style="${btnStyle}" onclick="${b.cost>0?(isOwned?`equipShopItem('banner','${b.id}')`:`buyShopItem('banner','${b.id}')`):(isEquipped?'':`equipShopItem('banner','${b.id}')`)}">${bannerImgTagHTML(b)}<span style="position:relative;z-index:2;text-shadow:0 1px 3px rgba(0,0,0,0.85), 0 0 8px rgba(0,0,0,0.6);">${b.label} ${b.cost>0?(isOwned?(isEquipped?'✓ aktiv':'✓ im Besitz'):`· ${b.cost} ${currencyMarkHTML()}`):(isEquipped?'✓ aktiv':(b.basic?'Kostenlos':'🏆 freigeschaltet'))}</span></button>`;
  });
  html += '</div></div>';
  html += '<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">✨</span><div class="setup-step-title">Leuchtende Namen</div></div><div class="filter-row">';
  SHOP_GLOWS.slice().sort((a,b)=>a.cost-b.cost).forEach(g=>{
    const isOwned = owned.glows && owned.glows.includes(g.id);
    if(g.cosmicExclusive && !isOwned) return;
    const isEquipped = s && s.equippedGlow===g.id;
    const btnClass = g.rainbow ? 'glow-name-rainbow' : 'glow-name-text';
    const btnStyle = g.rainbow ? 'border-color:#b388ff;' : `color:${g.color};text-shadow:0 0 6px ${g.color},0 0 14px ${g.color};border-color:${g.color};`;
    html += `<button class="filter-pill ${btnClass}${isEquipped?' active':''}${isOwned?' owned':''}" style="${btnStyle}" onclick="${isOwned?`equipShopItem('glow','${g.id}')`:`buyShopItem('glow','${g.id}')`}">${g.icon} ${g.label} ${isOwned?(isEquipped?'✓ aktiv':'✓ im Besitz'):`· ${g.cost} ${currencyMarkHTML()}`}</button>`;
  });
  html += '</div></div>';
  html += '<div class="settings-card"><div class="setup-step-head"><span class="setup-step-icon">🖼️</span><div class="setup-step-title">Rahmen</div></div><div class="filter-row">';
  SHOP_FRAMES.slice().sort((a,b)=>a.cost-b.cost).forEach(f=>{
    const isOwned = owned.frames && owned.frames.includes(f.id);
    if(f.cosmicExclusive && !isOwned) return;
    const isEquipped = s && s.equippedFrame===f.id;
    html += `<button class="filter-pill${isEquipped?' active':''}${isOwned?' owned':''}" style="${frameStyleFor(f)}" onclick="${isOwned?`equipShopItem('frame','${f.id}')`:`buyShopItem('frame','${f.id}')`}">${f.label} ${isOwned?(isEquipped?'✓ aktiv':'✓ im Besitz'):`· ${f.cost} ${currencyMarkHTML()}`}</button>`;
  });
  html += '</div></div></div>';
  html += '<div class="settings-card" id="shop-sabotage-card"><div class="setup-step-head"><span class="setup-step-icon">🎯</span><div class="setup-step-title">Sabotage &amp; Vorteile</div></div><p class="setup-info" style="margin-top:0;">Einmalig einsetzbar (verbraucht sich), bis zu 10 Stück pro Item auf Lager. Einsetzbar nur online, während der Helden-Auslosung.</p>';
  html += '<div class="shop-sabotage-list">';
  SHOP_SABOTAGE.slice().sort((a,b)=>a.cost-b.cost).forEach(b=>{
    const ownedCount = (owned.sabotage && owned.sabotage[b.id]) || 0;
    html += `<div class="settings-row-btn" style="cursor:pointer;margin-top:8px;" onclick="buySabotageItem('${b.id}')">
      <span class="settings-row-icon">${b.icon}</span>
      <span class="settings-row-text"><span class="settings-row-title">${b.label} ${ownedCount?`<span style="color:var(--turquoise);">(${ownedCount}x im Besitz)</span>`:''}</span><span class="settings-row-sub">${b.desc}</span></span>
      <span class="settings-row-chev">${b.cost} ${currencyMarkHTML()}</span>
    </div>`;
  });
  html += '</div></div>';
  document.getElementById('shop-content').innerHTML = html;
}
async function buyShopItem(kind, id){
  const name = shopSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const catalog = kind==='badge' ? SHOP_BADGES : kind==='hat' ? SHOP_HATS : kind==='glow' ? SHOP_GLOWS : kind==='frame' ? SHOP_FRAMES : SHOP_BANNERS;
  const item = catalog.find(i=>i.id===id);
  if(!item) return;
  if(shopBalance(name) < item.cost){ showAlert('Nicht genug Punkte dafür.', '💸'); return; }
  if(!(await confirmAction(`"${item.label||'Diesen Artikel'}" für ${item.cost} Punkte kaufen?`))) return;
  try{
    const s = statsStore[name];
    const balanceBefore = shopBalance(name);
    addCoins(name, -item.cost);
    s.shopOwned = s.shopOwned || {badges:[], banners:[], hats:[], glows:[], frames:[], sabotage:{}};
    if(!s.shopOwned.hats) s.shopOwned.hats = [];
    if(!s.shopOwned.glows) s.shopOwned.glows = [];
    if(!s.shopOwned.frames) s.shopOwned.frames = [];
    if(!s.shopOwned.sabotage) s.shopOwned.sabotage = {};
    const listKey = kind==='badge'?'badges':kind==='hat'?'hats':kind==='glow'?'glows':kind==='frame'?'frames':'banners';
    s.shopOwned[listKey].push(id);
    if(kind==='badge') s.equippedBadge = id;
    else if(kind==='hat') s.equippedHat = id;
    else if(kind==='glow') s.equippedGlow = id;
    else if(kind==='frame') s.equippedFrame = id;
    else s.equippedBanner = id;
    saveStats();
    { const balEl=document.getElementById('shop-balance'); if(balEl) balEl.innerHTML = `Guthaben: ${shopBalance(name)} ${currencyMarkHTML()}`; }
    // Kauf sofort in die Cloud schreiben, damit ein paralleles Geräte-Update den gerade
    // abgezogenen Shop-Stand nicht mit einem alten full_stats-Stand überschreibt.
    await syncFullStatsToCloud(name);
    await syncMyCosmeticsToProfile();
    console.log(`[Shop] ${name}: Guthaben ${balanceBefore} → ${shopBalance(name)} (−${item.cost} für "${item.label}")`);
  }catch(e){
    console.error('Kauf fehlgeschlagen:', e);
    showAlert('Beim Kauf ist ein unerwarteter Fehler aufgetreten: '+(e?.message||e));
  }finally{
    renderShopPage();
  }
}
async function buySabotageItem(id){
  const name = shopSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const item = SHOP_SABOTAGE.find(i=>i.id===id);
  if(!item) return;
  const s = statsStore[name];
  s.shopOwned = s.shopOwned || {badges:[], banners:[], hats:[], sabotage:{}};
  if(!s.shopOwned.sabotage) s.shopOwned.sabotage = {};
  const owned = s.shopOwned.sabotage[id] || 0;
  const cap = item.maxOwned || 10;
  if(owned >= cap){ showAlert(`Maximal ${cap} Stück von diesem Item auf Lager.`, '📦'); return; }
  if(shopBalance(name) < item.cost){ showAlert('Nicht genug Punkte dafür.', '💸'); return; }
  if(!(await confirmAction(`"${item.label||'Diesen Artikel'}" für ${item.cost} Punkte kaufen?`))) return;
  try{
    const balanceBefore = shopBalance(name);
    addCoins(name, -item.cost);
    s.shopOwned.sabotage[id] = owned + 1;
    saveStats();
    const balanceAfter = shopBalance(name);
    { const balEl=document.getElementById('shop-balance'); if(balEl) balEl.innerHTML = `Guthaben: ${balanceAfter} ${currencyMarkHTML()}`; }
    await syncFullStatsToCloud(name);
  }catch(e){
    console.error('Kauf fehlgeschlagen:', e);
    showAlert('Beim Kauf ist ein unerwarteter Fehler aufgetreten: '+(e?.message||e));
  }finally{
    renderShopPage();
  }
}
function equipShopItem(kind, id){
  const name = shopSelectedPlayer;
  if(!name || !statsStore[name]) return;
  const s = statsStore[name];
  const key = kind==='badge' ? 'equippedBadge' : kind==='hat' ? 'equippedHat' : kind==='glow' ? 'equippedGlow' : kind==='frame' ? 'equippedFrame' : 'equippedBanner';
  s[key] = (s[key] === id) ? null : id; // nochmal draufklicken zieht es wieder aus
  saveStats();
  syncMyCosmeticsToProfile();
  renderShopPage();
}
// Wie syncMyCosmeticsToProfile, aber für einen konkreten Namen (z.B. aus dem Admin/Achievements-
// Tab) statt sich auf shopSelectedPlayer zu verlassen. Das schließt die Lücke, durch die ein
// Achievements-Reset zwar lokal wirkte, aber die im Supabase-Profil gespiegelten equipped_*-Werte
// (und damit die Anzeige bei Teammitgliedern über remoteCosmeticsCache) stehen ließ.
async function syncCosmeticsForNameToProfile(name){
  if(!currentUser || !sb || currentUser.username !== name) return;
  const s = statsStore[name];
  if(!s) return;
  const payload = {
    equipped_badge: s.equippedBadge || null,
    equipped_hat: s.equippedHat || null,
    equipped_banner: s.equippedBanner || null,
    equipped_glow: s.equippedGlow || null,
    equipped_frame: s.equippedFrame || null,
  };
  try{
    await sb.from('profiles').update(payload).eq('id', currentUser.id);
    Object.assign(currentUser, payload);
    remoteCosmeticsCache[name] = { badge: payload.equipped_badge, hat: payload.equipped_hat, banner: payload.equipped_banner, glow: payload.equipped_glow, frame: payload.equipped_frame };
  }catch(e){ console.error('Kosmetik-Sync Fehler:', e); }
}
async function syncMyCosmeticsToProfile(){
  if(!currentUser) return;
  if(shopSelectedPlayer !== currentUser.username) return; // nur den eigenen Account synchronisieren, nie fremde lokale Namen
  await syncCosmeticsForNameToProfile(currentUser.username);
}

/* ============================================================ SESSION SETUP WIZARD ============================================================ */
let setupState = { scope:'rounds', gameId:null, gameMode:null, gamesCount:5, selectedGames:[], gameModeChoices:{}, randomOrder:true, roundsPerGame:1, funChallenges:true, mode:'team', sessionMode:'challenge', difficulty:'Mittel', playerRoles:{}, heroLockMode:'reroll', pointGoalChoice:'none', customGoalValue:300, rounds:3, count:4, selectedPlayers:[] };
let stepIndex = 0;
let continueFromSession = false;
const ALL_STEPS = ['scope','game','gameMode','gamesMulti','mode','sessionMode','difficulty','heroLock','pointGoal','rounds','count','players','role'];
function sessionHasHeroGames(){
  if(setupState.scope === 'rounds' || setupState.scope === 'match') return !!HERO_GAMES[setupState.gameId];
  return setupState.selectedGames.some(id=>HERO_GAMES[id]);
}
function sessionRoleOptions(){
  // Rollen-Filter nur sinnvoll bei genau einem rollenbasierten Spiel (nicht bei "nach Spielen"
  // mit mehreren unterschiedlichen Titeln gleichzeitig, da die Rollen dort nicht übereinstimmen).
  if(setupState.scope !== 'rounds' && setupState.scope !== 'match') return null;
  return rolesForGame(setupState.gameId);
}
function visibleSteps(){
  const noRounds = (setupState.scope==='rounds' || setupState.scope==='match') && isNoRoundsMode(setupState.gameId, setupState.gameMode);
  return ALL_STEPS.filter(s=>{
    if(s==='game') return setupState.scope==='rounds' || setupState.scope==='match';
    if(s==='gameMode') return (setupState.scope==='rounds' || setupState.scope==='match') && !!GAME_MODES[setupState.gameId];
    if(s==='gamesMulti') return setupState.scope==='games';
    if(noRounds && ['mode','sessionMode','difficulty','role','heroLock','pointGoal','rounds'].includes(s)) return false;
    if(s==='rounds') return setupState.scope==='rounds' || setupState.scope==='match';
    if(s==='difficulty') return setupState.sessionMode==='challenge';
    if(s==='role') return !!sessionRoleOptions();
    if(s==='heroLock') return sessionHasHeroGames() && setupState.scope !== 'match';
    return true;
  });
}

async function startFreshSetup(){
  continueFromSession = false;
  const saved = loadSetupState();
  if(saved && saved.setupState && (saved.setupState.gameId || (saved.setupState.selectedGames && saved.setupState.selectedGames.length))){
    const resume = await confirmAction('Du hast eine unvollendete Runden-Einrichtung. Fortsetzen? (Abbrechen = neu starten)', '🔁');
    if(resume){
      setupState = saved.setupState;
      stepIndex = saved.stepIndex || 0;
      renderSetupPage(); showStep();
      showView('session-setup');
      return;
    }
  }
  setupState = { scope:'rounds', gameId:null, gameMode:null, gamesCount:5, selectedGames:[], gameModeChoices:{}, randomOrder:true, roundsPerGame:1, funChallenges:true, mode:'team', sessionMode:'challenge', difficulty:'Mittel', playerRoles:{}, heroLockMode:'reroll', pointGoalChoice:'none', customGoalValue:300, rounds:3, count:4, selectedPlayers:[] };
  stepIndex = 0;
  if(myTeam && teamMembers.length){
    teamMembers.forEach(m=>{
      if(!globalPlayers.includes(m.username)) globalPlayers.push(m.username);
      avatarMap[m.username] = m.avatar || avatarFor(m.username);
    });
    savePlayers(); saveAvatars();
    setupState.count = Math.min(6, Math.max(3, teamMembers.length));
    setupState.selectedPlayers = teamMembers.map(m=>m.username).slice(0, setupState.count);
  } else {
    autoFillPlayers();
  }
  renderSetupPage(); showStep();
  showView('session-setup');
}

function autoFillPlayers(){
  while(setupState.selectedPlayers.length < setupState.count){
    const next = globalPlayers.find(p=>!setupState.selectedPlayers.includes(p));
    if(!next) break;
    setupState.selectedPlayers.push(next);
  }
}
function autoFillGames(){
  while(setupState.selectedGames.length < setupState.gamesCount){
    const next = SESSION_GAMES.find(id=>!setupState.selectedGames.includes(id));
    if(!next) break;
    setupState.selectedGames.push(next);
  }
}

function addPlayerInSetup(){
  const input = document.getElementById('setup-new-player-input');
  const name = input.value.trim();
  if(!name) return;
  if(globalPlayers.includes(name)){ input.value=''; return; }
  globalPlayers.push(name); savePlayers(); avatarFor(name);
  input.value = '';
  if(setupState.selectedPlayers.length < setupState.count) setupState.selectedPlayers.push(name);
  renderSetupPage(); showStep();
}
function buildPillRow(containerId, items, currentKey, onPick){
  const row = document.getElementById(containerId); row.innerHTML = '';
  items.forEach(it=>{
    const btn = document.createElement('button'); btn.className = 'filter-pill'+(it.key===currentKey?' active':''); btn.innerHTML = it.label;
    btn.addEventListener('click', ()=>{ onPick(it.key); renderSetupPage(); showStep(); });
    row.appendChild(btn);
  });
}

function renderSetupPage(){
  buildPillRow('setup-scope', [{key:'rounds',label:'🔁 Nach Runden'},{key:'match',label:'🏆 Nach Match'},{key:'games',label:'🎮 Nach Spielen'}], setupState.scope, k=>{
    setupState.scope = k;
    if(k==='games' && setupState.selectedGames.length===0) autoFillGames();
  });
  document.getElementById('setup-scope-desc').textContent = setupState.scope==='match'
    ? '🏆 MATCH: Der Held bleibt fürs ganze Match gleich, die Challenges sind größer und für das ganze Match gedacht (mehr davon, länger).'
    : setupState.scope==='games'
    ? 'Ihr wählt mehrere verschiedene Spiele, die nacheinander gespielt werden (je 1 Runde).'
    : 'Ihr spielt ein Spiel über eine feste Rundenanzahl, könnt zwischendurch aber wechseln.';

  buildPillRow('setup-games', SESSION_GAMES.map(id=>({key:id, label: gameIconHTML(id,18)+' '+GAME_NAME[id]})), setupState.gameId, k=>{ setupState.gameId=k; setupState.gameMode=null; });
  const gameModeNote = document.getElementById('setup-game-mode-note');
  if(gameModeNote){
    const restricted = setupState.gameId ? allowedModesFor(setupState.gameId) : ['team','versus'];
    gameModeNote.textContent = restricted.length===1
      ? (restricted[0]==='team' ? '🤝 Dieses Spiel geht nur im Team-Modus.' : '⚔️ Dieses Spiel geht nur „Jeder gegen Jeden" — kein Team-Modus.')
      : '';
  }

  const gmPool = GAME_MODES[setupState.gameId];
  if(gmPool){
    if(!setupState.gameMode || !gmPool.some(m=>m.key===setupState.gameMode)) setupState.gameMode = gmPool[0].key;
    buildPillRow('setup-gamemode', gmPool.map(m=>({key:m.key,label:m.label})), setupState.gameMode, k=>{ setupState.gameMode=k; renderSetupPage(); });
    const gm = gmPool.find(m=>m.key===setupState.gameMode);
    const gmDesc = document.getElementById('setup-gamemode-desc');
    if(gmDesc) gmDesc.textContent = gm ? gm.hint : '';
    if(gm && gm.noRounds){
      // Roundlose Modi (z. B. Deathmatch): sinnvolle Defaults setzen, damit der Assistent
      // direkt zu Spieleranzahl/Teilnehmern springt statt Fragen zu stellen, die hier keinen Sinn ergeben.
      setupState.mode = 'versus'; setupState.sessionMode = 'challenge'; setupState.difficulty = 'Mittel';
      setupState.pointGoalChoice = 'none'; setupState.rounds = 1;
    }
  } else {
    setupState.gameMode = null;
  }

  const gmWrap = document.getElementById('setup-games-multi'); gmWrap.innerHTML = '';
  SESSION_GAMES.forEach(id=>{
    const selected = setupState.selectedGames.includes(id);
    const chip = document.createElement('button'); chip.className = 'chip selectable'+(selected?' selected':''); chip.innerHTML = gameIconHTML(id,18)+' '+GAME_NAME[id];
    chip.addEventListener('click', ()=>{
      if(selected) setupState.selectedGames = setupState.selectedGames.filter(g=>g!==id);
      else setupState.selectedGames.push(id);
      renderSetupPage(); showStep();
    });
    gmWrap.appendChild(chip);
  });
  document.getElementById('setup-gamescount-hint').textContent = setupState.selectedGames.length ? `(${setupState.selectedGames.length} ausgewählt)` : '(beliebig viele auswählen)';

  buildPillRow('setup-games-order', [{key:true,label:'🔀 Zufällig'},{key:false,label:'📋 Auswahl-Reihenfolge'}], setupState.randomOrder, k=>{ setupState.randomOrder = k; });
  buildPillRow('setup-games-roundsper', [{key:1,label:'1'},{key:2,label:'2'},{key:3,label:'3'},{key:'random',label:'🎲 Zufällig (1-3)'}], setupState.roundsPerGame, k=>{ setupState.roundsPerGame = k; });

  const gamesModesWrap = document.getElementById('setup-games-modes-wrap'); gamesModesWrap.innerHTML = '';
  setupState.selectedGames.forEach(id=>{
    const pool = GAME_MODES[id];
    if(!pool) return;
    if(!setupState.gameModeChoices[id] || !pool.some(m=>m.key===setupState.gameModeChoices[id])) setupState.gameModeChoices[id] = pool[0].key;
    const box = document.createElement('div');
    box.style.marginTop = '14px';
    box.innerHTML = `<div class="setup-info" style="margin-bottom:4px;">🕹️ Modus für ${gameIconHTML(id,16)} ${GAME_NAME[id]}</div><div class="filter-row" id="setup-gm-${id}"></div>`;
    gamesModesWrap.appendChild(box);
    const row = box.querySelector(`#setup-gm-${id}`);
    pool.forEach(m=>{
      const btn = document.createElement('button');
      btn.className = 'filter-pill'+(m.key===setupState.gameModeChoices[id]?' active':'');
      btn.textContent = m.label;
      btn.addEventListener('click', ()=>{ setupState.gameModeChoices[id] = m.key; renderSetupPage(); });
      row.appendChild(btn);
    });
  });

  const MODE_LABELS = {team:'🤝 Team gegen Team', versus:'⚔️ Jeder gegen Jeden'};
  const allowedModes = allowedModesForSelection();
  if(!allowedModes.includes(setupState.mode)) setupState.mode = allowedModes[0];
  buildPillRow('setup-mode', allowedModes.map(m=>({key:m,label:MODE_LABELS[m]})), setupState.mode, k=>{ setupState.mode=k; });
  document.getElementById('setup-mode-desc').textContent = allowedModes.length===1
    ? (allowedModes[0]==='team' ? 'Dieses Spiel ist reines Koop — nur Team-Modus möglich.' : 'Dieses Spiel ist reiner Wettkampf — nur Gegeneinander möglich.')
    : (setupState.mode==='versus'
        ? 'Persönliche Wettkampf-Challenges pro Spieler (z. B. meiste Kills), plus ein paar gemeinsame Spielregeln.'
        : 'Gemeinsame Spielregeln fürs ganze Team, alle arbeiten auf dasselbe Ziel hin.');

  buildPillRow('setup-sessionmode', [{key:'challenge',label:'🎯 Challenge'},{key:'chaos',label:'🌀 Chaos'}], setupState.sessionMode, k=>{ setupState.sessionMode=k; });
  document.getElementById('setup-sessionmode-desc').textContent = setupState.sessionMode==='chaos'
    ? 'Zufällige Helden ohne Rollen-Balance, garantiert harte Challenges, doppelte Punkte.'
    : 'Ausgewogene Team-Zusammenstellung nach Rollen, Schwierigkeit frei wählbar.';
  buildPillRow('setup-funchallenges', [{key:false,label:'Aus'},{key:true,label:'An'}], setupState.funChallenges, k=>{ setupState.funChallenges=k; });

  buildPillRow('setup-difficulty', ['Leicht','Mittel','Schwer'].map(d=>({key:d,label:d})), setupState.difficulty, k=>{ setupState.difficulty=k; });

  const roleOptions = sessionRoleOptions();
  const rolePlayersWrap = document.getElementById('setup-role-players');
  if(!roleOptions){
    setupState.playerRoles = {};
  } else if(rolePlayersWrap){
    rolePlayersWrap.innerHTML = '';
    // Alte Auswahl von Spielern bereinigen, die nicht mehr Teil der Runde sind.
    Object.keys(setupState.playerRoles).forEach(p=>{ if(!setupState.selectedPlayers.includes(p)) delete setupState.playerRoles[p]; });
    if(!setupState.selectedPlayers.length){
      rolePlayersWrap.innerHTML = `<div class="empty-hint">Wählt zuerst eure Teilnehmer aus (nächster Schritt), dann könnt ihr hier Rollen verteilen.</div>`;
    }
    setupState.selectedPlayers.forEach(p=>{
      const row = document.createElement('div');
      row.className = 'player-block-label';
      row.style.cssText = 'flex-direction:column; align-items:flex-start; gap:6px; margin-bottom:10px;';
      row.innerHTML = playerCosmeticCardHTML(p, withHatOverlay(p, avatarHTML(p,20), 20));
      const pillRow = document.createElement('div');
      pillRow.className = 'filter-row';
      pillRow.style.marginTop = '2px';
      [{key:'all',label:'🎲 Zufällig'}, ...roleOptions.map(r=>({key:r, label:`${ROLE_META[r]?ROLE_META[r].icon:''} ${r}`}))].forEach(it=>{
        const btn = document.createElement('button');
        btn.className = 'filter-pill'+((setupState.playerRoles[p]||'all')===it.key?' active':'');
        btn.textContent = it.label;
        btn.addEventListener('click', ()=>{ setupState.playerRoles[p] = it.key; renderSetupPage(); showStep(); });
        pillRow.appendChild(btn);
      });
      row.appendChild(pillRow);
      rolePlayersWrap.appendChild(row);
    });
  }

  buildPillRow('setup-herolock', [{key:'reroll',label:'🔄 Jede Runde neu'},{key:'locked',label:'🔒 Gleicher Held'}], setupState.heroLockMode, k=>{ setupState.heroLockMode=k; });
  document.getElementById('setup-herolock-desc').textContent = setupState.heroLockMode==='locked'
    ? 'Jeder behält seinen ausgelosten Helden über alle Runden hinweg (bis ihr das Spiel wechselt).'
    : 'Vor jeder neuen Runde wird für alle ein neuer Held ausgelost.';
  const roundOptions = roundOptionsFor(setupState.gameId, setupState.gameMode, setupState.scope==='match');
  if(!roundOptions.includes(setupState.rounds)) setupState.rounds = roundOptions[Math.floor(roundOptions.length/2)];
  buildPillRow('setup-rounds', roundOptions.map(n=>({key:n,label:String(n)})), setupState.rounds, k=>{ setupState.rounds=k; });
  const isMatchStyle = matchStyleFor(setupState.gameId, setupState.gameMode)==='match';
  const roundsTitle = document.getElementById('setup-rounds-title');
  if(roundsTitle) roundsTitle.textContent = 'Anzahl Runden';
  const roundsHint = document.getElementById('setup-rounds-hint');
  if(roundsHint) roundsHint.textContent = isMatchStyle ? 'Bei diesem Modus deckt 1 Runde ein komplettes Match ab (größeres Challenge-Set).' : '';

  buildPillRow('setup-pointgoal', [{key:'none',label:'Kein Ziel'},{key:100,label:'100'},{key:250,label:'250'},{key:500,label:'500'},{key:'custom',label:'Eigenes'}], setupState.pointGoalChoice, k=>{ setupState.pointGoalChoice=k; });
  document.getElementById('setup-pointgoal-custom-wrap').style.display = setupState.pointGoalChoice==='custom' ? 'flex' : 'none';
  document.getElementById('setup-pointgoal-custom').value = setupState.customGoalValue;

  buildPillRow('setup-count', [2,3,4,5,6].map(n=>({key:n,label:String(n)})), setupState.count, k=>{
    setupState.count = k;
    if(setupState.selectedPlayers.length > k) setupState.selectedPlayers = setupState.selectedPlayers.slice(0, k);
    else autoFillPlayers();
  });
  document.getElementById('setup-count-hint').textContent = `(${setupState.selectedPlayers.length}/${setupState.count} ausgewählt)`;

  const chipsWrap = document.getElementById('setup-player-chips'); chipsWrap.innerHTML = '';
  if(!globalPlayers.length){
    chipsWrap.innerHTML = `<div class="empty-hint">Noch keine Spieler angemeldet — fügt unten welche hinzu.</div>`;
  } else {
    globalPlayers.forEach(name=>{
      const selected = setupState.selectedPlayers.includes(name);
      const chip = document.createElement('button'); chip.className = 'chip selectable'+(selected?' selected':''); chip.innerHTML = avatarHTML(name,18)+' '+name;
      chip.addEventListener('click', ()=>{
        if(selected) setupState.selectedPlayers = setupState.selectedPlayers.filter(n=>n!==name);
        else { if(setupState.selectedPlayers.length >= setupState.count) return; setupState.selectedPlayers.push(name); }
        renderSetupPage(); showStep();
      });
      chipsWrap.appendChild(chip);
    });
  }

  const heroHint = document.getElementById('setup-hero-hint');
  if(setupState.scope === 'games') heroHint.textContent = 'Bei Spielen mit Helden (z. B. Overwatch, Marvel Rivals, FragPunk, Valorant, Rainbow Six Siege) wird pro Runde automatisch ein Held ausgelost.';
  if(setupState.scope === 'match') heroHint.textContent = 'Bei Spielen mit Helden bleibt der Held fürs ganze Match gleich.';
  else if(setupState.gameId && !HERO_GAMES[setupState.gameId]) heroHint.textContent = 'Dieses Spiel hat keine Helden — es werden nur Regeln/Challenges verlost.';
  else if(setupState.gameId) heroHint.textContent = 'Zusätzlich wird für jeden Spieler ein Held ausgelost.';
  else heroHint.textContent = '';
}

document.getElementById('setup-pointgoal-custom').addEventListener('input', e=>{ setupState.customGoalValue = parseInt(e.target.value)||0; });

function showStep(){
  const steps = visibleSteps();
  if(stepIndex >= steps.length) stepIndex = steps.length-1;
  if(stepIndex < 0) stepIndex = 0;
  const current = steps[stepIndex];
  document.querySelectorAll('.setup-step').forEach(el=>el.style.display='none');
  document.getElementById('step-'+current).style.display='block';
  document.getElementById('setup-progress').textContent = `Schritt ${stepIndex+1} / ${steps.length}`;
  document.getElementById('setup-back-btn').classList.toggle('invisible', stepIndex===0);
  const isLast = stepIndex === steps.length-1;
  document.getElementById('setup-next-btn').style.display = isLast ? 'none' : 'inline-flex';
  document.getElementById('setup-start-btn').style.display = isLast ? 'inline-flex' : 'none';
  document.getElementById('setup-warning').textContent = '';
  const heroHint = document.getElementById('setup-hero-hint');
  heroHint.style.display = (current === 'game' || current === 'gamesMulti') ? 'block' : 'none';
  saveSetupState();
}

function nextStep(){
  const steps = visibleSteps(); const cur = steps[stepIndex]; const warn = document.getElementById('setup-warning'); warn.textContent = '';
  if(cur === 'game' && !setupState.gameId){ warn.textContent = 'Bitte wählt ein Spiel aus.'; return; }
  if(cur === 'gamesMulti' && setupState.selectedGames.length < 1){ warn.textContent = 'Bitte wählt mindestens ein Spiel aus.'; return; }
  if(cur === 'pointGoal' && setupState.pointGoalChoice==='custom' && (!setupState.customGoalValue || setupState.customGoalValue<1)){ warn.textContent = 'Bitte gebt ein gültiges Punkteziel ein.'; return; }
  if(stepIndex < steps.length-1){ stepIndex++; renderSetupPage(); showStep(); }
}
function prevStep(){ if(stepIndex>0){ stepIndex--; renderSetupPage(); showStep(); } }

function resolvePointGoal(){
  if(setupState.pointGoalChoice==='none') return null;
  if(setupState.pointGoalChoice==='custom') return setupState.customGoalValue || null;
  return setupState.pointGoalChoice;
}

function handleStartClick(){
  const warn = document.getElementById('setup-warning');
  if(setupState.selectedPlayers.length !== setupState.count){ warn.textContent = `Bitte wählt genau ${setupState.count} Spieler aus.`; return; }
  if(setupState.scope==='games' && setupState.selectedGames.length < 1){ warn.textContent = 'Bitte wählt mindestens ein Spiel aus.'; return; }
  if(setupState.pointGoalChoice==='custom' && (!setupState.customGoalValue || setupState.customGoalValue<1)){ warn.textContent = 'Bitte gebt ein gültiges Punkteziel ein.'; return; }
  warn.textContent = '';
  clearSetupState();

  personalityChallengesEnabled = !!setupState.funChallenges;
  const gameSequence = setupState.scope==='games' ? buildGameSequence(setupState.selectedGames, setupState.roundsPerGame, setupState.randomOrder) : null;
  const initialGameId = setupState.scope==='games' ? gameSequence[0] : setupState.gameId;
  const totalRounds = setupState.scope==='games' ? gameSequence.length : setupState.rounds;
  const pointGoal = resolvePointGoal();
  const gameModeChoices = setupState.scope==='games' ? Object.assign({}, setupState.gameModeChoices) : null;
  const gameMode = (setupState.scope==='rounds' || setupState.scope==='match')
    ? setupState.gameMode
    : (gameModeChoices ? (gameModeChoices[initialGameId] || null) : null);
  const matchStyle = setupState.scope==='match' ? 'match' : (setupState.scope==='rounds' ? matchStyleFor(initialGameId, gameMode) : null);

  if(continueFromSession && session){
    session.scope = setupState.scope; session.gameId = initialGameId; session.gameSequence = gameSequence; session.currentGameIndex = 0;
    session.mode = setupState.mode; session.sessionMode = setupState.sessionMode; session.difficultyKey = setupState.difficulty;
    session.heroLockMode = setupState.heroLockMode; session.gameMode = gameMode; session.matchStyle = matchStyle;
    session.gameModeChoices = gameModeChoices || {};
    session.roleMap = Object.assign({}, setupState.playerRoles);
    session.totalRounds = totalRounds; session.pointGoal = pointGoal; session.players = setupState.selectedPlayers.slice();
    session.currentRound = session.currentRound + 1; session.awaitingNextGameChoice = false;
    if(session.mode==='versus'){ session.cumulativePlayers = session.cumulativePlayers || {}; session.players.forEach(p=>{ if(!(p in session.cumulativePlayers)) session.cumulativePlayers[p]=0; }); }
    buildRound(); saveSession(); continueFromSession = false;
    showView('session');
  } else {
    startSession({
      scope: setupState.scope, gameId: initialGameId, gameSequence,
      mode: setupState.mode, sessionMode: setupState.sessionMode, heroLockMode: setupState.scope==='match' ? 'locked' : setupState.heroLockMode,
      gameMode, matchStyle, gameModeChoices, roleMap: Object.assign({}, setupState.playerRoles),
      difficultyKey: setupState.difficulty, totalRounds, pointGoal, players: setupState.selectedPlayers.slice(),
    });
    showView('session');
  }
}

/* ============================================================ HERO ASSIGNMENT ============================================================ */
const LS_ROLE_HISTORY = 'winchallenge_role_history_v1';
function loadRoleHistory(){ try{ const raw = localStorage.getItem(LS_ROLE_HISTORY); return raw ? JSON.parse(raw) : {}; }catch(e){ return {}; } }
function saveRoleHistory(){ try{ localStorage.setItem(LS_ROLE_HISTORY, JSON.stringify(roleHistory)); }catch(e){} }
let roleHistory = loadRoleHistory(); // { spielerKey: [rolle, rolle, rolle] } — die letzten 3 zugewiesenen Rollen
// Gleiches Prinzip fürs konkrete Held/Agent-Auslosen: pro Spieler+Spiel merken wir uns die zuletzt
// zugewiesenen Helden und schließen sie eine Weile aus dem Pool aus — echte Rotation "ohne
// Zurücklegen" statt komplett unabhängiger Zufallsziehung, damit sich gefühlt alle Helden
// gleichmäßiger abwechseln, statt dass ein und derselbe zufällig mehrfach hintereinander kommt
// (oder ein anderer sehr lange gar nicht).
const LS_HERO_HISTORY = 'winchallenge_hero_history_v1';
function loadHeroHistory(){ try{ const raw = localStorage.getItem(LS_HERO_HISTORY); return raw ? JSON.parse(raw) : {}; }catch(e){ return {}; } }
function saveHeroHistory(){ try{ localStorage.setItem(LS_HERO_HISTORY, JSON.stringify(heroHistory)); }catch(e){} }
let heroHistory = loadHeroHistory(); // { 'spielerKey:gameId': [heldname, heldname, ...] }
function recordHeroForPlayer(playerKey, gameId, heroName){
  const key = playerKey+':'+gameId;
  const hist = heroHistory[key] || [];
  hist.push(heroName);
  while(hist.length > 6) hist.shift(); // deckt auch kleinere Rollen-Pools ab, ohne sie je leerzuräumen
  heroHistory[key] = hist;
  saveHeroHistory();
}
function recentHeroesFor(playerKey, gameId){
  return new Set(heroHistory[playerKey+':'+gameId] || []);
}
// Wählt aus choices einen Helden, bevorzugt einen, der für diese/n Spieler:in in diesem Spiel nicht
// erst kürzlich dran war. Ist choices nach dem Ausschluss leer (Rollen-Pool zu klein), wird die
// Historie für diesen einen Pick ignoriert, statt einen leeren Pool zu riskieren.
function pickHeroAvoidingRecent(choices, playerKey, gameId){
  if(!choices.length) return null;
  const recent = recentHeroesFor(playerKey, gameId);
  let filtered = choices.filter(h=>!recent.has(h[0]));
  if(!filtered.length) filtered = choices;
  const hero = filtered[randInt(0, filtered.length-1)];
  recordHeroForPlayer(playerKey, gameId, hero[0]);
  return hero;
}
function recordRoleForPlayer(playerKey, role){
  const hist = roleHistory[playerKey] || [];
  hist.push(role);
  while(hist.length > 3) hist.shift();
  roleHistory[playerKey] = hist;
  saveRoleHistory();
}
function isRoleStreaked(playerKey, role){
  const hist = roleHistory[playerKey] || [];
  return hist.length >= 3 && hist.every(r=>r===role);
}
function dedupRoleStreaks(slots, players){
  // Verhindert, dass jemand eine 4. Runde in Folge dieselbe Rolle bekommt — tauscht ggf. mit
  // einem anderen Spieler, für den der Tausch keinen neuen Streak erzeugt.
  for(let i=0;i<players.length;i++){
    if(isRoleStreaked(players[i], slots[i])){
      for(let j=0;j<players.length;j++){
        if(j===i || slots[j]===slots[i]) continue;
        if(!isRoleStreaked(players[i], slots[j]) && !isRoleStreaked(players[j], slots[i])){
          const tmp = slots[i]; slots[i] = slots[j]; slots[j] = tmp;
          break;
        }
      }
    }
  }
  return slots;
}
// Bei OW2/Marvel Rivals ist die reine Gewichts-Proportion (Tank:1, Damage:2, Support:2) nur für
// die aktuelle 5v5-Größe korrekt. Bei 6 Spielern (klassisches 2-2-2, z. B. Custom-Lobbys/OW1-Format)
// würde die Proportion NIE auf 2 Tanks kommen (1.2 rundet immer auf 1 ab). Für die bekannten
// Competitive-Formate daher feste Verteilungen, sonst bleibt es bei der Gewichts-Proportion.
const ROLE_COMP_BY_COUNT = {
  ow2: { 5:{Tank:1,Damage:2,Support:2}, 6:{Tank:2,Damage:2,Support:2} },
  mr:  { 5:{Tank:1,Damage:2,Support:2}, 6:{Tank:2,Damage:2,Support:2} },
};
function assignHeroesBalanced(heroPool, players, weights, gameId){
  const roles = {};
  heroPool.forEach(([name,role])=>{ (roles[role] = roles[role]||[]).push(name); });
  // shuffle() hier ist wichtig: bei gleichen Gewichten (z. B. Valorant) sind die Nachkomma-Reste
  // bei kleinen Gruppen oft alle identisch — ein stabiler Sort würde dann IMMER dieselbe Rolle
  // (die erste im Objekt) bevorzugen. Durch das Mischen vor dem Sortieren wird der Tie-Break fair.
  const roleNames = shuffle(Object.keys(roles).filter(r=>weights[r] !== undefined));
  const fixedComp = ROLE_COMP_BY_COUNT[gameId] && ROLE_COMP_BY_COUNT[gameId][players.length];
  const counts = {}; let assigned = 0;
  if(fixedComp){
    roleNames.forEach(r=>{ counts[r] = fixedComp[r] || 0; assigned += counts[r]; });
    // Falls die feste Verteilung nicht exakt zur Spielerzahl passt (z. B. unbekannte Rolle im Pool),
    // Rest ganz normal nach Gewicht auffüllen statt Spieler ohne Rolle zu lassen.
    if(assigned < players.length){
      const remWeight = roleNames.reduce((s,r)=>s+weights[r],0);
      const rem = shuffle(roleNames.map(r=>({r, frac:weights[r]/remWeight}))).sort((a,b)=>b.frac-a.frac);
      let i = 0;
      while(assigned < players.length){ counts[rem[i % rem.length].r]++; assigned++; i++; }
    }
  } else {
    const totalWeight = roleNames.reduce((s,r)=>s+weights[r],0);
    const raw = roleNames.map(r=>({ r, exact: weights[r]/totalWeight*players.length }));
    raw.forEach(x=>{ counts[x.r] = Math.floor(x.exact); assigned += counts[x.r]; });
    const remainders = shuffle(raw.map(x=>({ r:x.r, frac:x.exact-counts[x.r] }))).sort((a,b)=>b.frac-a.frac);
    let i = 0;
    while(assigned < players.length){ counts[remainders[i % remainders.length].r]++; assigned++; i++; }
  }
  let slots = [];
  roleNames.forEach(r=>{ for(let k=0;k<counts[r];k++) slots.push(r); });
  slots = shuffle(slots);
  slots = dedupRoleStreaks(slots, players);
  const usedPerRole = {}; const assignment = {};
  players.forEach((p,idx)=>{
    const role = slots[idx] || roleNames[0];
    usedPerRole[role] = usedPerRole[role] || new Set();
    const rolePool = shuffle(roles[role] || []);
    const notUsedThisRound = rolePool.filter(h=>!usedPerRole[role].has(h));
    const recent = recentHeroesFor(p, gameId);
    const notRecent = notUsedThisRound.filter(h=>!recent.has(h));
    const candidates = notRecent.length ? notRecent : (notUsedThisRound.length ? notUsedThisRound : rolePool);
    const heroName = candidates[0] || (heroPool[0] ? heroPool[0][0] : '?');
    usedPerRole[role].add(heroName);
    recordHeroForPlayer(p, gameId, heroName);
    assignment[p] = [heroName, role];
    recordRoleForPlayer(p, role);
  });
  return assignment;
}
function assignHeroesChaos(heroPool, players){
  const assignment = {};
  players.forEach(p=>{
    let pick, tries = 0;
    do { pick = heroPool[randInt(0, heroPool.length-1)]; tries++; } while(isRoleStreaked(p, pick[1]) && tries<20);
    assignment[p] = pick;
    recordRoleForPlayer(p, pick[1]);
  });
  return assignment;
}

/* ============================================================ CHALLENGE GENERATION ============================================================ */
function pickByComposition(pool, comp, usedThemes){
  usedThemes = usedThemes || new Set();
  const cats = { leicht:[], mittel:[], schwer:[] };
  pool.forEach(c=>cats[c.diff].push(c));
  let result = [];
  ['leicht','mittel','schwer'].forEach(d=>{ const n = Math.min(comp[d], cats[d].length); result = result.concat(shuffle(pickUniqueThemes(cats[d], n, usedThemes))); });
  return result;
}
function generateChallengesForRound(pool, difficultyKey, sessionMode, forcedComp, players, usedThemes){
  const comp = forcedComp || (sessionMode === 'chaos' ? CHAOS_COMPOSITION : DIFF_COMPOSITION[difficultyKey]);
  const chosen = pickByComposition(pool, comp, usedThemes);
  const mult = sessionMode === 'chaos' ? 2 : 1;
  return chosen.map((c,i)=>({
    id: 'c'+i+'_'+Math.random().toString(36).slice(2,7),
    text: substitutePlayerName(c.text, players), diff: c.diff, points: DIFF_POINTS[c.diff]*mult, state: 'pending', chaos: sessionMode==='chaos',
  }));
}
function buildPersonalChallengeSet(gameId, difficultyKey, sessionMode, playerKeys, heroAssignment, forcedComp, overridePool, usedThemes){
  const personalPool = overridePool || PERSONAL_SOURCES[gameId];
  const comp = forcedComp || (sessionMode === 'chaos' ? CHAOS_COMPOSITION : DIFF_COMPOSITION[difficultyKey]);
  const mult = sessionMode === 'chaos' ? 2 : 1;
  const roleAware = !!heroAssignment && personalPool.some(c=>c.roles);
  // Optional von außen mitgegeben (z. B. die Themen der bereits gewählten gemeinsamen Team-Regeln),
  // damit eine persönliche Challenge nicht einer gemeinsamen Regel widerspricht (z. B. "Setzt euer
  // Ultimate ein" gleichzeitig mit der Team-Regel "Niemand darf seine Ultimate benutzen").
  const usedThemesAcrossTeam = usedThemes || new Set();
  const result = {};
  playerKeys.forEach(key=>{
    let poolForPlayer = personalPool;
    if(roleAware){
      const role = heroAssignment[key] ? heroAssignment[key][1] : null;
      const filtered = personalPool.filter(c=>!c.roles || c.roles.includes(role));
      if(filtered.length) poolForPlayer = filtered;
    }
    const cats = { leicht:[], mittel:[], schwer:[] };
    poolForPlayer.forEach(c=>cats[c.diff].push(c));
    // Fallback-Kategorien aus dem KOMPLETTEN Pool (ohne Rollen-Filter) — falls der rollen-spezifische
    // Pool für eine Schwierigkeit zu klein ist (manche Rollen haben einfach weniger hinterlegte
    // Challenges), damit niemand deswegen weniger Challenges insgesamt bekommt als andere.
    const catsAll = { leicht:[], mittel:[], schwer:[] };
    personalPool.forEach(c=>catsAll[c.diff].push(c));
    let picked = [];
    ['leicht','mittel','schwer'].forEach(d=>{
      const need = comp[d];
      let chosen = shuffle(pickUniqueThemes(cats[d], Math.min(need, cats[d].length), usedThemesAcrossTeam));
      if(chosen.length < need){
        const remaining = catsAll[d].filter(c=>!chosen.includes(c));
        const extra = pickUniqueThemes(remaining, Math.min(need-chosen.length, remaining.length), usedThemesAcrossTeam);
        chosen = chosen.concat(extra);
      }
      picked = picked.concat(chosen);
    });
    result[key] = picked.map((c,i)=>({
      id: 'c'+i+'_'+Math.random().toString(36).slice(2,7),
      text: c.text, diff: c.diff, points: PERSONAL_DIFF_POINTS[c.diff]*mult, state: 'pending', chaos: sessionMode==='chaos',
    }));
  });
  return result;
}

/* ============================================================ SESSION / ROUNDS ============================================================ */
session = loadSession();
if(session && session.totalRounds === undefined){
  session.scope = session.scope || 'rounds';
  session.sessionMode = session.sessionMode || 'challenge';
  session.totalRounds = 1; session.currentRound = 1; session.finished = false; session.awaitingNextGameChoice = false;
  if(session.mode==='team'){ session.cumulativeTeam = 0; }
  else { session.cumulativePlayers = {}; (session.players||[]).forEach(p=>session.cumulativePlayers[p]=0); }
}
if(session && session.sharedRules === undefined){
  session.sharedRules = session.challenges || [];
  session.personalChallenges = session.mode==='versus' ? {} : null;
  session.pointGoal = session.pointGoal || null;
}
if(session && session.heroRevealDone === undefined){
  session.heroRevealDone = true;
  session.heroRevealIndex = 0;
}

function buildRound(){
  playStartCue();
  const heroPool = HERO_GAMES[session.gameId] || null;
  let heroesFreshlyAssigned = false;
  if(heroPool){
    const keepExisting = session.heroLockMode === 'locked' && session.heroAssignment && session._heroAssignedGameId === session.gameId;
    if(!keepExisting){
      if(session.sessionMode==='chaos'){
        session.heroAssignment = assignHeroesChaos(heroPool, session.players);
      } else if(hasAnyRoleChoice(session.roleMap)){
        session.heroAssignment = assignHeroesByPlayerRoles(session.gameId, session.players, session.roleMap);
      } else {
        session.heroAssignment = assignHeroesBalanced(heroPool, session.players, ROLE_WEIGHTS[session.gameId], session.gameId);
      }
      session._heroAssignedGameId = session.gameId;
      heroesFreshlyAssigned = true;
    }
  } else {
    session.heroAssignment = null;
    session._heroAssignedGameId = null;
  }
  session.heroRevealDone = !heroesFreshlyAssigned;
  session.heroRevealIndex = 0;

  const rulesPool = rulesPoolFor(session.gameId, session.gameMode);
  session.revealedPlayer = null;
  session.votingPhase = false;
  // Im "Spiele nacheinander"-Scope deckt eine App-Runde jeweils ein komplettes Match des Spiels ab
  // (nicht nur eine kurze Ingame-Runde) — daher genau wie beim expliziten Match-Style ein größeres
  // Challenge-Set statt der kleinen Standard-Composition.
  const isMatchStyle = (session.matchStyle === 'match' || session.scope === 'games') && session.sessionMode !== 'chaos';
  const forcedComp = isMatchStyle ? MATCH_STYLE_COMPOSITION[session.difficultyKey] : null;
  if(session.mode === 'team'){
    session.sharedRules = generateChallengesForRound(rulesPool, session.difficultyKey, session.sessionMode, forcedComp, session.players);
    session.personalChallenges = null;
  } else {
    // Gemeinsames Themen-Set für BEIDE Aufrufe — sonst wurden gemeinsame Regeln und persönliche
    // Challenges unabhängig voneinander dedupliziert und konnten sich inhaltlich widersprechen
    // (z. B. gemeinsame Regel "Niemand darf seine Ultimate benutzen" gleichzeitig mit einer
    // persönlichen Challenge, die genau das verlangt) oder sich schlicht doppeln.
    const usedThemes = new Set();
    session.sharedRules = generateChallengesForRound(rulesPool, session.difficultyKey, session.sessionMode, VERSUS_RULES_COMPOSITION, session.players, usedThemes);
    session.personalChallenges = buildPersonalChallengeSet(session.gameId, session.difficultyKey, session.sessionMode, session.players, session.heroAssignment, forcedComp, personalPoolFor(session.gameId, session.gameMode), usedThemes);
  }
}

function startSession(cfg){
  session = {
    scope: cfg.scope, gameId: cfg.gameId, gameSequence: cfg.gameSequence || null, currentGameIndex: 0,
    mode: cfg.mode, sessionMode: cfg.sessionMode, difficultyKey: cfg.difficultyKey, heroLockMode: cfg.heroLockMode || 'reroll',
    gameMode: cfg.gameMode || null, matchStyle: cfg.matchStyle || null, gameModeChoices: cfg.gameModeChoices || {}, roleMap: cfg.roleMap || {},
    totalRounds: cfg.totalRounds, currentRound: 1, pointGoal: cfg.pointGoal || null, players: cfg.players,
    cumulativeTeam: cfg.mode==='team' ? 0 : undefined,
    cumulativePlayers: cfg.mode==='versus' ? Object.fromEntries(cfg.players.map(p=>[p,0])) : undefined,
    finished: false, awaitingNextGameChoice: false, pendingGameIntro: false, skippedGames: [], lastActionSkipped: false,
  };
  buildRound();
  saveSession(); renderScoreboard(); updateContinueButton();
}

function endRound(){
  recordRoundStats();
  if(session.mode==='team'){ session.cumulativeTeam = (session.cumulativeTeam||0) + scoreOf(session.sharedRules); }
  else {
    const sharedScore = scoreOf(session.sharedRules);
    session.players.forEach(p=>{ session.cumulativePlayers[p] = (session.cumulativePlayers[p]||0) + scoreOf(session.personalChallenges[p]) + sharedScore; });
  }
  let goalReached = false;
  if(session.pointGoal){
    if(session.mode==='team'){ goalReached = session.cumulativeTeam >= session.pointGoal; }
    else { goalReached = session.players.some(p=>session.cumulativePlayers[p] >= session.pointGoal); }
  }
  session.lastActionSkipped = false;
  if(goalReached || session.currentRound >= session.totalRounds){ session.finished = true; }
  else { session.awaitingNextGameChoice = true; }
  saveSession(); renderScoreboard(); updateContinueButton();
}
// Überspringt die aktuelle Runde/das aktuelle Match komplett — KEINE Punkte werden gutgeschrieben
// (im Unterschied zu endRound()). Bei "Spiele nacheinander" wird das übersprungene Spiel gemerkt,
// damit es sich später per reAddSkippedGame() wieder in die Session einbauen lässt.
async function skipRound(){
  if(!session) return;
  const label = session.scope==='games' ? 'dieses Spiel' : (session.mode==='team' ? 'diese Runde' : 'dieses Match');
  if(!(await confirmAction(`Seid ihr euch alle einig, ${label} zu überspringen? Es gibt dafür keine Punkte.`, '🚫'))) return;
  if(session.scope==='games' && session.gameId){
    session.skippedGames = session.skippedGames || [];
    if(!session.skippedGames.includes(session.gameId)) session.skippedGames.push(session.gameId);
  }
  session.votingPhase = false;
  session.lastActionSkipped = true;
  if(session.currentRound >= session.totalRounds){ session.finished = true; }
  else { session.awaitingNextGameChoice = true; }
  saveSession(); renderScoreboard(); updateContinueButton();
}
// Baut ein zuvor übersprungenes Spiel wieder ans Ende der laufenden "Spiele nacheinander"-Session ein.
function reAddSkippedGame(gameId){
  if(!session || session.scope!=='games' || !session.gameSequence) return;
  session.gameSequence.push(gameId);
  session.totalRounds += 1;
  session.skippedGames = (session.skippedGames||[]).filter(g=>g!==gameId);
  if(session.finished){ session.finished = false; session.awaitingNextGameChoice = true; }
  saveSession(); renderScoreboard(); updateContinueButton();
}
function skippedGamesChipsHTML(){
  if(!session || !session.skippedGames || !session.skippedGames.length) return '';
  return `<div class="rules-note" style="margin-top:14px;">🚫 Übersprungen in dieser Session:</div>
    <div class="player-chips" style="margin:6px 0 4px;">${session.skippedGames.map(gid=>
      `<button class="chip" style="cursor:pointer;border:none;" onclick="reAddSkippedGame('${gid}')">${gameIconHTML(gid,16)} ${GAME_NAME[gid]} · 🔁 wieder einbauen</button>`
    ).join('')}</div>`;
}
function chooseSameGame(){ session.currentRound++; session.awaitingNextGameChoice = false; session.lastActionSkipped = false; buildRound(); saveSession(); renderScoreboard(); }
function toggleGamePicker(){
  const el = document.getElementById('inline-game-picker');
  if(!el) return;
  el.style.display = el.style.display==='none' ? 'block' : 'none';
}
function continueSessionWithGame(gameId){
  session.gameId = gameId;
  session.gameMode = null; session.matchStyle = null;
  session.currentRound++;
  session.awaitingNextGameChoice = false;
  session.lastActionSkipped = false;
  buildRound(); saveSession(); renderScoreboard();
}
function advanceGameSequence(){
  session.currentGameIndex++; session.currentRound++;
  session.gameId = session.gameSequence[session.currentGameIndex];
  session.gameMode = (session.gameModeChoices && session.gameModeChoices[session.gameId]) || null;
  session.awaitingNextGameChoice = false;
  session.lastActionSkipped = false;
  session.pendingGameIntro = true;
  buildRound(); saveSession(); renderScoreboard();
}
function extendSession(){
  if(!session) return;
  session.totalRounds += 2;
  if(session.finished){ session.finished = false; session.awaitingNextGameChoice = true; }
  saveSession(); renderScoreboard(); updateContinueButton();
}
async function endSession(){
  if(!(await confirmAction('Session wirklich beenden? Der Fortschritt dieser Session geht verloren.'))) return;
  session = null; saveSession(); renderScoreboard(); updateContinueButton(); showHome();
}
function newSessionFromScoreboard(){ startFreshSetup(); }

function updateContinueButton(){
    if (typeof session === 'undefined') return;
  const btn = document.getElementById('continue-btn'); const sub = document.getElementById('continue-sub');
  const icon = document.getElementById('continue-icon');
  if(session){
    btn.classList.remove('disabled');
    if(icon) icon.innerHTML = gameIconHTML(session.gameId, 34);
    const modeLabel = session.mode==='team' ? 'Team' : 'Gegeneinander';
    const smLabel = session.sessionMode==='chaos' ? '🌀 Chaos' : '🎯 Challenge';
    const roundLabel = session.scope==='games' ? `Spiel ${session.currentGameIndex+1}/${session.gameSequence.length}` : `Runde ${session.currentRound}/${session.totalRounds}`;
    sub.innerHTML = `${gameIconHTML(session.gameId,16)} ${GAME_NAME[session.gameId]} · ${modeLabel} · ${smLabel} · ${roundLabel}`;
  } else if(myTeam && currentRound && (currentRound.status==='active' || currentRound.status==='voting')){
    btn.classList.remove('disabled');
    if(icon) icon.innerHTML = gameIconHTML(currentRound.game_id, 34);
    sub.innerHTML = `🌐 ${gameIconHTML(currentRound.game_id,16)} ${GAME_NAME[currentRound.game_id]||''} — Runde läuft in „${myTeam.name || 'Team'}"`;
  } else if(myTeam && currentRound && currentRound.status==='done'){
    btn.classList.remove('disabled');
    if(icon) icon.innerHTML = gameIconHTML(currentRound.game_id, 34);
    sub.innerHTML = `🌐 ${gameIconHTML(currentRound.game_id,16)} ${GAME_NAME[currentRound.game_id]||''} — Ergebnis in „${myTeam.name || 'Team'}"`;
  } else { btn.classList.add('disabled'); sub.textContent = 'Keine aktive Session'; if(icon) icon.textContent = '⏯️'; }
}

/* ============================================================ SCOREBOARD ============================================================ */
function scoreOf(arr){ return arr.reduce((s,c)=> s + (c.state==='win'? c.points : c.state==='lose' ? -c.points : 0), 0); }

function renderGoalBar(current, goal){
  if(!goal) return '';
  const pct = Math.max(0, Math.min(100, Math.round((current/goal)*100)));
  const remaining = Math.max(0, goal - current);
  return `<div class="goal-bar-wrap">
    <div class="goal-bar-label"><span>Punkte</span><span>${current} / ${goal}</span></div>
    <div class="goal-bar-track"><div class="goal-bar-fill" style="width:${pct}%"></div></div>
    <div class="goal-bar-sub">${remaining>0 ? `Noch ${remaining} Punkte bis zum Ziel · ${pct}%` : '🎉 Ziel erreicht!'}</div>
  </div>`;
}
function miniGoalBar(current, goal){
  if(!goal) return '';
  const pct = Math.max(0, Math.min(100, Math.round((current/goal)*100)));
  return `<div class="mini-goal-track"><div class="mini-goal-fill" style="width:0%" data-target-pct="${pct}"></div></div>`;
}
function animateMiniGoalBars(root){
  const scope = root || document;
  const bars = scope.querySelectorAll ? scope.querySelectorAll('.mini-goal-fill[data-target-pct]') : [];
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    bars.forEach(el=>{ el.style.width = el.dataset.targetPct + '%'; });
  }));
}

function renderHeroRow(entries, avatarResolver, gameId){
  let html = '<div class="solo-hero-list sb-hero-row">';
  entries.forEach(([playerName, hero])=>{
    const [heroName, role] = hero; const meta = ROLE_META[role]; const bg = heroColor(heroName);
    const avatarBit = withHatOverlay(playerName, avatarResolver ? avatarResolver(playerName) : avatarHTML(playerName,18), 18);
    const playerCard = playerCosmeticCardHTML(playerName, avatarBit);
    html += `<div class="solo-hero-item" style="opacity:1; transform:none;">
      <div class="solo-player">${playerCard}</div>
      <div class="solo-hero-body">
        <div class="solo-avatar" style="background:${heroImageFor(gameId,heroName)?'#000':bg}; overflow:hidden;">${heroAvatarInner(heroName,gameId)}<span class="avatar-badge" style="background:${meta.color}">${meta.icon}</span></div>
        <div class="solo-hero">${heroName}</div>
        <div class="solo-role" style="background:${meta.color}">${role}</div>
      </div></div>`;
  });
  html += '</div>'; return html;
}
function renderGameIntro(el, headHtml){
  const g = GAMES.find(x=>x.id===session.gameId);
  const cover = gameCoverCache[session.gameId];
  const cardStyle = cover ? `background-image:url('${cover.replace(/'/g,"%27")}');` : `background:${g?g.grad:'var(--bg-card)'};`;
  el.innerHTML = headHtml + `
    <div class="game-intro-card${cover?' has-cover':''}" style="${cardStyle}">
      <div class="game-intro-eyebrow">Nächstes Spiel</div>
      ${cover?'':`<div class="game-intro-icon">${g?g.icon:'🎮'}</div>`}
      <div class="game-intro-name">${GAME_NAME[session.gameId]}</div>
      <div class="game-intro-tag">${g?g.tag:''}</div>
      <button class="round-prompt-btn primary" id="game-intro-go">▶️ Los geht's</button>
    </div>`;
  const btn = document.getElementById('game-intro-go');
  if(btn) btn.onclick = ()=>{ session.pendingGameIntro = false; saveSession(); renderScoreboard(); };
}
function renderSessionHeroReveal(el, headHtml){
  const player = session.players[session.heroRevealIndex];
  const hero = session.heroAssignment[player];
  const pool = HERO_GAMES[session.gameId];
  const isLast = session.heroRevealIndex === session.players.length-1;
  const chosenRole = session.roleMap && session.roleMap[player] && session.roleMap[player]!=='all' ? session.roleMap[player] : null;
  const roleLine = chosenRole
    ? ` · Wunschrolle: ${ROLE_META[chosenRole]?ROLE_META[chosenRole].icon:''} ${chosenRole}`
    : (hero ? ` · Rolle: ${ROLE_META[hero[1]]?ROLE_META[hero[1]].icon:''} ${hero[1]}` : '');
  el.innerHTML = headHtml + `
    <div class="section-lead" style="padding-top:0;">
      <div class="eyebrow">Helden-Auslosung</div>
      <h2 style="font-size:1.5rem;display:flex;align-items:center;gap:8px;">${gameIconHTML(session.gameId,26)} ${GAME_NAME[session.gameId]}</h2>
      <p style="margin:2px 0 0;color:var(--text-muted);">Wer bekommt wen?${roleLine}</p>
    </div>
    <div class="reel-block">
      <div class="reel-player-name">${player}</div>
      <div class="reel-outer"><div class="reel-viewport reel-idle"><div class="reel-center-marker"></div><div class="reel-track" id="session-reel-track">${buildIdleReelHTML(pool)}</div></div></div>
      <div class="roll-zone" style="margin-top:20px; margin-bottom:0;"><button class="roll-btn" id="session-reel-next">🎰 Start</button></div>
    </div>`;
  const track = document.getElementById('session-reel-track');
  const nextBtn = document.getElementById('session-reel-next');
  let spun = false;
  nextBtn.onclick = ()=>{
    if(!spun){
      spun = true;
      nextBtn.disabled = true; nextBtn.textContent = 'Dreht sich…';
      spinReelTrack(track, pool, hero, 3600, ()=>{
        nextBtn.disabled = false;
        nextBtn.textContent = isLast ? '✅ Weiter zur Runde' : 'Weiter →';
      });
      return;
    }
    session.heroRevealIndex++;
    if(session.heroRevealIndex >= session.players.length) session.heroRevealDone = true;
    saveSession(); renderScoreboard();
  };
}
function renderChallengeToggleList(scope, arr){
  let html = '<div class="sb-challenge-list">';
  sortByDifficulty(arr).forEach(c=>{
    const stateClass = c.state==='win' ? 'won' : c.state==='lose' ? 'lost' : '';
    const chaosClass = c.chaos ? ' chaos' : '';
    const pts = c.state==='win' ? ('+'+c.points) : c.state==='lose' ? ('−'+c.points) : (c.points+' Pkt');
    const buyoutCost = Math.round(c.points * 1.5);
    const canBuyout = scope !== 'team' && c.state === 'pending' && shopBalance(scope) >= buyoutCost;
    html += `<div class="sb-challenge-item ${stateClass}${chaosClass}">
      <div class="sb-diff-badge" style="background:${DIFF_COLOR[c.diff]}">${DIFF_LABEL[c.diff]}</div>
      <div class="sb-challenge-text">${c.text}</div>
      <div class="sb-points">${pts}</div>
      <div class="sb-actions">
        <button data-scope="${scope}" data-cid="${c.id}" data-action="win" class="${c.state==='win'?'active':''}">✅</button>
        <button data-scope="${scope}" data-cid="${c.id}" data-action="lose" class="${c.state==='lose'?'active':''}">❌</button>
        ${canBuyout ? `<button data-buyout-scope="${scope}" data-buyout-cid="${c.id}" data-buyout-cost="${buyoutCost}" title="Für ${buyoutCost} Punkte freikaufen">🪙</button>` : ''}
      </div></div>`;
  });
  html += '</div>'; return html;
}
function renderLeaderboardTable(scored, goal, avatarResolver){
  let html = '<div class="leaderboard">';
  scored.forEach((s,i)=>{
    const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1)+'.';
    const avatarBit = withHatOverlay(s.name, avatarResolver ? avatarResolver(s.name) : avatarHTML(s.name,20), 20);
    const badgeBit = badgeIconHTML(cosmeticsFor(s.name).badge);
    html += `<div class="leaderboard-row ${i===0?'lead':''}">
      <div class="leaderboard-row-main"><div class="lb-rank">${medal}</div><div class="lb-avatar">${avatarBit}</div><div class="lb-name">${badgeBit}${glowNameHTML(s.name,s.name)}</div><div class="lb-score">${s.score} Pkt</div></div>
      ${goal ? miniGoalBar(s.score, goal) : ''}
    </div>`;
  });
  html += '</div>'; return html;
}

function renderScoreboard(){
  const el = document.getElementById('session-scoreboard');
  if(!session){ el.innerHTML = '<div class="session-empty">Keine aktive Session. Startet eine neue über „Spiel starten".</div>'; return; }

  const modeLabel = session.mode==='team' ? '🤝 Team gegen Team' : '⚔️ Jeder gegen Jeden';
  const smLabel = session.sessionMode==='chaos' ? '🌀 Chaos' : '🎯 Challenge';
  const roundBadgeText = session.scope==='games' ? `Spiel ${session.currentGameIndex+1} / ${session.gameSequence.length}` : `Runde ${session.currentRound} / ${session.totalRounds}`;
  let html = `
    <div class="scoreboard-head">
      <div class="scoreboard-info">
        <div class="round-badge">${roundBadgeText}</div>
        <div class="scoreboard-title">${gameIconHTML(session.gameId,22)} ${GAME_NAME[session.gameId]}</div>
        <div class="scoreboard-meta">${modeLabel} · ${smLabel} · ${session.difficultyKey || '—'} · ${session.players.length} Spieler</div>
      </div>
      <div class="scoreboard-actions"><button class="sb-btn" onclick="extendSession()">➕ Verlängerung</button><button class="sb-btn danger" onclick="endSession()">✕ Beenden</button></div>
    </div>`;

  if(session.pendingGameIntro){
    el.innerHTML = html;
    renderGameIntro(el, html);
    return;
  }

  if(session.heroAssignment && !session.heroRevealDone){
    el.innerHTML = html;
    renderSessionHeroReveal(el, html);
    return;
  }

  if(session.mode==='team'){
    html += renderGoalBar((session.cumulativeTeam||0) + scoreOf(session.sharedRules), session.pointGoal);
  } else {
    const bestNow = Math.max(...session.players.map(p=>(session.cumulativePlayers[p]||0) + (session.finished||session.awaitingNextGameChoice ? 0 : scoreOf(session.personalChallenges[p]||[])) + (session.finished||session.awaitingNextGameChoice ? 0 : scoreOf(session.sharedRules||[]))));
    if(session.pointGoal) html += renderGoalBar(bestNow, session.pointGoal);
  }

  function roundScoreSummary(){
    if(session.mode==='team'){
      const roundScore = scoreOf(session.sharedRules);
      const total = (session.cumulativeTeam||0) + roundScore;
      const scored = [{ name: GAME_NAME[session.gameId] || 'Team', score: total }];
      return `<div class="round-badge" style="margin-bottom:12px;">Diese Runde: ${roundScore>=0?'+':''}${roundScore} Punkte</div>` + renderLeaderboardTable(scored, session.pointGoal);
    }
    const sharedScore = scoreOf(session.sharedRules);
    const scored = session.players.map(p=>({name:p, score:(session.cumulativePlayers[p]||0)+scoreOf(session.personalChallenges[p])+sharedScore})).sort((a,b)=>b.score-a.score);
    return `<div class="round-badge" style="margin-bottom:12px;">Diese Runde</div>` + renderLeaderboardTable(scored, session.pointGoal);
  }
  function currentRoundTopPlayerName(){
    if(session.mode==='team') return null;
    const sharedScore = scoreOf(session.sharedRules);
    const scored = session.players.map(p=>({name:p, score:(session.cumulativePlayers[p]||0)+scoreOf(session.personalChallenges[p])+sharedScore})).sort((a,b)=>b.score-a.score);
    return scored.length ? scored[0].name : null;
  }

  if(session.finished){
    html += `<div class="final-summary"><div class="big-emoji confetti-burst" id="local-done-confetti">🏁</div><h3>Session beendet</h3><p style="color:var(--text-muted);">${session.currentRound} Runde${session.currentRound>1?'n':''} gespielt</p></div>`;
    html += session.lastActionSkipped ? `<div class="rules-note">🚫 Letzte Runde übersprungen — keine Punkte gezählt.</div>` : roundScoreSummary();
    let finishedTopName = null;
    let finalScore = 0;
    if(session.mode==='team'){ finalScore = session.cumulativeTeam||0; html += `<div class="score-total">Endstand: <span>${session.cumulativeTeam}</span> Punkte</div>`; }
    else { const scored = session.players.map(p=>({name:p, score:session.cumulativePlayers[p]||0})).sort((a,b)=>b.score-a.score); html += renderLeaderboardTable(scored, null); finishedTopName = scored.length ? scored[0].name : null; finalScore = scored.length ? scored[0].score : 0; }
    html += skippedGamesChipsHTML();
    html += `<div class="round-prompt-actions"><button class="round-prompt-btn primary" onclick="newSessionFromScoreboard()">🚀 Neue Session</button></div>`;
    el.innerHTML = html; animateMiniGoalBars(el);
    const finKey = 'finished_'+session.currentRound;
    if(localCelebratedKey !== finKey){ localCelebratedKey = finKey; if(finalScore > 0) setTimeout(()=>spawnConfetti('local-done-confetti', finishedTopName), 0); }
    return;
  }

  if(session.awaitingNextGameChoice){
    const roundStatusBlock = session.lastActionSkipped ? `<div class="rules-note">🚫 Übersprungen — keine Punkte gezählt.</div>` : roundScoreSummary();
    if(session.scope === 'games'){
      const nextId = session.gameSequence[session.currentGameIndex+1];
      html += `<div class="round-prompt">
        <h3>${session.lastActionSkipped?'Spiel übersprungen':'Runde '+session.currentRound+' beendet!'} <span>${session.lastActionSkipped?'🚫':'🎉'}</span></h3>
        ${roundStatusBlock}
        <p>Weiter geht's mit ${gameIconHTML(nextId,18)} ${GAME_NAME[nextId]} (Spiel ${session.currentGameIndex+2} von ${session.gameSequence.length}).</p>
        ${skippedGamesChipsHTML()}
        <div class="round-prompt-actions"><button class="round-prompt-btn primary" onclick="advanceGameSequence()">▶️ Weiter</button></div>
      </div>`;
    } else {
      const otherGames = SESSION_GAMES.filter(id=> id!==session.gameId && allowedModesFor(id).includes(session.mode));
      html += `<div class="round-prompt">
        <h3>${session.lastActionSkipped?'Übersprungen':'Runde '+session.currentRound+' beendet!'} <span>${session.lastActionSkipped?'🚫':'🎉'}</span></h3>
        ${roundStatusBlock}
        <p>Noch ${session.totalRounds - session.currentRound} Runde${(session.totalRounds - session.currentRound)>1?'n':''} übrig. Weiterspielen mit demselben Spiel oder ein anderes wählen?</p>
        <div class="round-prompt-actions">
          <button class="round-prompt-btn primary" onclick="chooseSameGame()">🔁 Gleiches Spiel</button>
          <button class="round-prompt-btn" onclick="toggleGamePicker()">🔀 Anderes Spiel</button>
        </div>
        <div id="inline-game-picker" style="display:none; margin-top:14px;">
          <div class="filter-row">${otherGames.map(id=>`<button class="filter-pill" onclick="continueSessionWithGame('${id}')">${gameIconHTML(id,18)} ${GAME_NAME[id]}</button>`).join('')}</div>
        </div>
      </div>`;
    }
    el.innerHTML = html; animateMiniGoalBars(el);
    // Kein Konfetti/Feuerwerk zwischen einzelnen Runden — das soll es nur beim wirklichen
    // Abschluss der gesamten Session geben (siehe "local-done-confetti" oben bei session.finished).
    return;
  }

  if(session.mode === 'team'){
    if(session.heroAssignment) html += renderHeroRow(Object.entries(session.heroAssignment), null, session.gameId);
    const liveTotal = (session.cumulativeTeam||0) + scoreOf(session.sharedRules);
    html += `<div class="score-total">Gesamt-Punkte: <span>${liveTotal}</span></div>`;
    html += `<div class="score-sub">Davor gesammelt: ${session.cumulativeTeam||0} Pkt · diese Runde: ${scoreOf(session.sharedRules)} Pkt</div>`;
    html += `<div class="challenges-label">📜 Spielregeln</div>`;
    html += renderChallengeToggleList('team', session.sharedRules);
    html += `<div class="roll-zone" style="margin-top:24px;gap:8px;flex-wrap:wrap;"><button class="roll-btn" onclick="endRound()">🏁 Runde beenden</button><button class="sb-btn" onclick="skipRound()">🚫 Überspringen</button></div>`;
  } else {
    const sharedScore = scoreOf(session.sharedRules);
    const scored = session.players.map(p=>({name:p, score:(session.cumulativePlayers[p]||0) + scoreOf(session.personalChallenges[p]) + sharedScore})).sort((a,b)=>b.score-a.score);
    html += renderLeaderboardTable(scored, session.pointGoal);
    html += `<div class="challenges-label">📜 Spielregeln (gelten für alle)</div>`;
    html += `<div class="rules-note">Diese Punkte werden allen Spielern gleichermaßen gutgeschrieben.</div>`;
    html += session.votingPhase ? renderChallengeToggleList('team', session.sharedRules) : renderChallengeListPlain(session.sharedRules);
    html += `<div class="section-divider">🎯 Persönliche Challenges</div>`;

    if(session.votingPhase){
      html += `<div class="rules-note">🗳️ Jetzt gemeinsam bewerten — alle sehen alle Challenges.</div>`;
      session.players.forEach(p=>{
        const live = (session.cumulativePlayers[p]||0) + scoreOf(session.personalChallenges[p]) + sharedScore;
        html += `<div class="player-block-label">${playerCosmeticCardHTML(p, withHatOverlay(p, avatarHTML(p,20), 20))}<span>${live} Pkt</span></div>`;
        if(session.heroAssignment) html += renderHeroRow([[p, session.heroAssignment[p]]], null, session.gameId);
        html += renderChallengeToggleList(p, session.personalChallenges[p]);
      });
      html += `<div class="roll-zone" style="margin-top:24px;gap:8px;flex-wrap:wrap;"><button class="roll-btn" onclick="endRound()">🏁 Runde abschließen</button><button class="sb-btn" onclick="skipRound()">🚫 Überspringen</button></div>`;
    } else {
      html += `<div class="rules-note">🔒 Jeder sieht nur die eigene Challenge — anzeigen, merken, verbergen, Handy weitergeben.</div>`;
      session.players.forEach(p=>{
        const revealed = session.revealedPlayer === p;
        const safeName = p.replace(/'/g, "\\'");
        html += `<div class="player-block-label">${playerCosmeticCardHTML(p, withHatOverlay(p, avatarHTML(p,20), 20))}</div>`;
        if(session.heroAssignment) html += renderHeroRow([[p, session.heroAssignment[p]]], null, session.gameId);
        if(revealed){
          html += renderChallengeListPlain(session.personalChallenges[p]);
          html += `<div class="roll-zone" style="margin:8px 0 22px;"><button class="sb-btn" onclick="toggleReveal('${safeName}')">🙈 Verbergen</button></div>`;
        } else {
          html += `<div class="empty-hint" style="padding:16px;">🔒 Verborgen</div>`;
          html += `<div class="roll-zone" style="margin:8px 0 22px;"><button class="sb-btn" onclick="toggleReveal('${safeName}')">👁️ Nur für ${p} anzeigen</button></div>`;
        }
      });
      html += `<div class="roll-zone" style="margin-top:24px;gap:8px;flex-wrap:wrap;"><button class="roll-btn" onclick="enterVotingPhase()">🏁 Runde beenden & gemeinsam bewerten</button><button class="sb-btn" onclick="skipRound()">🚫 Überspringen</button></div>`;
    }
  }

  el.innerHTML = html;
  animateMiniGoalBars(el);
}

function renderChallengeListPlain(arr){
  let html = '<div class="sb-challenge-list">';
  sortByDifficulty(arr).forEach(c=>{
    html += `<div class="sb-challenge-item${c.struck?' struck':''}">
      <div class="sb-diff-badge" style="background:${DIFF_COLOR[c.diff]}">${DIFF_LABEL[c.diff]}</div>
      <div class="sb-challenge-text">${c.text}</div>
      <div class="sb-points">${c.struck?'🗑️ gestrichen · ':''}${c.points} Pkt</div>
    </div>`;
  });
  html += '</div>';
  return html;
}
let localCelebratedKey = null; // verhindert, dass die Gewinn-Animation bei jedem Re-Render erneut abspielt
function toggleReveal(playerName){
  session.revealedPlayer = session.revealedPlayer === playerName ? null : playerName;
  saveSession(); renderScoreboard();
}
function enterVotingPhase(){
  session.votingPhase = true; session.revealedPlayer = null;
  saveSession(); renderScoreboard();
}

function toggleChallenge(scope, cid, action){
  const arr = scope === 'team' ? session.sharedRules : session.personalChallenges[scope];
  const item = arr.find(c=>c.id===cid); if(!item) return;
  item.state = item.state === action ? 'pending' : action;
  saveSession(); renderScoreboard();
}
async function buyoutChallenge(playerName, cid, cost){
  if(shopBalance(playerName) < cost) return;
  if(!(await confirmAction(`${cost} Punkte ausgeben, um diese Challenge automatisch als erledigt zu markieren?`))) return;
  const s = statsStore[playerName]; if(!s) return;
  addCoins(playerName, -cost);
  saveStats();
  toggleChallenge(playerName, cid, 'win');
}
document.getElementById('session-scoreboard').addEventListener('click', e=>{
  const buyBtn = e.target.closest('button[data-buyout-cid]');
  if(buyBtn){ buyoutChallenge(buyBtn.dataset.buyoutScope, buyBtn.dataset.buyoutCid, parseInt(buyBtn.dataset.buyoutCost, 10)); return; }
  const btn = e.target.closest('button[data-cid]'); if(!btn) return;
  toggleChallenge(btn.dataset.scope, btn.dataset.cid, btn.dataset.action);
});

/* ============================================================ HERO RANDOMIZER (Free Play) ============================================================ */
function heroItemAvatarHTML(name){
  const bg = heroImageCache[name] ? '#000' : heroColor(name);
  return `<div class="reel-item-avatar" style="background:${bg}; overflow:hidden;">${heroAvatarInner(name)}</div>`;
}
function buildIdleReelHTML(pool){
  const items = []; for(let k=0;k<9;k++){ items.push(pool[randInt(0,pool.length-1)]); }
  return items.map(([name])=>`<div class="reel-item">${heroItemAvatarHTML(name)}<div class="reel-item-name">${name}</div></div>`).join('');
}
function buildReelTrackHTML(items, targetIndex){
  return items.map(([name], i)=>`<div class="reel-item${i===targetIndex?' reel-item-target':''}">${heroItemAvatarHTML(name)}<div class="reel-item-name">${name}</div></div>`).join('');
}
/* Spins a reel track to land the target hero centered in the viewport, always keeping a
   trail of extra (random) heroes visible after it so it reads as an endless strip rather
   than stopping on the last card. */
function spinReelTrack(track, pool, target, duration, onDone){
  try{
    const viewport = track && track.parentElement;
    if(!track || !viewport) throw new Error('reel track not attached to DOM yet');
    viewport.classList.remove('reel-idle');
    const leadCount = 26, trailCount = 6;
    const filler = []; for(let k=0;k<leadCount;k++){ filler.push(pool[randInt(0,pool.length-1)]); }
    const targetIndex = filler.length;
    filler.push(target);
    for(let k=0;k<trailCount;k++){ filler.push(pool[randInt(0,pool.length-1)]); }
    track.innerHTML = buildReelTrackHTML(filler, targetIndex);
    track.style.transition = 'none';
    track.style.transform = 'translateX(0px)';
    const itemW = 120;
    const viewportWidth = viewport.getBoundingClientRect().width || 400;
    const finalX = viewportWidth/2 - (targetIndex*itemW + itemW/2);
    let done = false;
    const finish = ()=>{
      if(done) return; done = true;
      track.style.transform = `translateX(${finalX}px)`;
      const landed = track.querySelector('.reel-item-target');
      if(landed) landed.classList.add('reel-item-landed');
      onDone();
    };
    if(typeof track.animate === 'function'){
      // Web Animations API — explicit start/end keyframes, doesn't depend on the browser
      // "seeing" an intermediate style change like CSS-transition timing does, so it starts
      // reliably even on mobile WebViews where the transition-after-reflow trick sometimes
      // silently fails to animate at all.
      const anim = track.animate(
        [{ transform: 'translateX(0px)' }, { transform: `translateX(${finalX}px)` }],
        { duration, easing: 'cubic-bezier(.1,.82,.15,1)', fill: 'forwards' }
      );
      anim.onfinish = finish;
      anim.oncancel = finish;
      setTimeout(finish, duration + 300); // safety net in case onfinish never fires
    } else {
      void track.offsetWidth;
      requestAnimationFrame(()=>{
        track.style.transition = `transform ${duration}ms cubic-bezier(.1,.82,.15,1)`;
        track.style.transform = `translateX(${finalX}px)`;
      });
      setTimeout(finish, duration + 60);
    }
  }catch(err){
    console.error('Roulette-Fehler (spinReelTrack):', err);
    if(onDone) onDone();
  }
}
function runPlayerHeroReel(prefix, pool, heroWrap, onAllDone){
  const players = globalPlayers.slice();
  const shuffledPool = shuffle(pool);
  const assigned = players.map((p,i)=>shuffledPool[i % shuffledPool.length]);
  const results = [];
  let idx = 0;

  heroWrap.innerHTML = `<div class="reel-block">
    <div class="reel-player-name" id="${prefix}-reel-player"></div>
    <div class="reel-outer"><div class="reel-viewport reel-idle"><div class="reel-center-marker"></div><div class="reel-track" id="${prefix}-reel-track">${buildIdleReelHTML(pool)}</div></div></div>
    <div class="roll-zone" style="margin-top:20px; margin-bottom:0;"><button class="roll-btn" id="${prefix}-reel-next" disabled>Dreht sich…</button></div>
  </div>`;
  const nextBtn = document.getElementById(prefix+'-reel-next');

  function spinFor(i){
    const target = assigned[i];
    document.getElementById(prefix+'-reel-player').textContent = players[i];
    nextBtn.disabled = true; nextBtn.textContent = 'Dreht sich…';
    const track = document.getElementById(prefix+'-reel-track');
    spinReelTrack(track, pool, target, 3400, ()=>{
      results.push([players[i], target]);
      nextBtn.disabled = false;
      nextBtn.textContent = (i === players.length-1) ? '✅ Fertig' : 'Weiter →';
    });
  }

  nextBtn.addEventListener('click', function handler(){
    idx++;
    if(idx < players.length){ spinFor(idx); }
    else { nextBtn.removeEventListener('click', handler); onAllDone(results); }
  });
  spinFor(0);
}
function finalizeSoloReel(heroWrap, challWrap, results, challengePool, challengeRange, challengeLabel, gameId){
  const list = document.createElement('div'); list.className = 'solo-hero-list reel-done-list';
  results.forEach(([playerName, heroEntry], i)=>{
    const [heroName, role] = heroEntry; const meta = ROLE_META[role]; const bg = heroImageFor(gameId,heroName) ? '#000' : heroColor(heroName);
    const avatarBit = withHatOverlay(playerName, avatarHTML(playerName,18), 18);
    const playerCard = playerCosmeticCardHTML(playerName, avatarBit);
    const item = document.createElement('div'); item.className = 'solo-hero-item'; item.style.animationDelay = (i*0.06)+'s';
    item.innerHTML = `<div class="solo-player">${playerCard}</div>
      <div class="solo-hero-body">
        <div class="solo-avatar" style="background:${bg}; overflow:hidden;">${heroAvatarInner(heroName,gameId)}<span class="avatar-badge" style="background:${meta.color}">${meta.icon}</span></div>
        <div class="solo-hero">${heroName}</div>
        <div class="solo-role" style="background:${meta.color}">${role}</div>
      </div>`;
    list.appendChild(item);
  });
  heroWrap.innerHTML = '';
  heroWrap.appendChild(list);
  const challenges = pickNUnique(challengePool, randInt(challengeRange[0], challengeRange[1]));
  renderChallengeList(challWrap, challenges, challengeLabel);
}
function setupHeroRandomizer(prefix, heroes, roles, challengePool, challengeRange, challengeLabel){
  const rollBtnGuard = document.getElementById(prefix+'-roll');
  // Harter Schutz gegen Doppel-Initialisierung: selbst wenn diese Funktion aus Versehen zweimal für
  // dasselbe Spiel aufgerufen wird, hängt sich nie ein zweiter Klick-Handler an denselben Button —
  // genau das hat vorher die Rollen-/Modus-Auswahl beim Auslosen durcheinandergebracht.
  if(rollBtnGuard && rollBtnGuard.dataset.wired === '1') return;
  if(rollBtnGuard) rollBtnGuard.dataset.wired = '1';
  const filterRow = document.getElementById(prefix+'-filters');
  // Idempotent: falls die Initialisierung mehrfach läuft (z.B. Dokument versehentlich doppelt
  // deployed), werden die Reihen vorher geleert statt doppelt befüllt.
  if(filterRow) filterRow.innerHTML = '';
  const _modeRowClear = document.getElementById(prefix+'-modes');
  if(_modeRowClear) _modeRowClear.innerHTML = '';
  const labels = { all:'Alle' }; roles.forEach(r=>{ labels[r]=r; });
  // Rainbow Six benötigt vor dem Start zwingend eine Seite. Dadurch können
  // im Roulette ausschließlich Angreifer ODER Verteidiger auftauchen.
  const requiresR6Side = prefix === 'r6';
  let activeRole = requiresR6Side ? null : 'all';
  (requiresR6Side ? roles : ['all', ...roles]).forEach(r=>{
    const btn = document.createElement('button'); btn.className = 'filter-pill'+(r===activeRole?' active':''); btn.textContent = labels[r];
    btn.addEventListener('click', ()=>{ activeRole = r; filterRow.querySelectorAll('.filter-pill').forEach(p=>p.classList.remove('active')); btn.classList.add('active'); });
    filterRow.appendChild(btn);
  });
  const modeRow = document.getElementById(prefix+'-modes'); let mode = 'team';
  [{id:'team', label:'🎯 Team'}, {id:'solo', label:'👥 Jeder einzeln'}].forEach(m=>{
    const btn = document.createElement('button'); btn.className = 'mode-pill'+(m.id==='team'?' active':''); btn.textContent = m.label;
    btn.addEventListener('click', ()=>{ mode = m.id; modeRow.querySelectorAll('.mode-pill').forEach(p=>p.classList.remove('active')); btn.classList.add('active'); });
    modeRow.appendChild(btn);
  });
  const rollBtn = document.getElementById(prefix+'-roll'); const heroWrap = document.getElementById(prefix+'-hero'); const challWrap = document.getElementById(prefix+'-challenges');
  rollBtn.addEventListener('click', ()=>{
    if(rollBtn.disabled) return;
    try{
      if(requiresR6Side && !activeRole){
        heroWrap.innerHTML = '<div class="empty-hint">Wählt zuerst <strong>Angriff</strong> oder <strong>Verteidigung</strong>.</div>';
        challWrap.innerHTML = ''; return;
      }
      const pool = activeRole==='all' ? heroes : heroes.filter(h=>h[1]===activeRole);
      if(!pool.length) return;
      if(mode === 'solo' && !globalPlayers.length){
        heroWrap.innerHTML = `<div class="empty-hint">Für den Einzel-Modus braucht ihr zuerst angemeldete Spieler.<button class="empty-hint-link" onclick="showView('players')">👥 Spieler verwalten</button></div>`;
        challWrap.innerHTML = ''; return;
      }
      if(mode === 'team'){
        rollBtn.disabled = true; rollBtn.classList.add('rolling');
        challWrap.innerHTML = '';
        const target = pool[randInt(0,pool.length-1)];
        heroWrap.innerHTML = `<div class="reel-block"><div class="reel-outer"><div class="reel-viewport"><div class="reel-center-marker"></div><div class="reel-track" id="${prefix}-team-reel-track"></div></div></div></div>`;
        const track = document.getElementById(prefix+'-team-reel-track');
        // Sicherheitsnetz: egal was passiert, der Button darf nie dauerhaft blockiert bleiben.
        const safety = setTimeout(()=>{ rollBtn.disabled = false; rollBtn.classList.remove('rolling'); }, 4500);
        spinReelTrack(track, pool, target, 3400, ()=>{
          clearTimeout(safety);
          try{
            const [name, role] = target; const meta = ROLE_META[role]; const bg = heroColor(name);
            heroWrap.innerHTML = `<div class="hero-card" style="--card-accent:${meta.color}"><div class="hero-card-inner">
              <div class="hero-avatar" style="background:${heroImageFor(prefix,name)?'#000':bg}; overflow:hidden;">${heroAvatarInner(name,prefix)}<span class="avatar-badge" style="background:${meta.color}">${meta.icon}</span></div>
              <div class="hero-name">${name}</div><div class="role-pill">${meta.icon} ${role}</div></div></div>`;
            requestAnimationFrame(()=>{ const c = heroWrap.querySelector('.hero-card'); if(c) c.classList.add('show'); });
            const challenges = pickNUnique(challengePool, randInt(challengeRange[0], challengeRange[1]));
            renderChallengeList(challWrap, challenges, challengeLabel);
          }catch(revealErr){
            console.error('Hero-Reveal Fehler:', revealErr);
            heroWrap.innerHTML = `<div class="empty-hint">Anzeige fehlgeschlagen — tippt einfach nochmal.</div>`;
          }
          rollBtn.disabled = false; rollBtn.classList.remove('rolling');
        });
      } else {
        rollBtn.disabled = true; rollBtn.classList.add('rolling');
        challWrap.innerHTML = '';
        const safety = setTimeout(()=>{ rollBtn.disabled = false; rollBtn.classList.remove('rolling'); }, (globalPlayers.length*3600)+4500);
        runPlayerHeroReel(prefix, pool, heroWrap, (results)=>{
          clearTimeout(safety);
          try{ finalizeSoloReel(heroWrap, challWrap, results, challengePool, challengeRange, challengeLabel, prefix); }
          catch(revealErr){ console.error('Hero-Reveal Fehler:', revealErr); heroWrap.innerHTML = `<div class="empty-hint">Anzeige fehlgeschlagen — tippt einfach nochmal.</div>`; }
          rollBtn.disabled = false; rollBtn.classList.remove('rolling');
        });
      }
    }catch(err){
      console.error('Hero-Roulette Fehler:', err);
      rollBtn.disabled = false; rollBtn.classList.remove('rolling');
      heroWrap.innerHTML = `<div class="empty-hint">Etwas ist schiefgelaufen — tippt einfach nochmal.</div>`;
    }
  });
}

