try{ setupHeroRandomizer('mr', MR_HEROES, Object.keys(ROLE_WEIGHTS.mr), MR_CHALLENGES, [3,5], 'Team-Challenges'); }catch(e){ console.error('mr Roulette-Setup Fehler:', e); }
