try{ setupHeroRandomizer('finals', FINALS_CLASSES, Object.keys(ROLE_WEIGHTS.finals), FINALS_CHALLENGES, [3,5], 'Team-Challenges'); }catch(e){ console.error('finals Roulette-Setup Fehler:', e); }
