function checkPasswordRecoveryRedirect(){
  if(window.location.hash.indexOf('type=recovery') !== -1){
    showView('reset-password');
    return true;
  }
  return false;
}
document.getElementById('reset-password-submit').addEventListener('click', async ()=>{
  const errEl = document.getElementById('reset-password-error');
  const pw = document.getElementById('reset-password-input').value;
  errEl.textContent = '';
  if(!sb){ errEl.textContent = 'Verbindung zum Server nicht verfügbar.'; return; }
  if(pw.length < 6){ errEl.textContent = 'Passwort muss mindestens 6 Zeichen haben.'; return; }
  const { error } = await sb.auth.updateUser({ password: pw });
  if(error){ errEl.textContent = 'Fehler: ' + error.message; return; }
  errEl.style.color = 'var(--win)';
  errEl.textContent = 'Passwort geändert! Ihr seid jetzt eingeloggt.';
  const { data:{ user } } = await sb.auth.getUser();
  if(user){ await loadProfile(user.id); await restoreMyTeam(); renderAuthBar(); }
  setTimeout(()=>showHome(), 1200);
});

async function loadCustomGamesFromCloud(){
  if(!sb) return;
  try{
    const {data,error}=await sb.from('custom_games').select('*').order('created_at',{ascending:true});
    if(error){ console.warn('Eigene Spiele konnten nicht geladen werden:',error.message); return; }
    (data||[]).forEach(g=>{
      if(GAME_NAME[g.id]) return; // schon bekannt (Standard-Spiel oder schon geladen)
      const gameObj={ id:g.id, icon:g.icon||'🎮', watermark:g.icon||'🎮', name:g.name, tag:g.tag||'', grad:g.grad||'linear-gradient(135deg,#241a3a,#0d3b3a)', maxPlayers:g.max_players||10 };
      GAMES.push(gameObj);
      SESSION_GAMES.push(g.id);
      GAME_NAME[g.id]=g.name; GAME_ICON[g.id]=g.icon||'🎮';
      if(!CHALLENGE_SOURCES[g.id]) CHALLENGE_SOURCES[g.id]=[];
      if(!PERSONAL_SOURCES[g.id]) PERSONAL_SOURCES[g.id]=[];
    });
  }catch(e){ console.warn('Eigene Spiele konnten nicht geladen werden:',e); }
}
