(function(){
  const baseUseSabotage = useSabotageItem;
  async function consumeMiniCard(id){
    const s = statsStore[currentUser.username];
    s.shopOwned.sabotage[id] = Math.max(0,(s.shopOwned.sabotage[id]||0)-1);
    sabotageLoadout[id] = Math.max(0,(sabotageLoadout[id]||0)-1);
    saveLoadout(); saveStats();
  }
  async function refreshMiniCard(){ await loadRoundItems(); renderTeamPage(); }
  // Ein echtes Gruppen-Minispiel: Alle verbundenen Mitglieder sehen dasselbe Signal.
  // Der Starter sammelt die Klickzeiten ein und sendet anschließend das gemeinsame Ergebnis.
  const reactionDuelReadySessions = {};
  function showReactionDuelInvite(payload){
    if(!payload || reactionDuelReadySessions[payload.id]) return;
    const total = Math.max(1, (teamMembers||[]).length);
    const session = reactionDuelReadySessions[payload.id] = {payload, readyIds:new Set(), myReady:false};
    let modal=document.getElementById('reaction-duel-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='reaction-duel-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
    const renderInvite=()=>{
      modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:500px;text-align:center;">
        <div style="font-size:4rem;line-height:1;filter:drop-shadow(0 0 18px #facc15)">⚡</div>
        <div class="setup-step-title" style="margin:10px 0 6px;">Reaktionsduell</div>
        <p class="setup-info" style="margin:0 0 18px;">${payload.ownerName} schlägt ein Reaktionsduell vor. Klickt „Bereit", sobald ihr mitmachen wollt — das Signal kommt erst, wenn alle bereit sind.</p>
        <button id="reaction-duel-ready-btn" class="roll-btn" style="min-width:220px;">${session.myReady?'✅ Bereit — warte auf andere …':'✅ Bereit'}</button>
        <p class="setup-info" style="margin:14px 0 0;font-size:.78rem;">${session.readyIds.size}/${total} bereit</p>
      </div>`;
      const btn=modal.querySelector('#reaction-duel-ready-btn');
      if(session.myReady){ btn.disabled=true; btn.style.opacity='.6'; btn.style.cursor='wait'; }
      else btn.onclick=()=>{
        session.myReady=true; session.readyIds.add(currentUser.id);
        window.receiveReactionDuelReady({id:payload.id,userId:currentUser.id});
        if(teamChannel) teamChannel.send({type:'broadcast',event:'reaction-duel-ready',payload:{id:payload.id,userId:currentUser.id}}).catch(()=>{});
        renderInvite();
      };
    };
    renderInvite();
    modal.classList.remove('hidden');
    session.renderInvite=renderInvite;
  }
  window.receiveReactionDuelInvite = showReactionDuelInvite;
  window.receiveReactionDuelReady = function(ready){
    const session=ready&&reactionDuelReadySessions[ready.id];
    if(!session || session.started) return;
    session.readyIds.add(ready.userId);
    if(session.renderInvite && document.getElementById('reaction-duel-modal')) session.renderInvite();
    const total = Math.max(1, (teamMembers||[]).length);
    if(session.payload.ownerId===currentUser.id && session.readyIds.size>=total){
      session.started=true;
      const startPayload={id:session.payload.id,ownerId:session.payload.ownerId,ownerName:session.payload.ownerName,startAt:Date.now()+900};
      showGroupReactionDuel(startPayload);
      if(teamChannel) teamChannel.send({type:'broadcast',event:'reaction-duel-start',payload:startPayload}).catch(()=>{});
    }
  };
  const reactionDuelSessions = {};
  function myOpenLightChallenge(){ return roundItems.find(it=>it.scope==='personal' && it.user_id===currentUser.id && !it.result && it.diff==='leicht'); }
  function showGroupReactionDuel(payload){
    if(!payload || reactionDuelSessions[payload.id]) return;
    const session = reactionDuelSessions[payload.id] = {payload, clicks:[], done:false};
    let modal=document.getElementById('reaction-duel-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='reaction-duel-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
    modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:500px;text-align:center;">
      <div style="font-size:4rem;line-height:1;filter:drop-shadow(0 0 18px #facc15)">⚡</div>
      <div class="setup-step-title" style="margin:10px 0 6px;">Reaktionsduell</div>
      <p id="reaction-duel-text" class="setup-info" style="margin:0 0 18px;">${payload.ownerName} hat ein Reaktionsduell gestartet. Warte auf das Neon-Signal!</p>
      <button id="reaction-duel-go" class="roll-btn" disabled style="min-width:220px;opacity:.45;cursor:wait;">WARTEN …</button>
      <p class="setup-info" style="margin:14px 0 0;font-size:.78rem;">Der schnellste Klick kassiert Punkte von allen anderen Mitspielern.</p>
    </div>`;
    modal.classList.remove('hidden');
    const go=modal.querySelector('#reaction-duel-go'), text=modal.querySelector('#reaction-duel-text');
    const wait=Math.max(0,payload.startAt-Date.now());
    window.setTimeout(()=>{
      if(session.done) return;
      session.signalAt=performance.now(); text.textContent='JETZT! Klick so schnell du kannst.';
      go.disabled=false; go.textContent='⚡ JETZT KLICKEN'; go.style.opacity='1'; go.style.cursor='pointer';
      go.style.boxShadow='0 0 26px rgba(34,211,209,.9),0 0 48px rgba(168,85,247,.55)';
      go.onclick=()=>{
        if(session.clicked || session.done) return;
        session.clicked=true; go.disabled=true; go.textContent='KLICK GESENDET …';
        const click={id:payload.id,userId:currentUser.id,username:currentUser.username,ms:Math.max(0,Math.round(performance.now()-session.signalAt))};
        window.receiveReactionDuelClick(click);
        if(teamChannel) teamChannel.send({type:'broadcast',event:'reaction-duel-click',payload:click}).catch(()=>{});
      };
    },wait);
    // Nur der Startende wertet aus, damit alle Geräte dasselbe Ergebnis erhalten.
    window.setTimeout(()=>{
      if(session.done || payload.ownerId!==currentUser.id) return;
      const winner=[...session.clicks].sort((a,b)=>a.ms-b.ms)[0];
      const participantIds=session.clicks.map(c=>c.userId);
      const result={id:payload.id,winnerId:winner?.userId||null,winnerName:winner?.username||'',ms:winner?.ms||null,participantIds};
      window.receiveReactionDuelResult(result);
      if(teamChannel) teamChannel.send({type:'broadcast',event:'reaction-duel-result',payload:result}).catch(()=>{});
    },wait+1450);
  }
  window.receiveReactionDuelStart = showGroupReactionDuel;
  window.receiveReactionDuelClick = function(click){
    const session=click&&reactionDuelSessions[click.id];
    if(!session || session.done || session.clicks.some(x=>x.userId===click.userId)) return;
    session.clicks.push(click);
  };
  window.receiveReactionDuelResult = async function(result){
    const session=result&&reactionDuelSessions[result.id];
    if(!session || session.done) return;
    session.done=true;
    const modal=document.getElementById('reaction-duel-modal');
    if(modal) modal.classList.add('hidden');
    if(!result.winnerId){ showToast('Reaktionsduell: Niemand hat rechtzeitig geklickt.','⚡'); return; }
    const stolenEach=5;
    const losers=(result.participantIds||[]).filter(id=>id!==result.winnerId);
    const totalStolen=stolenEach*losers.length;
    if(result.winnerId===currentUser.id){
      if(currentRound && sb && totalStolen>0){
        const rows=[
          {round_id:currentRound.id,user_id:currentUser.id,scope:'personal',text:`⚡ Reaktionsduell gewonnen: +${totalStolen} Punkte`,diff:'leicht',points:totalStolen,result:'success',struck:true},
          ...losers.map(id=>({round_id:currentRound.id,user_id:id,scope:'personal',text:`⚡ Reaktionsduell verloren: −${stolenEach} Punkte`,diff:'leicht',points:stolenEach,result:'fail',struck:true})),
        ];
        const {error}=await sb.from('round_items').insert(rows);
        if(!error){ const s=statsStore[currentUser.username]; s.minigamesWon=(s.minigamesWon||0)+1; saveStats(); notifyNewAchievements(checkAchievements(currentUser.username)); await refreshMiniCard(); }
      }
      showToast(`Du gewinnst das Reaktionsduell (${result.ms} ms)! +${totalStolen} Punkte von den anderen.`,'⚡');
    } else if((result.participantIds||[]).includes(currentUser.id)){
      showToast(`${result.winnerName} gewinnt das Reaktionsduell (${result.ms} ms) und kassiert ${stolenEach} Punkte von dir.`,'⚡');
    } else showToast(`${result.winnerName} gewinnt das Reaktionsduell (${result.ms} ms).`,'⚡');
  };
  async function runGroupReactionDuel(){
    const payload={id:'rd-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),ownerId:currentUser.id,ownerName:currentUser.username};
    showReactionDuelInvite(payload);
    if(teamChannel) teamChannel.send({type:'broadcast',event:'reaction-duel-invite',payload}).catch(()=>{});
    return true;
  }
  async function runReactionDuel(){
    const light = roundItems.find(it=>it.scope==='personal' && it.user_id===currentUser.id && !it.result && it.diff==='leicht');
    if(!light){ showAlert('Für das Reaktionsduell brauchst du eine offene leichte Challenge.','⚡'); return false; }
    const reaction = await new Promise(resolve=>{
      let modal=document.getElementById('reaction-duel-modal');
      if(!modal){ modal=document.createElement('div'); modal.id='reaction-duel-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
      let active=false, startedAt=0, timer=null, finished=false;
      const finish=(value)=>{ if(finished) return; finished=true; if(timer) clearTimeout(timer); modal.classList.add('hidden'); resolve(value); };
      modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:500px;text-align:center;">
        <button class="member-modal-close" id="reaction-duel-cancel">✕</button>
        <div style="font-size:4rem;line-height:1;filter:drop-shadow(0 0 18px #facc15)">⚡</div>
        <div class="setup-step-title" style="margin:10px 0 6px;">Reaktionsduell</div>
        <p id="reaction-duel-text" class="setup-info" style="margin:0 0 18px;">Warte auf das Neon-Signal. Erst dann klicken!</p>
        <button id="reaction-duel-go" class="roll-btn" disabled style="min-width:220px;opacity:.45;cursor:wait;">WARTEN …</button>
        <p class="setup-info" style="margin:14px 0 0;font-size:.78rem;">Gewinn: „${light.text}" wird als geschafft gewertet.</p>
      </div>`;
      modal.classList.remove('hidden');
      modal.querySelector('#reaction-duel-cancel').onclick=()=>finish(null);
      const go=modal.querySelector('#reaction-duel-go');
      const text=modal.querySelector('#reaction-duel-text');
      go.onclick=()=>{ if(!active) return; finish(performance.now()-startedAt); };
      timer=window.setTimeout(()=>{
        active=true; startedAt=performance.now();
        text.textContent='JETZT! Klick so schnell du kannst.';
        go.disabled=false; go.textContent='⚡ JETZT KLICKEN'; go.style.opacity='1'; go.style.cursor='pointer';
        go.style.boxShadow='0 0 26px rgba(34,211,209,.9),0 0 48px rgba(168,85,247,.55)';
      },1300+Math.floor(Math.random()*1700));
    });
    if(reaction===null) return false;
    if(reaction>1150){ showAlert(`Knapp zu spät (${Math.round(reaction)} ms) – keine Challenge wurde gestrichen.`,'⚡'); return false; }
    const {error} = await sb.from('round_items').update({result:'success',points:0,struck:true}).eq('id',light.id);
    if(error){ showAlert('Reaktionsduell konnte nicht gespeichert werden: '+error.message); return false; }
    showToast(`Reaktionsduell gewonnen (${Math.round(reaction)} ms): eine leichte Challenge wurde gestrichen.`,'⚡'); return true;
  }
  // Zahlenraten ist ein gemeinsames Minispiel: Der Starter legt nur die Runde an.
  // Erst wenn jede/r Teilnehmer/in eine Zahl gewählt hat, wird die geheime Zahl aufgedeckt.
  const numberGuessSessions = {};
  function groupNumberGuessMembers(){
    const left=new Set(currentRound?.left_players||[]);
    return teamMembers.filter(m=>!left.has(m.user_id)).map(m=>m.user_id);
  }
  function numberGuessReward(correctCount){
    if(correctCount>=5) return 10;
    if(correctCount===4) return 8;
    if(correctCount===3) return 6;
    if(correctCount===2) return 4;
    return correctCount===1 ? 2 : 0;
  }
  function showGroupNumberGuess(payload){
    if(!payload || numberGuessSessions[payload.id]) return;
    const session=numberGuessSessions[payload.id]={payload,choices:{},done:false,submitted:false};
    let modal=document.getElementById('number-guess-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='number-guess-modal'; modal.className='custom-alert-backdrop'; document.body.appendChild(modal); }
    const isParticipant=(payload.participantIds||[]).includes(currentUser.id);
    modal.innerHTML=`<div class="custom-alert-box number-guess-group" onclick="event.stopPropagation();">
      <div class="custom-alert-icon">🔢</div><div class="setup-step-title" style="font-size:1.32rem;">Zahlenraten</div>
      <p id="number-guess-copy"><strong>${messageEscape(payload.ownerName)}</strong> startet ein Minispiel. Wählt alle eine Zahl von 1 bis 5.</p>
      <p class="setup-info" id="number-guess-progress" style="margin:0 0 14px;">Je mehr richtig liegen, desto höher ist der Punktebonus für alle Richtigen.</p>
      <div class="number-guess-grid">${Array.from({length:5},(_,i)=>`<button class="filter-pill" data-number="${i+1}" ${isParticipant?'':'disabled'}>${i+1}</button>`).join('')}</div>
      <div class="setup-info" id="number-guess-wait" style="margin:14px 0 0;">${isParticipant?'Wähle deine Glückszahl.':'Diese Runde ist bereits ohne dich gestartet.'}</div>
    </div>`;
    modal.classList.remove('hidden');
    const updateWaiting=()=>{
      const selected=Object.keys(session.choices).length, total=(payload.participantIds||[]).length;
      const wait=modal.querySelector('#number-guess-wait');
      if(wait && !session.done) wait.textContent=session.submitted?`Deine Zahl ist gespeichert · wartet auf ${Math.max(0,total-selected)} weitere …`:`${selected}/${total} Zahlen gewählt`;
    };
    modal.querySelectorAll('[data-number]').forEach(btn=>btn.onclick=()=>{
      if(session.submitted || !isParticipant) return;
      const number=Number(btn.dataset.number); session.submitted=true;
      session.choices[currentUser.id]=number;
      modal.querySelectorAll('[data-number]').forEach(x=>{x.disabled=true;x.classList.toggle('active',x===btn);});
      const choice={id:payload.id,userId:currentUser.id,username:currentUser.username,number};
      window.receiveNumberGuessChoice(choice);
      if(teamChannel) teamChannel.send({type:'broadcast',event:'number-guess-choice',payload:choice}).catch(()=>{});
      updateWaiting();
    });
    session.updateWaiting=updateWaiting;
  }
  function resolveGroupNumberGuess(session){
    if(!session || session.done || session.payload.ownerId!==currentUser.id) return;
    const participants=session.payload.participantIds||[];
    if(!participants.length || !participants.every(id=>Number.isInteger(session.choices[id]))) return;
    const answer=1+Math.floor(Math.random()*5);
    const correctIds=participants.filter(id=>session.choices[id]===answer);
    const result={id:session.payload.id,answer,correctIds,reward:numberGuessReward(correctIds.length),total:participants.length};
    window.receiveNumberGuessResult(result);
    if(teamChannel) teamChannel.send({type:'broadcast',event:'number-guess-result',payload:result}).catch(()=>{});
  }
  window.receiveNumberGuessStart=showGroupNumberGuess;
  window.receiveNumberGuessChoice=function(choice){
    const session=choice&&numberGuessSessions[choice.id];
    if(!session || session.done || !session.payload.participantIds.includes(choice.userId)) return;
    session.choices[choice.userId]=choice.number;
    session.updateWaiting?.();
    resolveGroupNumberGuess(session);
  };
  window.receiveNumberGuessResult=async function(result){
    const session=result&&numberGuessSessions[result.id];
    if(!session || session.done) return;
    session.done=true;
    const modal=document.getElementById('number-guess-modal');
    const won=(result.correctIds||[]).includes(currentUser.id);
    if(modal){
      const wait=modal.querySelector('#number-guess-wait');
      const copy=modal.querySelector('#number-guess-copy');
      if(copy) copy.textContent=`Die geheime Zahl war ${result.answer}.`;
      if(wait) wait.textContent=won?`Richtig! ${result.correctIds.length}/${result.total} lagen richtig · +${result.reward} Punkte.`:`Leider nicht richtig · ${result.correctIds.length}/${result.total} lagen richtig.`;
      window.setTimeout(()=>modal.classList.add('hidden'),2600);
    }
    if(won && result.reward>0 && currentRound && sb){
      const {error}=await sb.from('round_items').insert({round_id:currentRound.id,user_id:currentUser.id,scope:'personal',text:`Zahlenraten: +${result.reward} Punkte`,diff:'leicht',points:result.reward,result:'success',struck:true});
      if(!error){ const s=statsStore[currentUser.username]; s.minigamesWon=(s.minigamesWon||0)+1; saveStats(); notifyNewAchievements(checkAchievements(currentUser.username)); }
    }
    showToast(won?`Zahlenraten gewonnen: +${result.reward} Punkte.`:'Zahlenraten: diesmal keine Punkte.','🔢');
    await refreshMiniCard();
  };
  async function runGroupNumberGuess(){
    const participantIds=groupNumberGuessMembers();
    if(!participantIds.includes(currentUser.id)){ showAlert('Du bist für dieses Match nicht aktiv.','🔢'); return false; }
    const payload={id:'ng-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),ownerId:currentUser.id,ownerName:currentUser.username,participantIds};
    showGroupNumberGuess(payload);
    if(teamChannel) teamChannel.send({type:'broadcast',event:'number-guess-start',payload}).catch(()=>{});
    return true;
  }
  const riskCardSessions = {};
  function showRiskCardVoteInvite(payload){
    if(!payload || riskCardSessions[payload.id]) return;
    const total = Math.max(1, (teamMembers||[]).length);
    const session = riskCardSessions[payload.id] = {payload, votes:{}, myVote:null, started:false};
    let modal=document.getElementById('risk-card-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='risk-card-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
    const renderVote=()=>{
      const counted=Object.keys(session.votes).length;
      modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:500px;text-align:center;">
        <div style="font-size:4rem;line-height:1;filter:drop-shadow(0 0 18px #c084fc)">🎲</div>
        <div class="setup-step-title" style="margin:10px 0 6px;">Risiko-Karte</div>
        <p class="setup-info" style="margin:0 0 16px;">${payload.ownerName} spielt die Risiko-Karte. Stimmt ab, wie viele Würfel geworfen werden — die Mehrheit entscheidet.</p>
        <div class="filter-row" style="justify-content:center;">${[1,2,3].map(n=>`<button class="filter-pill${session.myVote===n?' active':''}" onclick="window.__riskCardVote('${payload.id}',${n})">${n} 🎲</button>`).join('')}</div>
        <p class="setup-info" style="margin:14px 0 0;font-size:.78rem;">${counted}/${total} abgestimmt${session.myVote?' — warte auf die anderen …':''}</p>
      </div>`;
    };
    window.__riskCardVote=(id,n)=>{
      const s=riskCardSessions[id]; if(!s||s.started) return;
      s.myVote=n; s.votes[currentUser.id]=n;
      window.receiveRiskCardVote({id,userId:currentUser.id,n});
      if(teamChannel) teamChannel.send({type:'broadcast',event:'risk-card-vote',payload:{id,userId:currentUser.id,n}}).catch(()=>{});
      if(s.renderVote) s.renderVote();
    };
    renderVote();
    modal.classList.remove('hidden');
    session.renderVote=renderVote;
  }
  window.receiveRiskCardInvite = showRiskCardVoteInvite;
  window.receiveRiskCardVote = function(vote){
    const session=vote&&riskCardSessions[vote.id];
    if(!session || session.started) return;
    session.votes[vote.userId]=vote.n;
    if(session.renderVote && document.getElementById('risk-card-modal')) session.renderVote();
    const total=Math.max(1,(teamMembers||[]).length);
    if(session.payload.ownerId===currentUser.id && Object.keys(session.votes).length>=total){
      session.started=true;
      const tally={1:0,2:0,3:0};
      Object.values(session.votes).forEach(n=>{ tally[n]=(tally[n]||0)+1; });
      const maxVotes=Math.max(tally[1],tally[2],tally[3]);
      const winners=[1,2,3].filter(n=>tally[n]===maxVotes);
      const diceCount=winners[randInt(0,winners.length-1)];
      window.receiveRiskCardRolling({id:session.payload.id,diceCount});
      if(teamChannel) teamChannel.send({type:'broadcast',event:'risk-card-rolling',payload:{id:session.payload.id,diceCount}}).catch(()=>{});
    }
  };
  window.receiveRiskCardRolling = function(info){
    const session=riskCardSessions[info.id];
    if(!session) return;
    session.diceCount=info.diceCount;
    showRiskCardDiceRoll(session);
  };
  function showRiskCardDiceRoll(session){
    const {payload,diceCount}=session;
    const isOwner=payload.ownerId===currentUser.id;
    let modal=document.getElementById('risk-card-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='risk-card-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
    modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:500px;text-align:center;">
      <div class="setup-step-title" style="margin:0 0 6px;">Risiko-Karte — ${diceCount} 🎲</div>
      <p class="setup-info" id="risk-card-roll-info" style="margin:0 0 16px;">${isOwner?'Drückt auf „Würfeln", um die Runde zu entscheiden.':`${payload.ownerName} würfelt gleich für alle …`}</p>
      <div class="dice-multi-row" id="risk-card-dice-row" style="margin-bottom:14px;">${Array.from({length:diceCount},(_,i)=>`<div class="dice-scene"><div class="dice-cube" id="risk-card-cube-${i}">${buildDicePipsHTML()}</div></div>`).join('')}</div>
      <div class="dice-result-text" id="risk-card-dice-result">${isOwner?'Bereit zum Würfeln!':'Wartet auf den Wurf …'}</div>
      <div class="roll-zone" style="margin-top:14px;">${isOwner?`<button class="roll-btn" id="risk-card-roll-btn"><span class="dice">🎲</span> Würfeln</button>`:''}</div>
    </div>`;
    modal.classList.remove('hidden');
    if(isOwner){
      const rotations = Array.from({length:diceCount},()=>({x:-20,y:-30}));
      document.getElementById('risk-card-roll-btn').onclick=()=>{
        const btn=document.getElementById('risk-card-roll-btn'); if(btn.disabled) return;
        btn.disabled=true; btn.classList.add('rolling');
        const rolls=[];
        for(let i=0;i<diceCount;i++){
          const result=randInt(1,6); rolls.push(result);
          const target=DICE_FACE_ROTATION[result];
          const spinX=360*randInt(2,3)*(Math.random()<0.5?1:-1);
          const spinY=360*randInt(2,4)*(Math.random()<0.5?1:-1);
          const rot=rotations[i];
          rot.x=Math.round((rot.x+spinX)/360)*360+target.x;
          rot.y=Math.round((rot.y+spinY)/360)*360+target.y;
          document.getElementById('risk-card-cube-'+i).style.transform=`rotateX(${rot.x}deg) rotateY(${rot.y}deg)`;
        }
        document.getElementById('risk-card-dice-result').textContent='Würfelt …';
        window.setTimeout(()=>{
          const total=rolls.reduce((a,b)=>a+b,0);
          const threshold=Math.round(3.5*diceCount);
          const success=total>threshold;
          const result={id:payload.id,ownerId:payload.ownerId,ownerName:payload.ownerName,diceCount,rolls,total,threshold,success};
          window.receiveRiskCardResult(result);
          if(teamChannel) teamChannel.send({type:'broadcast',event:'risk-card-result',payload:result}).catch(()=>{});
        },1150);
      };
    }
  }
  window.receiveRiskCardResult = async function(result){
    const session=riskCardSessions[result.id]; if(session) session.done=true;
    let modal=document.getElementById('risk-card-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='risk-card-modal'; modal.className='member-modal-backdrop'; document.body.appendChild(modal); }
    modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:460px;text-align:center;">
      <div style="font-size:3.2rem;line-height:1;">${result.success?'✅':'❌'}</div>
      <div class="setup-step-title" style="margin:10px 0 6px;">${result.success?'Geschafft!':'Leider nicht geschafft'}</div>
      <p class="setup-info" style="margin:0 0 4px;">${(result.rolls||[]).join(' + ')} = <strong>${result.total}</strong> (nötig: über ${result.threshold})</p>
      <p class="setup-info" style="margin:0;">${result.success?`Die Punkte einer offenen Challenge werden ×${result.diceCount} vervielfacht.`:'Es gibt eine zusätzliche schwere Challenge.'}</p>
      <div class="roll-zone" style="margin-top:16px;"><button class="roll-btn" onclick="document.getElementById('risk-card-modal').classList.add('hidden')">Alles klar</button></div>
    </div>`;
    modal.classList.remove('hidden');
    if(result.ownerId!==currentUser.id) return;
    const s=statsStore[currentUser.username];
    if(result.success){
      const item=roundItems.find(it=>it.scope==='personal' && it.user_id===currentUser.id && !it.result);
      if(!item){ showAlert('Keine offene Challenge für die Risiko-Karte.','🎲'); return; }
      const {error}=await sb.from('round_items').update({points:(item.points||0)*result.diceCount}).eq('id',item.id);
      if(error){ showAlert('Risiko-Karte konnte nicht gespeichert werden: '+error.message); return; }
      if(s){ s.minigamesWon=(s.minigamesWon||0)+1; saveStats(); notifyNewAchievements(checkAchievements(currentUser.username)); }
    } else {
      const pool=personalPoolFor(currentRound.game_id,currentRound.game_mode).filter(x=>x.diff==='schwer');
      if(!pool.length){ showAlert('Für dieses Spiel sind keine schweren Challenges hinterlegt. Das Item wurde nicht verbraucht.','🎲'); return; }
      const pick=pool[randInt(0,pool.length-1)];
      const {error}=await sb.from('round_items').insert({round_id:currentRound.id,user_id:currentUser.id,scope:'personal',text:'Risiko-Karte: '+pick.text,diff:'schwer',points:TEAM_ROUND_PERSONAL_DIFF_POINTS['schwer']});
      if(error){ showAlert('Risiko-Karte konnte nicht gespeichert werden: '+error.message); return; }
    }
    broadcastTeamCardEffect(SHOP_SABOTAGE.find(x=>x.id==='risk_card')||{icon:'🎲',label:'Risiko-Karte'}, '');
    await consumeMiniCard('risk_card'); await refreshMiniCard();
  };
  async function runRiskCardVote(){
    const payload={id:'rc-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),ownerId:currentUser.id,ownerName:currentUser.username};
    showRiskCardVoteInvite(payload);
    if(teamChannel) teamChannel.send({type:'broadcast',event:'risk-card-invite',payload}).catch(()=>{});
    return true;
  }
  useSabotageItem = async function(id,target,extra){
    if(!['reaction_duel','risk_card','number_guess'].includes(id)) return baseUseSabotage(id,target,extra);
    if(!currentRound || !currentUser || !sb || currentRound.status!=='active') return;
    const s=statsStore[currentUser.username];
    if(!s || !(s.shopOwned&&s.shopOwned.sabotage&&s.shopOwned.sabotage[id]) || !(sabotageLoadout[id]||0)){
      showAlert('Dieses Minispiel wurde nicht für diese Runde mitgenommen.','🎯'); return;
    }
    if(id==='reaction_duel'){
      if(await runGroupReactionDuel()){
        broadcastTeamCardEffect(SHOP_SABOTAGE.find(x=>x.id===id)||{icon:'⚡',label:'Reaktionsduell'}, '');
        await consumeMiniCard(id); await refreshMiniCard();
      }
      return;
    }
    if(id==='risk_card'){
      await runRiskCardVote();
      return;
    }
    if(await runGroupNumberGuess()){
      broadcastTeamCardEffect(SHOP_SABOTAGE.find(x=>x.id===id)||{icon:'🔢',label:'Zahlenraten'}, '');
      await consumeMiniCard(id); await refreshMiniCard();
    }
  };
})();

(function(){
  const PIKA_KEY = 'winchallenge_pikachu_expedition_v1';
  const TOTAL = 50;
  const PIKA_VARIANTS = [
    {emoji:'⚡', freq:880, img:'assets/pikachu-50-avatar.png', label:'Pikachu'},
    {emoji:'🍀', freq:587, img:null, label:'Glücksklee'},
    {emoji:'✨', freq:1046, img:null, label:'Sternenfunke'},
  ];
  function playPikaSound(freq){
    try{
      const ctx = new (window.AudioContext||window.webkitAudioContext)();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.type='sine'; osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.16, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+0.28);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime+0.28);
    }catch(e){}
  }
  if(!SHOP_BANNERS.some(b=>b.id==='pikachu_expedition')){
    SHOP_BANNERS.push({id:'pikachu_expedition', label:'Pikachu-Expedition', img:'assets/pikachu-50-banner.gif', cost:0, prestige:true, requiresPikachu:true, animated:true});
  }
  const oldShowView = showView;
  showView = function(id, skipHistory){
    const answer = oldShowView(id, skipHistory);
    window.setTimeout(()=>placePikachu(id), 80);
    return answer;
  };
  function readFound(){ try{return JSON.parse(localStorage.getItem(PIKA_KEY)||'[]');}catch(e){return [];} }
  function placePikachu(viewId){
    if(window.__pikaV2) return;
    const view = document.getElementById('view-'+viewId);
    if(!view || view.querySelector('.pika-hidden')) return;
    const found = readFound();
    const index = Array.from({length:TOTAL},(_,i)=>i).find(i=>!found.includes(i));
    if(index===undefined) return;
    const variant = PIKA_VARIANTS[Math.floor(Math.random()*PIKA_VARIANTS.length)];
    const pika = document.createElement('button');
    pika.type='button'; pika.className='pika-hidden'; pika.title=''; pika.setAttribute('aria-label','Verstecktes Sammelobjekt');
    pika.style.cssText=`position:absolute;z-index:20;right:${18+(index%4)*19}px;top:${120+(index%7)*67}px;width:28px;height:28px;padding:0;border:2px solid #facc15;border-radius:50%;background:#facc15;box-shadow:0 0 12px #facc15;cursor:pointer;opacity:.82;overflow:hidden;font-size:15px;display:flex;align-items:center;justify-content:center;`;
    pika.innerHTML = variant.img
      ? `<img src="${variant.img}" alt="" style="width:100%;height:100%;object-fit:contain;display:block;border-radius:50%;">`
      : variant.emoji;
    pika.onclick=()=>{
      playPikaSound(variant.freq);
      const next = [...new Set([...readFound(),index])];
      localStorage.setItem(PIKA_KEY,JSON.stringify(next)); pika.remove();
      showToast(`${variant.label} gefunden! ${next.length}/${TOTAL}`, variant.emoji);
      if(next.length>=TOTAL && currentUser){
        const s=statsStore[currentUser.username]; s.shopOwned=s.shopOwned||{badges:[],banners:[],hats:[],glows:[],frames:[],sabotage:{}};
        s.shopOwned.banners=s.shopOwned.banners||[];
        if(!s.shopOwned.banners.includes('pikachu_expedition')) s.shopOwned.banners.push('pikachu_expedition');
        saveStats(); showAlert('Pikachu-Expedition abgeschlossen! Das animierte Banner und der Blitz-Emoji sind freigeschaltet.','⚡');
      }
    };
    view.style.position = view.style.position || 'relative';
    view.appendChild(pika);
  }
})();
/* ==================================================== ZAHLENRATEN ==================================================== */
function openNumberGuessGame(){
  return new Promise(resolve=>{
    let modal=document.getElementById('number-guess-modal');
    if(!modal){
      modal=document.createElement('div');
      modal.id='number-guess-modal';
      modal.className='custom-alert-backdrop';
      document.body.appendChild(modal);
    }
    const close=()=>{ modal.classList.add('hidden'); resolve(null); };
    modal.innerHTML=`<div class="custom-alert-box" style="max-width:430px;text-align:center;" onclick="event.stopPropagation();">
      <button class="member-modal-close" aria-label="Schließen">✕</button>
      <div class="custom-alert-icon">🔢</div>
      <div class="setup-step-title" style="font-size:1.35rem;">Zahlenraten</div>
      <p>Wähle deine Glückszahl. Triffst du die geheime Zahl von 1 bis 10, bekommst du sofort <strong style="color:var(--turquoise)">+3 Punkte</strong>.</p>
      <div class="number-guess-grid" style="display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin:18px 0;">${Array.from({length:10},(_,i)=>`<button class="filter-pill" data-number="${i+1}" style="min-height:46px;justify-content:center;font-size:1.05rem;">${i+1}</button>`).join('')}</div>
      <div class="setup-info" style="margin:0;">Ein Versuch pro Karte.</div>
    </div>`;
    modal.classList.remove('hidden');
    modal.onclick=e=>{ if(e.target===modal) close(); };
    modal.querySelector('.member-modal-close').onclick=close;
    modal.querySelectorAll('[data-number]').forEach(button=>button.onclick=()=>{ modal.classList.add('hidden'); resolve(Number(button.dataset.number)); });
  });
}

/* ==================================================== MITTEILUNGSZENTRUM ==================================================== */
let messageCenterChannel = null;
let messageCenterItems = [];
function messageEscape(value){ return String(value ?? '').replace(/[&<>'"]/g, c=>({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;' }[c])); }
function messageDate(value){ try{return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch(e){return ''; } }
function messageKindLabel(kind){ return ({news:'Neuigkeiten',patch:'Patch',bugfix:'Bugfix',games:'Spiele',challenges:'Challenges',shop:'Shop',direct:'Direkte Nachricht',invite:'Einladung'})[kind] || 'Neuigkeiten'; }
function messageReadKey(){ return currentUser ? `winchallenge_messages_read_${currentUser.id}` : ''; }
function messageReadAt(){ try{return Number(localStorage.getItem(messageReadKey())||0);}catch(e){return 0;} }
function setMessagesRead(){ try{localStorage.setItem(messageReadKey(),String(Date.now()));}catch(e){} updateMessageBadges(0); }
const MESSAGE_RETENTION_MS = 24 * 60 * 60 * 1000;
function messageRetentionKey(){ return currentUser ? `winchallenge_message_retention_${currentUser.id}` : ''; }
function messageSessionKey(){ return currentUser ? `winchallenge_message_login_${currentUser.id}` : ''; }
function readMessageRetention(){ try{return JSON.parse(localStorage.getItem(messageRetentionKey())||'{}')||{};}catch(e){return {};} }
function writeMessageRetention(value){ try{localStorage.setItem(messageRetentionKey(),JSON.stringify(value));}catch(e){} }
function beginMessageRetentionSession(){
  if(!currentUser) return;
  try{ sessionStorage.setItem(messageSessionKey(),String(Date.now())); }catch(e){}
}
function retainMessageItems(items){
  const now=Date.now(); const entries=readMessageRetention();
  let sessionStart=now;
  try{ sessionStart=Number(sessionStorage.getItem(messageSessionKey())||now); }catch(e){}
  items.forEach(item=>{
    const id=String(item.id); const known=entries[id];
    if(!known) entries[id]={expiresAt:Math.max(sessionStart,new Date(item.created_at||now).getTime())+MESSAGE_RETENTION_MS,dismissed:false};
  });
  Object.keys(entries).forEach(id=>{ if(entries[id]?.expiresAt < now - MESSAGE_RETENTION_MS) delete entries[id]; });
  writeMessageRetention(entries);
  return items.filter(item=>{ const entry=entries[String(item.id)]; return entry && !entry.dismissed && entry.expiresAt>now; });
}
function dismissMessageFromCenter(id){
  const entries=readMessageRetention(); const previous=entries[String(id)]||{};
  entries[String(id)]={...previous,dismissed:true,expiresAt:previous.expiresAt||Date.now()+MESSAGE_RETENTION_MS};
  writeMessageRetention(entries); messageCenterItems=messageCenterItems.filter(item=>String(item.id)!==String(id));
  renderMessageCenterList(); refreshMessageBadges();
}
function updateMessageBadges(count){
  if(!userPrefs?.messageNotifications) count=0;
  const label=count>99?'99+':String(Math.max(0,count||0));
  document.querySelectorAll('[data-message-badge]').forEach(el=>{el.textContent=label;el.classList.toggle('visible',count>0);});
  document.querySelectorAll('[data-message-hamburger-badge]').forEach(el=>{el.textContent=label;el.classList.toggle('visible',count>0);});
  document.querySelectorAll('[data-message-menu-count]').forEach(el=>{el.textContent=count>0?`(${label})`:'';});
}
async function refreshMessageBadges(){
  if(!sb||!currentUser) return;
  const [messagesResult,notificationsResult,inviteMessages,dmResult]=await Promise.all([
    sb.from('app_messages').select('id,author_id,created_at').order('created_at',{ascending:false}).limit(80),
    sb.from('player_notifications').select('id,from_user_id,message,created_at').eq('target_user_id',currentUser.id).is('round_id',null).order('created_at',{ascending:false}).limit(80),
    loadPendingInviteMessages().catch(()=>[]),
    sb.from('direct_messages').select('id',{count:'exact',head:true}).eq('recipient_id',currentUser.id).is('read_at',null).catch(()=>({count:0}))
  ]);
  if(messagesResult.error || notificationsResult.error) return;
  const readAt=messageReadAt();
  const isInviteLikeText=t=>/lädt dich|möchte.*befreundet/i.test(String(t||''));
  const visible=retainMessageItems([
    ...(messagesResult.data||[]),
    ...(notificationsResult.data||[]).filter(n=>!isInviteLikeText(n.message)).map(n=>({...n,id:`notification-${n.id}`,author_id:n.from_user_id})),
    ...inviteMessages
  ]);
  const unread=visible.filter(item=>item.author_id!==currentUser.id && new Date(item.created_at).getTime()>readAt).length;
  const dmUnread=(dmResult&&dmResult.count)||0;
  const teamChatUnread=(typeof myTeam!=='undefined' && myTeam) ? unreadTeamChatCount() : 0;
  updateMessageBadges(unread+dmUnread+teamChatUnread);
}
let messageBadgePollInterval=null;
function startMessageBadgePolling(){
  if(messageBadgePollInterval) return;
  messageBadgePollInterval=setInterval(()=>{ if(currentUser) refreshMessageBadges(); }, 25000);
}
function ensureMessageCenterLive(){
  if(messageCenterChannel||!sb||!currentUser) return;
  messageCenterChannel=sb.channel('message-center-'+currentUser.id)
    .on('postgres_changes',{event:'*',schema:'public',table:'app_messages'},()=>{ refreshMessageBadges(); if(document.getElementById('view-message-center')?.classList.contains('active')) refreshMessageCenter(true); })
    .on('postgres_changes',{event:'*',schema:'public',table:'app_message_replies'},()=>{ if(document.getElementById('view-message-center')?.classList.contains('active')) refreshMessageCenter(true); })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'player_notifications',filter:`target_user_id=eq.${currentUser.id}`},()=>{ refreshMessageBadges(); if(document.getElementById('view-message-center')?.classList.contains('active')) refreshMessageCenter(true); })
    .on('postgres_changes',{event:'*',schema:'public',table:'team_invites',filter:`to_user=eq.${currentUser.id}`},()=>{ refreshMessageBadges(); if(document.getElementById('view-message-center')?.classList.contains('active')) refreshMessageCenter(true); })
    .on('postgres_changes',{event:'*',schema:'public',table:'friend_requests',filter:`to_user=eq.${currentUser.id}`},()=>{ refreshMessageBadges(); if(document.getElementById('view-message-center')?.classList.contains('active')) refreshMessageCenter(true); }).subscribe();
}
function ensureMessageCenterView(){
  if(document.getElementById('view-message-center')) return;
  const view=document.createElement('section');
  view.id='view-message-center'; view.className='view';
  view.innerHTML=`<div class="bg-watermark">W</div><div class="topbar"><button class="back-btn" onclick="goBack()">Zurück</button><div class="page-title">Mitteilungszentrum</div></div><div class="content"><div class="section-lead"><div class="eyebrow">News & Nachrichten</div><h2>Immer auf dem Laufenden</h2><p>Patches, neue Inhalte und persönliche Nachrichten an einem Ort.</p></div><div class="filter-row" id="mc-tabs" style="margin-bottom:14px;"><button class="filter-pill active" onclick="switchMcTab('messages')">✉️ Mitteilungen</button><button class="filter-pill" onclick="switchMcTab('chat')">💬 Chat</button></div><div id="mc-pane-messages"><div class="filter-row" id="message-center-clear-row" style="justify-content:flex-end;margin-bottom:10px;display:none;"><button class="sb-btn danger" onclick="clearAllMessagesFromCenter()">🗑️ Alle löschen</button></div><div id="message-center-admin"></div><div id="message-center-list" class="message-center-list"></div></div><div id="mc-pane-chat" style="display:none;"><div id="chat-list-view"></div><div id="chat-conversation-view" style="display:none;"></div></div></div>`;
  document.body.appendChild(view);
}
async function loadPendingInviteMessages(){
  // Team-Einladungen und Freundschaftsanfragen laufen technisch über eigene Tabellen
  // (team_invites, friend_requests) statt über player_notifications — deshalb landeten sie
  // bisher nie im Mitteilungszentrum, obwohl dafür oben ein Toast/Badge aufploppte.
  // Hier im Mitteilungszentrum verfallen sie bewusst schon nach 1 Stunde (nicht erst nach 24h),
  // damit man zeitnah reagiert.
  const expiresBefore = new Date(Date.now()-60*60*1000).toISOString();
  const [teamInvitesResult, friendRequestsResult] = await Promise.all([
    sb.from('team_invites').select('id,team_id,created_at,teams(name,code),profiles!team_invites_from_user_fkey(id,username,avatar)').eq('to_user',currentUser.id).eq('status','pending').gte('created_at',expiresBefore),
    sb.from('friend_requests').select('id,from_user,created_at,profiles!friend_requests_from_user_fkey(id,username,avatar)').eq('to_user',currentUser.id).eq('status','pending').gte('created_at',expiresBefore)
  ]);
  const teamInvites=(teamInvitesResult.data||[]).map(inv=>({
    id:`team-invite-${inv.id}`, author_id:inv.profiles?.id||null, recipient_id:currentUser.id,
    category:'invite', title:'Team-Einladung', created_at:inv.created_at,
    body:`${inv.profiles?.username||'Jemand'} lädt dich ins Team „${inv.teams?.name||'Team'}“ ein.`,
    profiles:{username:inv.profiles?.username||'WIN CHALLENGE',avatar:inv.profiles?.avatar||null}, app_message_replies:[],
    inviteAction:{type:'team',inviteId:inv.id,teamCode:inv.teams?.code||''}
  }));
  const friendRequests=(friendRequestsResult.data||[]).map(req=>({
    id:`friend-request-${req.id}`, author_id:req.profiles?.id||null, recipient_id:currentUser.id,
    category:'invite', title:'Freundschaftsanfrage', created_at:req.created_at,
    body:`${req.profiles?.username||'Jemand'} möchte mit dir befreundet sein.`,
    profiles:{username:req.profiles?.username||'WIN CHALLENGE',avatar:req.profiles?.avatar||null}, app_message_replies:[],
    inviteAction:{type:'friend',requestId:req.id,fromUserId:req.profiles?.id||null}
  }));
  return [...teamInvites,...friendRequests];
}
async function refreshMessageCenter(render=true){
  if(!sb || !currentUser) return;
  const [messagesResult, notificationsResult, inviteMessages] = await Promise.all([
    sb.from('app_messages').select('id,author_id,recipient_id,category,title,body,created_at,profiles!app_messages_author_id_fkey(username,avatar),app_message_replies(id,author_id,body,created_at,profiles(username,avatar))').order('created_at',{ascending:false}).limit(80),
    sb.from('player_notifications').select('id,from_user_id,message,icon,created_at').eq('target_user_id',currentUser.id).is('round_id',null).order('created_at',{ascending:false}).limit(80),
    loadPendingInviteMessages().catch(e=>{ console.warn('Einladungen konnten nicht geladen werden:',e.message); return []; })
  ]);
  const error=messagesResult.error||notificationsResult.error;
  if(error){ console.warn('Mitteilungen konnten nicht geladen werden:',error.message); messageCenterItems=[]; }
  else {
    const isInviteLikeText=t=>/lädt dich|möchte.*befreundet/i.test(String(t||''));
    const direct=(notificationsResult.data||[]).filter(note=>!isInviteLikeText(note.message)).map(note=>({
      id:`notification-${note.id}`, author_id:note.from_user_id, recipient_id:currentUser.id,
      category:'direct', title:'Direkte Mitteilung', body:note.message||'Neue Mitteilung', created_at:note.created_at,
      profiles:{username:'WIN CHALLENGE',avatar:null}, app_message_replies:[]
    }));
    messageCenterItems=retainMessageItems([...(messagesResult.data||[]),...direct,...inviteMessages].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)));
  }
  if(render) renderMessageCenterList(error?.message);
}
function renderMessageCenterList(loadError=''){
  const list=document.getElementById('message-center-list'); if(!list) return;
  const clearRow=document.getElementById('message-center-clear-row');
  if(loadError){ list.innerHTML=''; if(clearRow) clearRow.style.display='none'; return; }
  if(clearRow) clearRow.style.display=messageCenterItems.length?'flex':'none';
  if(!messageCenterItems.length){ list.innerHTML='<div class="empty-hint">Noch keine Mitteilungen. Neue Updates und Nachrichten erscheinen hier live.</div>'; return; }
  list.innerHTML=messageCenterItems.map(m=>{
    const author=m.profiles||{}; const replies=(m.app_message_replies||[]).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));
    const request=messageRequestRef(m.body);
    const cleanBody=String(m.body||'').replace(/\n?\[wc-request:[^\]]+\]/g,'').trim();
    const openRequest=currentUser?.is_admin && request ? `<button class="message-card-action" type="button" onclick="openAdminRequestModal('${request.kind}','${request.id}')">Anfrage öffnen</button>` : '';
    const inviteActions=m.category==='invite' && m.inviteAction ? `<div class="filter-row" style="margin-top:13px;">${m.inviteAction.type==='team'?`<button class="message-card-action" type="button" onclick="respondToInviteMessage('${messageEscape(m.id)}',true)">Annehmen</button><button class="sb-btn danger" type="button" onclick="respondToInviteMessage('${messageEscape(m.id)}',false)">Ablehnen</button>`:`<button class="message-card-action" type="button" onclick="respondToInviteMessage('${messageEscape(m.id)}',true)">Annehmen</button><button class="sb-btn danger" type="button" onclick="respondToInviteMessage('${messageEscape(m.id)}',false)">Ablehnen</button>`}</div>` : '';
    const replyForm=m.category==='invite' ? '' : `<form class="message-reply-form" onsubmit="event.preventDefault();sendMessageReply('${m.id}',this)"><input maxlength="800" required placeholder="Antwort schreiben …"><button class="sb-btn" type="submit">Antworten</button></form>`;
    return `<article class="message-card" data-message-id="${messageEscape(m.id)}"><div class="message-card-head"><span class="message-kind ${messageEscape(m.category)}">${messageEscape(messageKindLabel(m.category))}</span><time>${messageDate(m.created_at)}</time></div><h3>${messageEscape(m.title)}</h3><p>${messageEscape(cleanBody).replace(/\n/g,'<br>')}</p>${openRequest}${inviteActions}<div class="message-author">${renderAccountAvatarHTML(author.avatar,22)} ${messageEscape(author.username||'WIN CHALLENGE')}</div><div class="message-replies">${replies.map(r=>`<div class="message-reply"><strong>${messageEscape(r.profiles?.username||'Spieler')}</strong><span>${messageEscape(r.body)}</span><time>${messageDate(r.created_at)}</time></div>`).join('')}</div>${replyForm}</article>`;
  }).join('');
  list.querySelectorAll('.message-card[data-message-id]').forEach(card=>{
    const id=card.dataset.messageId;
    if(String(id).startsWith('notification-')) card.querySelector('.message-reply-form')?.remove();
    const button=document.createElement('button');
    button.type='button'; button.className='message-delete'; button.textContent='Löschen'; button.title='Mitteilung ausblenden';
    button.onclick=()=>dismissMessageFromCenter(id);
    card.querySelector('.message-card-head')?.appendChild(button);
  });
}
async function clearAllMessagesFromCenter(){
  if(!messageCenterItems.length) return;
  if(!(await confirmAction('Wirklich alle Mitteilungen ausblenden?'))) return;
  const entries=readMessageRetention();
  const now=Date.now();
  messageCenterItems.forEach(m=>{
    const previous=entries[String(m.id)]||{};
    entries[String(m.id)]={...previous,dismissed:true,expiresAt:previous.expiresAt||now+MESSAGE_RETENTION_MS};
  });
  writeMessageRetention(entries);
  messageCenterItems=[];
  renderMessageCenterList();
  refreshMessageBadges();
}
let mcActiveTab='messages';
function switchMcTab(tab){
  mcActiveTab=tab;
  const tabsRow=document.getElementById('mc-tabs');
  if(tabsRow) tabsRow.querySelectorAll('.filter-pill').forEach((b,i)=>b.classList.toggle('active',(tab==='messages'&&i===0)||(tab==='chat'&&i===1)));
  const paneMsg=document.getElementById('mc-pane-messages'), paneChat=document.getElementById('mc-pane-chat');
  if(paneMsg) paneMsg.style.display=tab==='messages'?'block':'none';
  if(paneChat) paneChat.style.display=tab==='chat'?'block':'none';
  if(tab==='chat'){ ensureDmLive(); if(!dmActivePartner) renderChatList(); }
}
let dmActivePartner=null;
let dmMessages=[];
let dmChannelReady=false;
async function renderChatList(){
  const wrap=document.getElementById('chat-list-view');
  if(!wrap||!sb||!currentUser) return;
  wrap.innerHTML='<div class="empty-hint">Lädt…</div>';
  const {data,error}=await sb.from('direct_messages')
    .select('id,sender_id,recipient_id,body,created_at,read_at,sender:profiles!direct_messages_sender_id_fkey(id,username,avatar),recipient:profiles!direct_messages_recipient_id_fkey(id,username,avatar)')
    .or(`sender_id.eq.${currentUser.id},recipient_id.eq.${currentUser.id}`)
    .order('created_at',{ascending:false}).limit(300);
  if(error){ wrap.innerHTML='<div class="empty-hint">Chat konnte nicht geladen werden: '+messageEscape(error.message)+'</div>'; return; }
  const byPartner={};
  (data||[]).forEach(m=>{
    const isMine=m.sender_id===currentUser.id;
    const partner=isMine?m.recipient:m.sender;
    if(!partner) return;
    const pid=partner.id;
    if(!byPartner[pid]) byPartner[pid]={partner,lastBody:m.body,lastAt:m.created_at,lastMine:isMine,unread:0};
    if(!isMine && !m.read_at) byPartner[pid].unread++;
  });
  const list=Object.values(byPartner).sort((a,b)=>new Date(b.lastAt)-new Date(a.lastAt));
  if(!list.length){ wrap.innerHTML='<div class="empty-hint">Noch keine Chats. Öffne über die Freundesliste einen Chat mit jemandem.</div>'; return; }
  wrap.innerHTML=list.map(c=>`<button class="settings-row-btn" style="width:100%;margin-bottom:8px;cursor:pointer;" onclick="openDmConversation('${c.partner.id}','${messageEscape(c.partner.username)}')">
      <span class="settings-row-icon" style="padding:0;background:none;">${renderAccountAvatarHTML(c.partner.avatar,36)}</span>
      <span class="settings-row-text"><span class="settings-row-title">${messageEscape(c.partner.username)}${c.unread?` <span class="menu-message-count">(${c.unread})</span>`:''}</span><span class="settings-row-sub">${c.lastMine?'Du: ':''}${messageEscape((c.lastBody||'').slice(0,60))}</span></span>
    </button>`).join('');
}
async function openDmConversation(partnerId, partnerName){
  dmActivePartner={id:partnerId,name:partnerName};
  const listView=document.getElementById('chat-list-view'), convView=document.getElementById('chat-conversation-view');
  if(listView) listView.style.display='none';
  if(convView){
    convView.style.display='block';
    convView.innerHTML=`<button class="sb-btn" style="margin-bottom:12px;" onclick="closeDmConversation()">← Zurück</button>
      <div class="settings-card" style="max-height:52vh;overflow:auto;" id="dm-feed"></div>
      <form class="team-chat-form" onsubmit="event.preventDefault();sendDmMessage(this)"><input maxlength="800" required placeholder="Nachricht an ${messageEscape(partnerName)} …"><button class="roll-btn" type="submit">Senden</button></form>`;
  }
  await loadDmMessages();
  await markDmRead();
  refreshMessageBadges();
  ensureDmLive();
}
function closeDmConversation(){
  dmActivePartner=null;
  const listView=document.getElementById('chat-list-view'), convView=document.getElementById('chat-conversation-view');
  if(convView) convView.style.display='none';
  if(listView) listView.style.display='block';
  renderChatList();
}
async function loadDmMessages(){
  if(!dmActivePartner||!sb||!currentUser) return;
  const {data,error}=await sb.from('direct_messages').select('id,sender_id,recipient_id,body,created_at')
    .or(`and(sender_id.eq.${currentUser.id},recipient_id.eq.${dmActivePartner.id}),and(sender_id.eq.${dmActivePartner.id},recipient_id.eq.${currentUser.id})`)
    .order('created_at',{ascending:true}).limit(300);
  dmMessages=error?[]:(data||[]);
  renderDmFeed();
}
function renderDmFeed(){
  const feed=document.getElementById('dm-feed'); if(!feed) return;
  feed.innerHTML=dmMessages.length?dmMessages.map(m=>{
    const mine=m.sender_id===currentUser.id;
    return `<div class="message-reply" style="grid-template-columns:1fr;text-align:${mine?'right':'left'};"><strong>${mine?'Du':messageEscape(dmActivePartner.name)}</strong><span>${messageEscape(m.body)}</span><time>${messageDate(m.created_at)}</time></div>`;
  }).join('') : '<div class="empty-hint">Noch keine Nachrichten. Schreib was!</div>';
  feed.scrollTop=feed.scrollHeight;
}
async function sendDmMessage(form){
  const input=form.querySelector('input'); const body=input.value.trim();
  if(!body||!dmActivePartner||!sb||!currentUser) return;
  input.value='';
  const {error}=await sb.from('direct_messages').insert({sender_id:currentUser.id,recipient_id:dmActivePartner.id,body});
  if(error){ showAlert('Nachricht konnte nicht gesendet werden: '+error.message); return; }
  await loadDmMessages();
}
async function markDmRead(){
  if(!dmActivePartner||!sb||!currentUser) return;
  try{ await sb.from('direct_messages').update({read_at:new Date().toISOString()}).eq('sender_id',dmActivePartner.id).eq('recipient_id',currentUser.id).is('read_at',null); }catch(e){}
}
function ensureDmLive(){
  if(dmChannelReady||!sb||!currentUser) return;
  dmChannelReady=true;
  sb.channel('dm-'+currentUser.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages',filter:`recipient_id=eq.${currentUser.id}`},(payload)=>{
      if(dmActivePartner && payload.new.sender_id===dmActivePartner.id){ loadDmMessages(); markDmRead(); }
      else showToast('Neue Chat-Nachricht.','💬');
      if(document.getElementById('view-message-center')?.classList.contains('active') && mcActiveTab==='chat' && !dmActivePartner) renderChatList();
      refreshMessageBadges();
    }).subscribe();
}
async function openDmFromFriends(partnerId, partnerName){
  showView('message-center');
  await renderMessageCenter();
  switchMcTab('chat');
  await openDmConversation(partnerId, partnerName);
}
async function respondToInviteMessage(itemId,accept){
  const item=messageCenterItems.find(m=>String(m.id)===String(itemId));
  const action=item?.inviteAction;
  if(!action) return;
  try{
    if(action.type==='team'){
      if(accept) await acceptTeamInvite(action.inviteId,action.teamCode);
      else await declineTeamInvite(action.inviteId);
    } else if(action.type==='friend'){
      if(accept) await acceptFriendRequest(action.requestId,action.fromUserId,true);
      else await declineFriendRequest(action.requestId);
    }
  }catch(e){ console.error(e); }
  dismissMessageFromCenter(itemId);
  refreshMessageCenter(true);
}
function messageRequestRef(body){
  const match=String(body||'').match(/\[wc-request:(challenge|game|bug):([^\]]+)\]/);
  return match && match[2] ? {kind:match[1],id:match[2]} : null;
}
async function openAdminRequestModal(kind,id){
  if(!currentUser?.is_admin||!sb||!id) return;
  const source=kind==='challenge'?'custom_challenges':kind==='game'?'game_suggestions':'bug_reports';
  const {data,error}=await sb.from(source).select('*').eq('id',id).maybeSingle();
  if(error||!data){ showAlert('Diese Anfrage ist nicht mehr verfügbar.'); return; }
  let modal=document.getElementById('admin-request-modal');
  if(!modal){ modal=document.createElement('div');modal.id='admin-request-modal';modal.className='member-modal-backdrop hidden';modal.onclick=e=>{if(e.target===modal)modal.classList.add('hidden');};document.body.appendChild(modal); }
  const title=kind==='challenge'?'Challenge-Freigabe':kind==='game'?'Spielvorschlag':'Bug-Report';
  const author=kind==='challenge'?data.created_by_name:kind==='game'?data.suggested_by_name:data.reporter_name;
  const body=kind==='challenge'?`${GAME_NAME[data.game_id]||data.game_id} · ${DIFF_LABEL[data.diff]||data.diff}\n${data.text}`:kind==='game'?`${data.game_name}\n${data.description||'Keine zusätzliche Beschreibung.'}`:`${data.title}\n${data.body}`;
  const reward=kind==='bug'?'<input id="admin-request-reward" type="number" min="0" max="500" value="0" placeholder="Danke-Coins">':'';
  const actions=kind==='bug'?'<button class="roll-btn" onclick="resolveAdminRequest(\''+kind+'\',\''+id+'\',\'reviewed\')">Antwort senden</button><button class="sb-btn" onclick="resolveAdminRequest(\''+kind+'\',\''+id+'\',\'fixed\')">Als behoben markieren</button>':'<button class="roll-btn" onclick="resolveAdminRequest(\''+kind+'\',\''+id+'\',\'approved\')">Freigeben</button><button class="sb-btn danger" onclick="resolveAdminRequest(\''+kind+'\',\''+id+'\',\'rejected\')">Ablehnen</button>';
  modal.innerHTML=`<div class="member-modal-card" onclick="event.stopPropagation();" style="max-width:640px;"><button class="member-modal-close" onclick="document.getElementById('admin-request-modal').classList.add('hidden')">✕</button><div class="setup-step-head" style="justify-content:center;"><div class="setup-step-title">${title}</div></div><p class="setup-info" style="white-space:pre-wrap;margin:0 4px 12px;"><strong>von ${messageEscape(author||'Spieler')}</strong>\n${messageEscape(body)}</p><textarea id="admin-request-feedback" rows="3" maxlength="800" placeholder="Antwort an ${messageEscape(author||'Spieler')}"></textarea>${reward}<div class="filter-row" style="margin-top:12px;">${actions}</div></div>`;
  modal.classList.remove('hidden');
}
async function resolveAdminRequest(kind,id,action){
  if(!currentUser?.is_admin||!sb) return;
  const feedback=document.getElementById('admin-request-feedback')?.value.trim()||'';
  const modal=document.getElementById('admin-request-modal');
  let targetId=null, message='';
  if(kind==='challenge'){
    const {data}=await sb.from('custom_challenges').select('created_by,game_id').eq('id',id).maybeSingle(); targetId=data?.created_by;
    const result=action==='approved'?await sb.from('custom_challenges').update({approved:true}).eq('id',id):await sb.from('custom_challenges').delete().eq('id',id);
    if(result.error){showAlert('Antwort konnte nicht gespeichert werden: '+result.error.message);return;}
    message=action==='approved'?'Deine Challenge wurde freigegeben.':'Deine Challenge wurde abgelehnt.';
  } else if(kind==='game'){
    const {data,error}=await sb.from('game_suggestions').update({status:action,admin_feedback:feedback}).eq('id',id).select('suggested_by,game_name').maybeSingle(); if(error){showAlert('Antwort konnte nicht gespeichert werden: '+error.message);return;} targetId=data?.suggested_by;message=action==='approved'?`Dein Spielvorschlag „${data?.game_name||''}“ wird hinzugefügt.`:`Dein Spielvorschlag „${data?.game_name||''}“ wird nicht umgesetzt.`;
  } else {
    const reward=Math.max(0,Math.min(500,parseInt(document.getElementById('admin-request-reward')?.value,10)||0));
    const {data,error}=await sb.from('bug_reports').update({status:action,admin_feedback:feedback,reward_coins:reward||null,rewarded:reward>0}).eq('id',id).select('reporter_id,title').maybeSingle(); if(error){showAlert('Antwort konnte nicht gespeichert werden: '+error.message);return;} targetId=data?.reporter_id;message=`Antwort zu deinem Bug-Report „${data?.title||''}“: ${feedback||bugStatusLabel(action)}${reward?` · +${reward} Shop-Coins`:''}`;
    if(reward&&targetId){ const {data:p}=await sb.from('profiles').select('admin_bonus_points').eq('id',targetId).maybeSingle(); await sb.from('profiles').update({admin_bonus_points:(p?.admin_bonus_points||0)+reward}).eq('id',targetId); }
  }
  if(targetId) await sb.from('player_notifications').insert({target_user_id:targetId,from_user_id:currentUser.id,icon:action==='approved'||action==='fixed'?'✅':'✉',message:feedback?`${message} — ${feedback}`:message});
  modal?.classList.add('hidden'); showToast('Antwort gespeichert und versendet.','✅'); refreshMessageCenter(true);
}
async function renderMessageCenter(){
  ensureMessageCenterView();
  const admin=document.getElementById('message-center-admin');
  if(admin){
    if(currentUser?.is_admin && sb){
      const {data}=await sb.from('profiles').select('id,username').order('username');
      admin.innerHTML=`<details class="hero-avatar-group message-admin-toggle"><summary>📢 Ankündigung / Patch-Notiz verfassen</summary><div class="settings-card message-admin" style="border:0;border-radius:0;margin:0;"><p class="setup-info" style="margin-top:0;">Direkt an eine Person oder als News für alle.</p><div class="form-row"><select id="message-recipient"><option value="">An alle Spieler</option>${(data||[]).filter(p=>p.id!==currentUser.id).map(p=>`<option value="${p.id}">${messageEscape(p.username)}</option>`).join('')}</select><select id="message-category"><option value="news">Neuigkeiten</option><option value="patch">Patch</option><option value="bugfix">Bugfix</option><option value="games">Spiele</option><option value="challenges">Challenges</option><option value="shop">Shop</option></select></div><input id="message-title" maxlength="90" placeholder="Titel"><textarea id="message-body" maxlength="1500" placeholder="Was ist neu?" rows="4"></textarea><button class="roll-btn" onclick="sendAdminMessage()">Veröffentlichen</button></div></details>`;
    } else admin.innerHTML='';
  }
  await refreshMessageCenter(true);
  setMessagesRead();
  ensureMessageCenterLive();
}
async function sendAdminMessage(){
  if(!currentUser?.is_admin || !sb) return;
  const recipient=document.getElementById('message-recipient')?.value||null;
  const title=document.getElementById('message-title')?.value.trim(); const body=document.getElementById('message-body')?.value.trim();
  if(!title||!body){ showAlert('Bitte Titel und Nachricht ausfüllen.'); return; }
  const category=recipient?'direct':(document.getElementById('message-category')?.value||'news');
  const {error}=await sb.from('app_messages').insert({author_id:currentUser.id,recipient_id:recipient,category,title,body});
  if(error){ showAlert('Nachricht konnte nicht gesendet werden: '+error.message); return; }
  showToast('Nachricht veröffentlicht.',''); document.getElementById('message-title').value=''; document.getElementById('message-body').value=''; refreshMessageCenter(true);
}
async function sendMessageReply(messageId, form){
  if(!currentUser||!sb) return;
  const input=form.querySelector('input'); const body=input?.value.trim(); if(!body) return;
  const {error}=await sb.from('app_message_replies').insert({message_id:messageId,author_id:currentUser.id,body});
  if(error){ showAlert('Antwort konnte nicht gesendet werden: '+error.message); return; }
  input.value=''; refreshMessageCenter(true);
}
