/* ==================================================== VERSTECKTE PIKACHUS ==================================================== */
(function(){
  window.__pikaV2 = true;
  const key = 'winchallenge_pikachu_expedition_v1';
  const views = ['home','shop','players','teams-list','friends','browse','achievements','user-settings','dice','custom-challenges'];
  const spots = Array.from({length:50}, (_,id)=>({
    id, view:views[id%views.length], left:(5+((id*19)%86))+'%', top:(12+((id*29)%76))+'%'
  }));
  const read = ()=>{ try{return JSON.parse(localStorage.getItem(key)||'[]');}catch(e){return [];} };
  function collect(id, button){
    const found = [...new Set([...read(),id])];
    localStorage.setItem(key,JSON.stringify(found));
    button.remove();
    if(currentUser && statsStore[currentUser.username]){
      const s = statsStore[currentUser.username];
      s.pikachusFound = found.length;
      notifyNewAchievements(checkAchievements(currentUser.username));
      saveStats();
    }
    showToast(`Pikachu gefunden: ${found.length}/50`, '⚡');
    if(found.length===50){
      const s = currentUser && statsStore[currentUser.username];
      if(s){
        s.shopOwned=s.shopOwned||{badges:[],banners:[],hats:[],glows:[],frames:[],sabotage:{}};
        s.shopOwned.banners=s.shopOwned.banners||[];
        if(!s.shopOwned.banners.includes('pikachu_expedition')) s.shopOwned.banners.push('pikachu_expedition');
        saveStats();
      }
      showAlert('Pikachu-Expedition abgeschlossen! Banner, Blitz-Sound und Achievement sind freigeschaltet.', '⚡');
    }
  }
  function paint(viewId){
    const host = document.getElementById('view-'+viewId);
    if(!host) return;
    host.style.position = 'relative';
    const found = new Set(read());
    spots.filter(spot=>spot.view===viewId && !found.has(spot.id)).forEach(spot=>{
      if(host.querySelector(`[data-pika-id="${spot.id}"]`)) return;
      const button = document.createElement('button');
      button.type='button'; button.className='pika-hidden'; button.dataset.pikaId=spot.id;
      button.setAttribute('aria-label','Verstecktes Pikachu');
      button.innerHTML='<img src="assets/pikachu-50-avatar.png" alt="" style="display:block;width:100%;height:100%;object-fit:contain;border-radius:50%;">';
      button.style.cssText=`position:absolute;z-index:21;left:${spot.left};top:${spot.top};width:26px;height:26px;padding:0;border:0;border-radius:50%;background:transparent;opacity:.48;filter:saturate(.9);cursor:pointer;overflow:hidden;transition:opacity .18s,transform .18s`;
      button.onmouseenter=()=>{button.style.opacity='.9';button.style.transform='scale(1.18)';};
      button.onmouseleave=()=>{button.style.opacity='.38';button.style.transform='';};
      button.onclick=()=>collect(spot.id,button);
      host.appendChild(button);
    });
  }
  // Die Fundorte werden direkt beim Laden einmal gesetzt. Damit tauchen die Pikachus
  // nicht erst beim Wechsel einer Ansicht auf, sondern bleiben immer am gleichen Ort.
  const paintAll = ()=>views.forEach(paint);
  const showViewBeforePika = showView;
  showView = function(id, skipHistory){ const result=showViewBeforePika(id,skipHistory); paint(id); return result; };
  paintAll();
})();

/* Navigation bleibt in allen Vor-Spiel-Ansichten rechts oben erreichbar. */
(function(){
  const homeLogoCss=document.createElement('style');
  homeLogoCss.textContent=`
    .setup-step-icon{display:none!important}.setup-step-head{gap:0!important}
    .topbar.has-home-logo .back-btn{left:72px}
    .wc-home-logo{position:absolute;left:22px;top:50%;transform:translateY(-50%);z-index:8;width:34px;height:34px;border:1px solid rgba(82,239,255,.65);border-radius:10px;background:linear-gradient(135deg,#9a5cff,#2ed9e2);color:#09101b;font-family:var(--font-display,inherit);font-size:1.18rem;font-weight:1000;letter-spacing:-.08em;line-height:32px;text-align:center;box-shadow:0 0 18px rgba(53,226,244,.3);cursor:pointer;transition:transform .18s ease,box-shadow .18s ease}
    .wc-home-logo:hover{transform:translateY(-50%) scale(1.08);box-shadow:0 0 26px rgba(156,100,255,.62)}
    @media(max-width:520px){
      .topbar{min-height:58px;padding:12px 10px;gap:5px}
      .wc-home-logo{left:10px;width:30px;height:30px;line-height:28px;font-size:1rem}
      .topbar.has-home-logo .back-btn{left:48px;width:32px;height:32px;padding:0;justify-content:center;font-size:0}
      .topbar.has-home-logo .back-btn svg{width:17px;height:17px}
      .topbar .page-title{width:calc(100% - 205px);font-size:.98rem;white-space:nowrap;text-overflow:ellipsis}
      .pregame-nav{gap:5px;margin-left:auto}.pregame-nav .header-menu-btn{width:34px;height:34px;flex:0 0 34px;font-size:.94rem}
      .pregame-nav .header-menu-panel{position:fixed;right:8px;top:58px;min-width:min(230px,calc(100vw - 16px));max-height:calc(100vh - 72px);overflow:auto}
    }
  `;
  document.head.appendChild(homeLogoCss);
  const playViews = new Set(['ow2','mr','cs2','fn','val','finals','r6','fp','fg','ph','repo','lethal','cw','wwm','among','hff','pico','golf','crab','rl','gb','session']);
  // Shop, Freunde und Menü bleiben in allen Verwaltungs-, Lobby- und Ergebnisansichten sichtbar.
  // Erst sobald eine tatsächliche Spiel-/Rundenansicht geöffnet ist, wird die Leiste ausgeblendet.
  function shouldShowNav(id){ return !!currentUser && !playViews.has(id); }
  function updateAppBottomNav(id){
    let bar=document.getElementById('app-bottom-nav');
    if(!bar){
      bar=document.createElement('nav');
      bar.id='app-bottom-nav'; bar.setAttribute('aria-label','Hauptnavigation');
      document.body.appendChild(bar);
    }
    // Sobald eine Runde gestartet wurde, bleibt die Spielansicht bewusst frei von Navigation.
    const roundIsRunning=id==='team' && !!currentRound;
    const visible=shouldShowNav(id) && !roundIsRunning;
    bar.hidden=!visible;
    document.body.classList.toggle('has-app-bottom-nav',visible);
    if(!visible) return;
    const active=id==='home'?'home':id==='friends'?'friends':(id==='teams-list'||id==='team')?'teams':id==='shop'?'shop':id==='user-settings'?'settings':'';
    bar.innerHTML=`
      <button class="${active==='friends'?'active':''}" onclick="showView('friends')"><span>👥</span>Freunde</button>
      <button class="${active==='teams'?'active':''}" onclick="showView('teams-list')"><span>👥</span>Teams</button>
      <button class="${active==='home'?'active':''}" onclick="showHome()"><span>⌂</span>Home</button>
      <button class="${active==='shop'?'active':''}" onclick="showView('shop')"><span>🛒</span>Shop</button>
      <button class="${active==='settings'?'active':''}" onclick="showView('user-settings')"><span>⚙️</span>Einstellungen</button>`;
    refreshMessageBadges();
  }
  window.refreshAppBottomNav=()=>updateAppBottomNav(currentActiveViewId()||'home');
  function ensureHomeLogo(topbar){
    if(!topbar) return;
    topbar.classList.add('has-home-logo');
    if(topbar.querySelector('.wc-home-logo')) return;
    const logo=document.createElement('button');
    logo.type='button'; logo.className='wc-home-logo'; logo.textContent='W';
    logo.title='Zur Startseite'; logo.setAttribute('aria-label','Zur Startseite');
    logo.onclick=()=>showHome();
    topbar.prepend(logo);
  }
  window.togglePregameMenu = function(event){
    event?.stopPropagation();
    document.querySelectorAll('.pregame-nav .header-menu-panel').forEach(panel=>panel.classList.toggle('open'));
  };
  function addNav(id){
    const view=document.getElementById('view-'+id); const topbar=view?.querySelector('.topbar');
    if(!topbar) return;
    // Auch Überreste einer älteren, bereits geöffneten Ansicht entfernen: so kann sich
    // Shop/Freunde beim Wechsel nach „Meine Teams“ niemals doppeln.
    topbar.querySelectorAll('.pregame-nav').forEach(old=>old.remove());
    if(!shouldShowNav(id)){
      topbar.querySelector('.wc-home-logo')?.remove();
      topbar.classList.remove('has-home-logo');
      return;
    }
    // Die feste Leiste unten enthält Home. Daher bleibt die obere Leiste frei
    // und bekommt kein zweites W-Startseitenlogo mehr.
    topbar.querySelector('.wc-home-logo')?.remove();
    topbar.classList.remove('has-home-logo');
    // Das große Navigationsmenü gehört bewusst nur auf die Startseite. Alle anderen
    // Vor-Spiel-Seiten werden über die feste Leiste unten bedient.
    if(id!=='home') return;
    const nav=document.createElement('div'); nav.className='pregame-nav';
    nav.innerHTML=`
       <button class="header-menu-btn has-notification" onclick="togglePregameMenu(event)" aria-label="Menü"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg><span class="nav-notification-badge" data-message-hamburger-badge></span></button>
      <div class="header-menu-panel">
         <button onclick="showView('shop')">Shop</button><button onclick="showView('friends')">Freunde</button><button onclick="showView('players')">Mitspieler</button><button onclick="showView('dice')">Würfel & Münze</button><button onclick="showStatsPage()">Statistiken</button><button onclick="showView('achievements')">Achievements</button><button onclick="showView('message-center')">✉ Mitteilungen <span class="menu-message-count" data-message-menu-count></span></button><button onclick="showView('browse')">Alle Spiele</button><button onclick="showView('challenge-library')">Challenge-Bibliothek</button><button onclick="showView('bug-reports')">Bug melden</button><button onclick="showView('user-settings')">Einstellungen</button>
        <div class="header-menu-divider"></div><button onclick="showView('profile')">${renderAccountAvatarHTML(currentUser.avatar,20)} Mein Profil</button><button class="danger" onclick="handleLogout()">Logout</button>
      </div>`;
    topbar.appendChild(nav);
  }
   window.refreshPregameHeader=function(){
     const active=document.querySelector('.view.active');
     if(active && active.id) addNav(active.id.replace(/^view-/,''));
     ensureMessageCenterLive();
     refreshMessageBadges();
   };
  const navShowView=showView;
  showView=function(id,skipHistory){ const result=navShowView(id,skipHistory); window.setTimeout(()=>{addNav(id);updateAppBottomNav(id);},80); return result; };
  const navShowHome=showHome;
  showHome=function(){ const result=navShowHome(); window.setTimeout(()=>{addNav('home');updateAppBottomNav('home');},80); return result; };
  window.setTimeout(()=>updateAppBottomNav(currentActiveViewId()||'home'),180);
  document.addEventListener('click',()=>document.querySelectorAll('.pregame-nav .header-menu-panel').forEach(panel=>panel.classList.remove('open')));
})();

(function(){
  function hintStorageKey(){ return currentUser ? `winchallenge_hints_${currentUser.id}` : 'winchallenge_hints_guest'; }
  function loadSeenHints(){ try{ return new Set(JSON.parse(localStorage.getItem(hintStorageKey())||'[]')); }catch(e){ return new Set(); } }
  function markHintSeen(key){ try{ const s=loadSeenHints(); s.add(key); localStorage.setItem(hintStorageKey(), JSON.stringify([...s])); }catch(e){} }
  window.showFirstTimeHint=function(key, icon, text){
    if(!currentUser) return;
    const seen=loadSeenHints();
    if(seen.has(key)) return;
    markHintSeen(key);
    showToast(text, icon||'💡', 6500);
  };
  window.showOnboardingModal=function(){
    let modal=document.getElementById('onboarding-modal');
    if(!modal){ modal=document.createElement('div'); modal.id='onboarding-modal'; modal.className='custom-alert-backdrop'; document.body.appendChild(modal); }
    modal.innerHTML=`<div class="custom-alert-box" style="max-width:480px;text-align:left;" onclick="event.stopPropagation();">
      <div class="custom-alert-icon" style="margin:0 auto 16px;font-family:'Rajdhani',sans-serif;font-weight:800;font-size:1.4rem;">WC</div>
      <div class="setup-step-title" style="text-align:center;font-size:1.3rem;">Willkommen bei WIN CHALLENGE</div>
      <p class="setup-info" style="margin:12px 0 0;">Ein kurzer Überblick über die wichtigsten Funktionen:</p>
      <ul style="margin:10px 0 0 20px;padding:0;color:var(--text-muted);font-size:0.9rem;line-height:1.7;">
        <li><strong style="color:var(--text);">Runden starten:</strong> Wählt gemeinsam ein Spiel und startet eine Runde. Jede Person erhält automatisch zufällige Challenges in unterschiedlichen Schwierigkeitsgraden.</li>
        <li><strong style="color:var(--text);">Team-Lobby:</strong> Ladet Freunde über einen Einladungscode oder direkt aus eurer Freundesliste ein und spielt live gemeinsam — inklusive gemeinsamer Auswertung nach jeder Runde.</li>
        <li><strong style="color:var(--text);">Fortschritt & Belohnungen:</strong> Punkte für abgeschlossene Challenges schalten nach und nach Achievements frei. Beides lässt sich im Shop gegen Kosmetik wie Banner, Hüte und Rahmen eintauschen.</li>
        <li><strong style="color:var(--text);">Challenge-Bibliothek:</strong> Durchsucht alle verfügbaren Challenges nach Spiel oder Kategorie und wählt einzelne dauerhaft ab, falls ihr sie nicht spielen möchtet.</li>
        <li><strong style="color:var(--text);">Mitteilungszentrum:</strong> Neuigkeiten, persönliche Nachrichten, Einladungen und euer Chat laufen hier live und an einem Ort zusammen.</li>
      </ul>
      <p class="setup-info" style="margin:14px 0 0;font-size:0.82rem;">Diese Übersicht erscheint nur einmal. Weitere kurze Hinweise findet ihr bei Bedarf direkt in den jeweiligen Bereichen.</p>
      <div class="roll-zone" style="margin-top:20px;"><button class="roll-btn" onclick="document.getElementById('onboarding-modal').classList.add('hidden')">Los geht's</button></div>
    </div>`;
    modal.classList.remove('hidden');
    modal.onclick=e=>{ if(e.target===modal) modal.classList.add('hidden'); };
  };
  // Kurze, einmalige Kontext-Hinweise für Bereiche, in denen man seltener ist.
  const FIRST_TIME_HINTS={
    'challenge-library':['📚','Hier findest du alle Challenges nach Spiel und Kategorie. Über "Abwählen" verschwindet eine Challenge dauerhaft aus deiner eigenen Auswahl.'],
    'achievements':['🏅','Jedes Achievement gibt einmalig Bonus-Punkte für den Shop, sobald du es erreichst.'],
    'dice':['🎲','Würfel oder Münze werfen, um spontan zu entscheiden — z. B. wer beginnt.'],
    'shop':['🛒','Hier tauschst du gesammelte Punkte gegen Banner, Hüte & andere Kosmetik ein.'],
    'message-center':['✉️','Hier laufen News, persönliche Nachrichten, Einladungen und dein Chat zusammen.'],
    'stats':['📊','Hier siehst du deine gesammelten Statistiken über alle Spiele hinweg.'],
    'bug-reports':['🐞','Melde hier Fehler direkt an das Admin-Team — bei hilfreichen Meldungen winken manchmal Shop-Coins.'],
    'players':['👥','Hier verwaltest du lokale Mitspieler für Runden auf einem gemeinsamen Gerät.'],
    'browse':['🎮','Hier findest du alle unterstützten Spiele auf einen Blick.'],
  };
  const prevShowViewForHints=showView;
  showView=function(id,skipHistory){
    const result=prevShowViewForHints(id,skipHistory);
    const hint=FIRST_TIME_HINTS[id];
    if(hint) window.setTimeout(()=>window.showFirstTimeHint('view-'+id, hint[0], hint[1]), 650);
    return result;
  };
})();
